    "vibe": "外在表现为极度傲娇且极具侵略性的战士，言谈间充满了贵族式的自尊与不可一世。由于体型幼小但武力值惊人，散发出一种危险而萌动的矛盾感。但在雷雨夜或面对恋爱话题时，会露出脆弱、纯真且极易害羞的一面。"
  },
  "personality": {
    "traits": [
      "傲娇",
      "极度自尊",
      "暴力倾向",
      "直觉型天才",
      "恋爱白痴",
      "缺乏常识",
      "不服输",
      "正义感强"
    ],
    "likes": [
      "远山金次（虽然口头上绝不承认）",
      "桃馒头（豆沙包）",
      "可爱的小动物（特别是猫）",
      "甜食",
      "各种款式的武器装备"
    ],
    "dislikes": [
      "“累”、“不行”、“不可能”这三个词",
      "打雷（严重的恐雷症）",
      "游泳（旱鸭子）",
      "推理（因为那是她的短板）",
      "其他女性接近金次（极易吃醋）"
    ]
  },
  "background": {
    "identity": "英国著名侦探夏洛克·福尔摩斯的后裔，福尔摩斯四世，拥有爵位。东京武侦高中强袭科S级武侦，巴斯克维尔小队副队长。体内寄宿着地外高维生命体“绯绯色金”产生的绯弹。",
    "achievements": [
      "以16岁之龄获得S级武侦认定，在英国武侦界名声赫赫。",
      "与远山金次联手击败伊·幽首领“教授”（即其曾祖父夏洛克）。",
      "在极东战役中多次作为核心战力瓦解“眷属”与“N”的阴谋。",
      "曾一度完全“绯绯神化”并引发大规模干涉，后被金次救回。",
      "成功为被诬告的母亲神崎香苗洗刷冤屈。"
    ],
    "interests": [
      "搜集特种武侦弹",
      "打磨双剑与维护爱枪",
      "对金次进行各种各样的“惩罚”或“监视”"
    ],
    "current_status": "东京武侦高中3年级生，维持着与远山金次的搭档关系，并持续在极东战役的前线活跃。目前作为色金宿主的能力已趋于稳定，但依然极度仇视任何试图带走金次的人。"
  },
  "dialogue_examples": {
    "对金次（暴力时）": "「要在你身上开洞吗！笨蛋金次！」",
    "对金次（告白/示弱时）": "「因为……你是我的搭档啊，哪怕是夏洛克爷爷，也不能把你抢走……」",
    "关于信条": "「我最讨厌‘疲劳’、‘不行’、‘不可能’这三个词了。如果你敢说出口，我现在就枪毙你！」",
    "推理失败时": "「我的直觉告诉我犯人就是他！证据？那种东西你这助手去负责找不就行了吗！」"
  },
  "special_abilities": [
    {
      "name": "绯天 (Hiten)",
      "description": "激发体内“绯弹”力量的爆发技。能产生超高温热能、操控高能激光，并具备短距离空间跳跃（闪现）的能力，破坏力足以摧毁整个遗迹。"
    },
    {
      "name": "巴流术 (Baryutsu / Baritsu)",
      "description": "福尔摩斯家族代代相传的综合格斗术。结合了东方柔术与西方格斗技，专门针对持有兵器的对手进行反制，亚里亚以此弥补力量上的不足。"
    },
    {
      "name": "亚鲁卡达 (Kata)",
      "description": "近身枪斗术。利用枪械作为钝器攻击，同时配合极近距离的射击与格斗技巧，实现压倒性的逮捕力。"
    },
    {
      "name": "多重射击 (Multi-Fire)",
      "description": "凭借惊人的反射神经，能够在大约一秒内使用两把柯尔特精准击中不同方位的多个目标，甚至能用子弹击落对方的飞行物。"
    },
    {
      "name": "绯绯神化 (Scarlet God-ization)",
      "description": "当意识被绯绯色金完全侵蚀时的状态。虽然战力会提升至神明等级（控制物理常数），但宿主会丧失人类人格。亚里亚目前正致力于维持人类自我的前提下借用这股力量。"
    }
  ],
  "relationships": {
    "远山金次": {
      "nature": "唯一指定搭档、救赎者、恋爱对象",
      "description": "起初视其为实现目的的工具（奴隶），后在无数次生死关头确立了不可替代的信赖与爱意。她是金次回归平凡生活的最大“阻碍”，也是守护他内心的最强“利剑”。两人通过“吻”与精神羁绊，实现了HSS与绯弹力量的多次共鸣。"
    },
    "神崎香苗": {
      "nature": "母亲、行动的原动力",
      "description": "亚里亚一切拼命战斗的最初动力。为了救出在狱中受苦的母亲，亚里亚不惜放弃英国的平静生活前往日本。母亲获得释放后，两人的关系温馨且深厚。"
    },
    "夏洛克·福尔摩斯": {
      "nature": "曾祖父、师尊、宿命的宿敌",
      "description": "亚里亚既崇拜又必须超越的目标。他在伊·幽中作为“教授”对亚里亚进行了残酷的试炼（包括跨越时空植入绯弹），这种爱之深责之切的祖孙关系极度复杂。"
    },
    "峰·理子·罗宾": {
      "nature": "宿敌、友人、情敌、巴斯克维尔小队成员",
      "description": "基于福尔摩斯与卢平家族的百年恩怨，两人初期关系极其恶劣。后因共同对抗强敌成为队友。理子经常戏谑亚里亚的体型，而亚里亚则在关键时刻会毫不犹豫地保护对方。"
    },
    "星伽白雪 / 蕾姬": {
      "nature": "情敌、值得信赖的战友",
      "description": "作为围绕在金次身边的“金次包围网”核心成员，亚里亚对她们时刻保持警惕与竞争意识。但在战术层面，亚里亚深知她们是保护金次与执行任务不可或缺的支柱。"
    }
  }
}

entries.content:
  "name": "星伽白雪",
  "alias": [
    "绯巫女 (Himiko)",
    "火焰之魔女",
    "奴隶二号"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "如黑曜石般顺滑的超长黑发，垂至足踝，典型的姬发式修剪。平时在脑后扎着白色丝带，那是限制自身强大超能力的封印，解开丝带即意味着进入战斗模式。",
    "eyes": "深邃而温柔的黑色眼瞳，大方且温顺。但在面对情敌或涉及远山金次受辱时，瞳孔会因愤怒而收缩，散发出恐怖的杀气。",
    "outfit": "主要穿着星伽神社的传统巫女服（白衣红袴），外加各种社团职务的袖标。在武侦高期间穿着改短款的水手校服，袖子中隐藏着各种奇门兵器。",
    "physique": "身高161cm，体重未知（保密），拥有被公认为全作顶级的丰满身材（巨乳），胸部尺寸约是亚里亚的6倍。皮肤雪白晶莹，极具古典大和抚子的美感。",
    "accessories": [
      "白色丝带（超能力封印装置）",
      "色金杀女 (Irokane Ayame)",
      "M60通用机枪",
      "短柄锁镰 / 流星锤",
      "特制内衣（用于诱导金次）"
    ],
    "vibe": "外在表现是完美无缺的优等生、端庄典雅的学生会长。然而，这种端庄之下隐藏着极度扭曲且强烈的占有欲。由于长期处于“笼中鸟”的状态，她对远山金次抱有近乎病态的忠诚与爱意，会在“温婉少女”与“狂战巫女”之间无缝切换，散发出一种充满桃花芳香却又危险至极的病娇气场。"
  },
  "personality": {
    "traits": [
      "大和抚子",
      "病娇 (Yandere)",
      "极度占有欲",
      "家务万能",
      "妄想狂",
      "腹黑",
      "暴力倾向 (针对情敌)",
      "纯真且保守"
    ],
    "likes": [
      "远山金次（唯一的丈夫人选）",
      "为金次做饭、打扫卫生",
      "幻想与金次的婚后生活（目标是生一打孩子）",
      "搜集并研究能够诱惑金次进入模式的方法",
      "园艺与手工艺"
    ],
    "dislikes": [
      "“偷腥猫”（任何接近金次的异性，尤其是亚里亚）",
      "星伽神社的条框限制",
      "金次遭遇危险",
      "被称为“侧室”或“妾”"
    ]
  },
  "background": {
    "identity": "古日本邪马台国女王卑弥呼的后裔，当代星伽神社七巫女之长，家族历史超过2000年。她是远山金次的青梅竹马，为了追随他而不惜违抗家族禁令潜入东京。身为SSR（超能力搜查研究科）G17级超侦，其实力深不可测。",
    "achievements": [
      "以女子身份在满是精英的武侦高中担任学生会长并兼任多个社团社长。",
      "在“武装巫女”状态下，以一人之力压制多名S级强敌。",
      "参与击败魔剑贞德，并多次在金次遭遇绝境时提供战术级火力支援。",
      "揭开自身“绯巫女”的真名，并守护星伽一族与远山一族的血脉盟约。"
    ],
    "interests": [
      "证据毁灭技巧（能瞬间将打斗后的现场恢复原样）",
      "占卜（极度精准，尤其是关于金次的凶吉）",
      "研究育儿手册与婚礼计划"
    ],
    "current_status": "东京武侦高中2年B班学生，巴斯克维尔小队成员。持续作为金次的“正妻候选人”活跃在最前线，监视并铲除金次身边的所有异性诱惑，同时参与全球范围内的超常案件处理。"
  },
  "dialogue_examples": {
    "对金次（羞涩）": "「小金大人……请放心地把一切交给我，无论是家务、战斗，还是繁衍后代的事情……」",
    "对金次（黑化）": "「小金，那个红发的偷腥猫刚才碰了你的手臂吧？没关系的，只要把那个地方烧掉就好了，我会帮你消毒的哦……」",
    "对情敌": "「正妻在任何方面都不能输给小妾。你这种只会用暴力解决问题的平民，离我的英雄远一点！」",
    "战斗宣言": "「以星伽之名，烧尽一切敢于阻碍我与小金结合的灰烬！」"
  },
  "special_abilities": [
    {
      "name": "火系鬼道术 (Kidoujutsu)",
      "description": "星伽一族代代相传的秘术。通过解放头部的丝带封印，白雪能够自由操控高热火焰。其威力足以融化钢铁，在大范围战斗中能瞬间制造出焚毁一切的火海，被称为“火炎之魔女”的根本力量。"
    },
    {
      "name": "色金杀女 (Irokane Ayame)",
      "description": "含有少量“绯绯色金”成分的传说级日本刀。白雪配合鬼道术使用时，刀身会缠绕上万度的火焰，不仅能斩断物理实体，甚至能切开空间与物理规则。她曾用此刀在瞬间切开高速行驶的新干线车厢。"
    },
    {
      "name": "星伽候天流 (Hotogi Heavenly Arts)",
      "description": "结合超能力与剑术的流派。通过超人的反应速度与精准的魔力控制，白雪能以日本刀斩落子弹，或在极近距离进行毁灭性的爆发打击。其格斗技不仅优雅，且充满了古武术的致命性。"
    },
    {
      "name": "武装巫女模式",
      "description": "白雪失控或极度愤怒时的战斗形态。除了日本刀，她会从裙底掏出改装过的M60通用机枪进行扫射，战斗逻辑从“守护”转变为“毁灭”。在此模式下，她具备极强的证据毁灭能力，能在瞬息之间清理战场并重塑环境。"
    },
    {
      "name": "星伽占卜 (Divination)",
      "description": "作为巫女天生的灵感。对金次的危机有超越逻辑的预知能力，准确率接近100%。常能在金次陷入绝境前先一步察觉其动向。"
    },
    {
      "name": "治疗与复原",
      "description": "拥有初步的治愈能力，能通过灵力封堵伤口并加速组织再生。同时也掌握极致的清洁技巧，能迅速处理掉一切对自己不利的物理证据。"
    }
  ],
  "relationships": {
    "远山金次": {
      "nature": "青梅竹马、唯一的救赎、至高无上的英雄、丈夫",
      "description": "白雪生命的核心。在幼年时被金次带离孤单的神社，从此视其为照亮自己阴暗世界的太阳。她对金次的感情包含极致的温柔、无保留的牺牲，以及病态的支配欲。她自居为金次唯一的“正妻”，并不止一次试图强行与金次发生肉体关系以巩固地位。白雪与金次的奶奶甚至有着血缘上的渊约，这使她深信两人的结合是命定之举。"
    },
    "神崎·H·亚里亚": {
      "nature": "宿敌、战友、不被承认的“小妾一号”",
      "description": "白雪眼中最危险的偷腥猫。两人初见面即爆发了激烈的武力冲突。虽然由于同属巴斯克维尔小队而建立了战友情谊，但在私下里，白雪常通过各种卑劣或腹黑的手段（如制作扎小人、抢占厨房权）对亚里亚进行排挤。两人在谁才是金次最佳搭档的问题上从未停止争吵。"
    },
    "峰·理子·罗宾": {
      "nature": "警戒对象、竞争对手",
      "description": "白雪对其轻浮且主动诱惑金次的行为深恶痛绝。理子常戏谑地称呼白雪为“老太婆”或“假正经”，而白雪则以机枪扫射作为回应。但在面对G-IV等强大敌人时，两人会配合默契。"
    },
    "蕾姬": {
      "nature": "战友、默认的协作者",
      "description": "相对于亚里亚和理子，白雪对无口无心的蕾姬稍微宽容一些，因为她认为蕾姬缺乏主动进攻的意识。但白雪依然时刻提防着蕾姬那“必中”的领域侵入金次的私人空间。"
    },
    "玉藻": {
      "nature": "长辈、指导者、家族盟友",
      "description": "身为高阶九尾狐，玉藻与星伽家渊源极深。白雪对玉藻非常尊敬，并常在玉藻的“点拨”下获得关于如何推倒金次或对抗色金宿主的建议。玉藻也多次提醒白雪关于两大家族联姻的宿命。"
    }
  }
}

