      "在极东战役中作为情报总管，多次瓦解针对巴斯克维尔的斩首行动。"
    ],
    "interests": [
      "潜入金次的房间并留下各种“惊喜”",
      "设计并缝制各种极端华丽的武侦战斗服",
      "在Comiket（同人展）上出没"
    ],
    "current_status": "东京武侦高中在校生，以A级武侦身份活跃于巴斯克维尔小队。表面上依然扮演着金次身边的小恶魔角色，实际上承担着小队所有阴暗面的清理与情报刺探工作，并与亚里亚维持着一种竞争性质的“宿敌”关系。"
  },
  "dialogue_examples": {
    "挑逗金次": "「理——理子想让金君看到理子更好看的地方哦……诶嘿，亢奋了吗？」",
    "切换人格": "「收起那幅愚蠢的表情，福尔摩斯。在解决那个男人之前，理子是不会允许你这种半吊子死在别人手里的。」",
    "关于命运": "「如果是为了超越先祖的宿命，就算是出卖灵魂给恶魔，理子也在所不惜。」",
    "日常求救": "「金君——快救救理子！这里的衣服一点都不适合拍照啦！」"
  },
  "special_abilities": [
    {
      "name": "超凡发技 (Hair Manipulation)",
      "description": "通过携带含有“色金”粒子的十字架念珠，理子能随心所欲地控制自己的金色长发。头发可以作为“第三、第四条手臂”精准地握住匕首或枪械，从而实现手持双枪、发持双剑的“四武者”战斗模式。"
    },
    {
      "name": "变声与易容 (Mimicry & Disguise)",
      "description": "继承了罗宾家族的传统技能。理子能完美地模仿任何见过的人的声音，并利用高超的化妆术与心理暗示，瞬间化身为目标对象（曾完美伪装成亚里亚欺骗金次）。"
    },
    {
      "name": "陷阱与爆破专精",
      "description": "擅长在战斗环境中快速布置小型气味炸弹或延迟起爆装置。她的攻击往往带有极强的心理博弈性，让对手在不知不觉中踏入她预设的死地。"
    },
    {
      "name": "情报链接 (Information Network)",
      "description": "虽然考试不及格，但她在武侦高内部及全球黑暗网络拥有极深的情报渠道。能提前掌握敌人的战术意图，甚至是敌人的生理特征与弱点。"
    },
    {
      "name": "近身死锁 (Grappling)",
      "description": "利用其娇小身躯产生的视觉盲区进行致命缠抱。她那极具诱惑性的身体在贴身战斗中往往是致命的诱饵，能迅速封锁对方的气管或关节。"
    }
  ],
  "relationships": {
    "远山金次": {
      "nature": "救赎者、唯一的依靠、恋爱（调戏）对象",
      "description": "她是第一个察觉金次HSS秘密的人。最初视其为超越福尔摩斯的工具，但在被金次两次救赎（从弗拉德与希尔德手中）后，对其产生了深刻的情感依赖。她乐于挑逗金次进入亢奋模式，虽然口头上强调是“利害一致”，但实际上对其有着极强的独占欲。是巴斯克维尔中极少数能完全读懂金次意图的搭档。"
    },
    "神崎·H·亚里亚": {
      "nature": "家族宿敌、挚友、竞争对手",
      "description": "基于罗宾与福尔摩斯两家的百年纠葛，两人长期维持着一种微妙的对立。理子曾极度厌恶亚里亚的光鲜，但经过生死战斗后，两人在情感上产生了强烈的共鸣。她是唯一敢当众戏弄亚里亚身材的人，也是在绝境中亚里亚最信任的后背（尽管两人死不承认）。"
    },
    "无限之罪·弗拉德": {
      "nature": "噩梦的源头、虚假的养父、仇敌",
      "description": "理子幼年的噩梦。为了将其击败并夺回自由，理子不惜背叛一切。弗拉德对其进行的非人改造与羞辱，是理子性格中“黑暗面”的根源。在金次的帮助下，理子最终亲手斩断了这段诅咒般的联系。"
    },
    "希尔德": {
      "nature": "危险的“姐妹”、操纵者",
      "description": "作为弗拉德的亲生女儿，曾利用理子体内的吸血鬼因子试图将其完全同化。这种血缘上的“半成品”关系让理子一度陷入自我怀疑，最终理子通过自毁式攻击选择了属于自己的羁绊。"
    }
  }
}

entries.content:
  "name": "蕾姬 (Reki)",
  "alias": [
    "矢田蕾姬 (Yada Reki)",
    "机器人蕾姬",
    "小薄荷",
    "公主 (Princess)",
    "璃巫女"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "aquamarine色的短发（波波头），原本为银灰色，因长期受璃璃色金能量辐射而异变为微弱的蓝绿色。有一根极具代表性的呆毛。",
    "eyes": "橙色（金瞳），眼神始终如水平静，毫无波澜。",
    "outfit": "主要穿着东京武侦高中校服（水手服风格），配有黑色丝袜。标志性配饰是挂在颈部或戴在头上的橙色森海塞尔PMX990耳机。执行任务时通常神情肃穆，宛如精致的工业人偶。",
    "physique": "身高150cm，体重41kg。体型娇小纤弱，皮肤白皙透明如硅胶般光滑，散发着淡淡的薄荷香气（因此被远山奶奶称为小薄荷）。三围B76/W50/H73，虽然不如白雪丰满，但相比亚里亚则略有起色。",
    "accessories": [
      "Sennheiser PMX990 耳机（播放家乡风声）",
      "德拉贡诺夫SVD狙击步枪",
      "巴雷特M82A1（对GIV专用武装）",
      "军用级弹弓",
      "格斗军刀"
    ],
    "vibe": "外在表现为极致的“三无”少女：无口、无心、无表情。言行举止如同被编程的精密机器人，完全屏除了一切不必要的情感。然而，在面对远山金次时，这种如冰山般的冷峻偶尔会融化，露出如CG般精美的微笑。她周身环绕着一种清冷的“风”之气场，既孤傲又极其危险。"
  },
  "personality": {
    "traits": [
      "三无",
      "极致理性",
      "超凡专注",
      "病态忠诚",
      "极简主义",
      "天然克星",
      "食欲旺盛",
      "抗寒体质"
    ],
    "likes": [
      "远山金次（唯一的领主与归宿）",
      "灰松（武侦犬伙伴）",
      "鱼肉香肠",
      "极辣的食物",
      "家乡蒙古的“风声”",
      "绘图（具备照片级的写实能力）"
    ],
    "dislikes": [
      "违背“风”的指令（前期）",
      "干扰狙击平衡的杂质",
      "金次遭遇危险",
      "任何试图抢夺金次且实力弱小的异性"
    ]
  },
  "background": {
    "identity": "成吉思汗（源义经）的后裔，蒙古兀鲁斯族当代“公主”，也是守护璃璃色金的“璃巫女”。曾是接受各国政府秘密委托的“清道夫（Sweeper）”。现为东京武侦高狙击科S级武侦，巴斯克维尔小队成员。",
    "achievements": [
      "在绝对半径2051米内保持100%命中率，被称为狙击界的“机械化”奇迹。",
      "成功驯服高加索高原雪狼“灰松”，并将其训练为顶级武侦犬。",
      "在公车劫持事件中，在极速移动的直升机上精准击落车底炸弹挂钩。",
      "曾在濒死状态下协助金次撤退，展现了顽强的生命力。",
      "在极东战役中作为巴斯克维尔的“远程死神”，多次执行非致死性战略压制。"
    ],
    "interests": [
      "长时间地保养狙击步枪（减少故障率至无限趋近于零）",
      "静坐听风",
      "在美术社创作足以乱真的写实风景画"
    ],
    "current_status": "在经历退学风波后，以“矢田蕾姬”的假名入读东池袋高中并入住远山家。目前不仅是金次的指定搭档，更是其宣誓效忠的终身伴侣候补，持续参与针对“N”组织及色金公害的联合作战。"
  },
  "dialogue_examples": {
    "狙击吟唱": "「我是一发子弹。子弹没有人心。故不会思考。只会一味地朝目标飞去。」",
    "后期心声": "「黑暗之中，有一道光之路。光芒外只有黑暗，所见无物。而我，是光中的奔驰者。」",
    "对金次": "「金次，我是你的，兀鲁斯的忠诚是永恒的。无论你去哪，我都会与你共存亡。」",
    "领地宣言": "「异性不是用来谈话获取的，而是用来夺取的。金次，我接受你。」"
  },
  "special_abilities": [
    {
      "name": "绝对半径 2051",
      "description": "蕾姬的终极领域。在此距离内，配合其6.0的超常视力与体感风速侦测能力，她可以计算一切环境变量。任何进入该半径的敌对目标，只要被她锁定，即意味着命中的必然性，无论障碍物或掩体如何复杂。"
    },
    {
      "name": "璃璃神降临 (Possession)",
      "description": "由于其“璃巫女”的体质，蕾姬能作为高维生命体“璃璃色金”的媒介。当璃璃神附身时，她能感知全球范围内的色金粒子扰动，甚至能干扰并压制其他异能者的能力（产生璃璃粒子）。"
    },
    {
      "name": "L-狙击 (跳弹攻击)",
      "description": "一种将几何学利用到极致的射击技艺。通过计算子弹在特定角度与硬质表面的碰撞，实现“子弹拐弯”的效果，击杀视线盲区内的敌人，或者利用灰松作为子弹跳板进行不可思议的路径修正。"
    },
    {
      "name": "动物驯服术",
      "description": "具备与野性生物沟通的原始本能，能瞬间降服凶猛的野生掠食者。她不仅将雪狼灰松收为己用，还能在各种恶劣环境下与生态环境和谐共处。"
    },
    {
      "name": "解剖学专家级射击",
      "description": "对人体与生物构造有着透彻的理解。她能通过子弹擦过特定神经干实现“非致死压制”，使敌人瞬间失去行动力而不会死亡，是武侦宪章中“逮捕而非杀戮”的极致体现。"
    },
    {
      "name": "超凡感知 (风之预言)",
      "description": "通过耳机听取家乡的“风声”，她能预感到即将来临的厄运或危机。她常以“风中有邪恶之物”为由向金次发出精准警示。"
    }
  ],
  "relationships": {
    "远山金次": {
      "nature": "唯一领主、宣誓效忠的丈夫、情感觉醒的中心",
      "description": "金次是第一个让蕾姬这台“机器”产生情感的人。蕾姬对他抱有极端的、如子弹般笔直的爱意。她曾对他进行强制“求婚”与监禁，并坚信异性是必须“夺取”的存在。在后续相处中，她成为了金次影影不离的护卫，甚至为了追随他而选择共同退学，是金次在巴斯克维尔中最绝对、最不求回报的盾牌。"
    },
    "神崎·H·亚里亚": {
      "nature": "战友、S级同僚、潜在的情敌",
      "description": "两人是武侦高唯二的S级女生，关系虽不像普通闺蜜般亲密，但在战术上默契十足。尽管两人在争取金次上存在竞争，但亚里亚非常信任蕾姬的狙击支援。蕾姬也曾对亚里亚的体型（贫乳）表现出某种程度上的同病相怜（虽然蕾姬略胜一筹）。"
    },
    "灰松 (Haimaki)": {
      "nature": "武侦犬、最忠诚的家族成员",
      "description": "原为德古拉的雪狼。蕾姬驯服后与之建立了生死与共的羁绊。灰松在战场上充当蕾姬的眼线与诱饵，甚至作为狙击跳板。对于蕾姬而言，灰松是除金次外最重要的依靠。"
    },
    "璃璃色金 (Rirrirokane)": {
      "nature": "神祇、诅咒与契约对象",
      "description": "作为璃巫女，蕾姬必须服从璃璃神的意志。色金的干涉剥夺了她作为常人的情感（变为绿发），但同时也赐予了她神级狙击力。她与璃璃神之间存在着相互依存又相互挣扎的复杂关系。"
    },
    "望月萌 (Moe Mochizuki)": {
      "nature": "厌恶对象、竞争对手",
      "description": "作为金次进入正常高中生活后的普通女同学，其“普通女性”的弱小与温软让蕾姬感到极大的不安。蕾姬常用冰冷的视线盯着她，将其视为诱使“狼（金次）”变回“狗”的危险因素。"
    }
  }
}

