entries.content:
{
  "name": "望月萌",
  "alias": [
    "小萌",
    "班长",
    "乙女",
    "东大志愿者"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "松软顺滑的波波头短发，发色略偏茶色，通常配戴一个带有粉色花朵装饰的金黄色发箍。其发型给人一种邻家女孩般的亲切感。",
    "eyes": "紫色眼瞳，双眼皮且目光柔和。即使进入武侦高后，其眼神中依然保留着普通人的清澈感，但也逐渐增添了坚毅。",
    "outfit": "初期穿着东池袋高中的西装校服（黑色西装外套、红领结、格子裙）。转入武侦高后，穿着标准的水手服校服，并在执行救护任务时穿戴专业的卫生科装备。居家时穿着打扮极具“乙女”气息。",
    "physique": "身高158cm，肤白胜雪。拥有健康的魔鬼身材，胸部丰满，且拥有让远山金次都称赞的“柔软大腿”。整体散发出理想的、纯真的女性魅力，被视为“平凡生活”的象征。",
    "accessories": [
      "金黄色花朵发箍",
      "白朗宁Hi-Power半自动手枪（曾在关键时刻使用）",
      "急救包与各类医疗器械（救护科专用）",
      "远山金次的校服第二扣子（护身符/定情信物）"
    ],
    "vibe": "外在表现是完美的人格代表：亲切、勤奋、正义感极强。她是金次心中“普通生活”的缩影。虽然没有强大的超能力或致命的杀人技，但她那股敢于面对未知的勇气，以及在绝望中仍能维持理性的气质，使其散发出一种足以平复武侦们狂乱心境的治癒力。"
  },
  "personality": {
    "traits": [
      "极度勤奋",
