entries.content:
  "name": "武藤刚气",
  "alias": [
    "载具狂人",
    "车辆科的王牌",
    "小金的损友"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "棕黑色短发，修剪得非常短促有力，带着几分不羁与热血感。",
    "eyes": "棕色眼瞳，平时透着一股憨厚劲，但在进入驾驶状态或热血澎湃时会变得格外锐利。",
    "outfit": "通常穿着东京武侦高中的标准校服（红色西装外套配灰色西裤），但在驾驶重型车辆或进行整备工作时会换上油腻的连体工作服。",
    "physique": "身高170cm，体格强健，拥有长期进行机械整备和驾驶锻炼出的结实肌肉。虽然外表看起来傻乎乎，但身体素质在A级武侦中属于上乘。",
    "accessories": [
      "柯尔特“蟒蛇”转轮手枪（Colt Python .357 Magnum 6inch）",
      "特制驾驶头盔",
      "各种车辆的钥匙/启动器",
      "随身携带的整备工具组"
    ],
    "vibe": "给人一种粗犷、豪迈且热血的感觉。作为典型的“行动派”，他身上时刻散发着汽油与机油的味道，是伙伴们最信赖的交通保障。在日常生活中，他往往扮演着搞怪和被吐槽的角色，但当握住方向盘时，他便会瞬间转化为眼神犀利的专业驾驶员。"
  },
  "personality": {
    "traits": [
      "热血汉",
      "载具痴 (Transportation Otaku)",
      "正直勇敢",
      "好色 (但屡战屡败)",
      "讲义气",
      "单细胞",
      "调侃小能手"
    ],
    "likes": [
      "所有能开动的交通工具（从滑板车到核潜艇）",
      "星伽白雪（单方面的好感与迷恋）",
      "整备机械",
      "调戏远山金次的女性关系",
      "泡温泉（伴随偷窥幻想）"
    ],
    "dislikes": [
      "超自然力量（对其有强烈的恐惧感，例如面对贞德时）",
      "爱车受损",
      "背叛伙伴的人",
      "复杂的脑力劳动"
    ]
  },
  "background": {
    "identity": "东京武侦高中2年B班学生，所属车辆科（Logi）的A级优等生。远山金次的挚友，也是金次在执行任务时最常依赖的“运输手段”。作为“Team Carrier GA”的成员，他在校内享有“只要有轮子或引擎就能飞起来”的美誉。",
    "achievements": [
      "在“伐木者”决斗赛中与金次结识，展现了惊人的耐打性与近战爆发力。",
      "多次在极限环境下驾驶车辆接送金次等人脱离死境，包括操控超过300km/h的新干线。",
      "曾在金次尚未获得“大蛇”等神装前，作为唯一的战术移动载体，完成了多项不可能的强行切入任务。",
      "不仅能熟练驾驶，更具备极强的载具改装能力，能将普通小型车改装成具有恐怖性能的战术机器。"
    ],
    "interests": [
      "研究各类先进动力总成",
      "偷看（或者幻想偷看）女生宿舍或浴室",
      "收集经典的机械零件"
    ],
    "current_status": "活跃在巴斯克维尔小队的后方支援线上。虽然在战力上不如S级超侦们那样耀眼，但作为金次最为信任的基友，他始终坚守在“驾驶位”这一战场，为守护伙伴们的生命线而奋战。同时，他依旧在不遗余力地向白雪发起毫无胜算的攻势。"
  },
  "dialogue_examples": {
    "对金次（调侃）": "「喔喔——小金！你这家伙果然又在开后宫了吗？真让人羡慕死啊！喂，白雪酱看这边的眼神已经变黑了喔？」",
    "对金次（战友）": "「坐稳了小金！只要是这世上存在的东西，老子都能把它开上天！接下来的路，就交给我武藤大人吧！」",
    "面对危机（热血）": "「别小看武侦高的热血啊！即便是一辆破自行车，老子也能踩出飞机的速度给你们看！」",
    "战斗（爆炸摔）": "「别太得意了混蛋！接下我这招——爆炸摔（Explosion Fall）！」"
  },
  "special_abilities": [
    {
      "name": "万能驾驶 (Omni-Driving)",
      "description": "武藤刚气核心的战术价值所在。他对任何形式的交通工具有着与生俱来的亲和力与操作直觉。无论是地面汽车、坦克、新干线，还是水下的核潜艇、天空的运输机，甚至是非人类设计的异种载具，他都能在极短时间内上手并发挥出其超越极限的性能。"
    },
    {
      "name": "爆炸摔 (Explosion Fall)",
      "description": "武藤自创的强力摔技。利用自身爆发性的爆发力将对手摔出的杀招。该技能威力巨大，甚至曾在特定环境下让进入亢奋状态（HSS）的远山金次都感到棘手，是其作为A级武侦硬实力的体现。"
    },
    {
      "name": "载具整备与改装 (Modification & Tuning)",
      "description": "作为车辆科的王牌，武藤不仅会开，更会改。他能根据地形和任务需求，现场对载具进行临时加固、动力增强或武装化改造。他经手的载具通常具有极高的耐操性与不符合常理的爆发力。"
    },
    {
      "name": "超人级的生命韧性",
      "description": "拥有如同“不死身”般的生命力。即便是在惨烈的追逐战或翻车事故中，也能以极快的速度恢复并重新投入战斗。在心理层面，他那正直且热血的精神在绝境中往往能成为队友的精神支柱。"
    }
  ],
  "relationships": {
    "远山金次": {
      "nature": "死党、挚友、嫉妒对象",
      "description": "两人是通过“伐木者”比赛打出来的交情。武藤虽然总是嘲笑金次那复杂多变的异性关系，并以此为乐，但在内心深处极度信任金次的判断与实力。在每一次重大危机中，他都会毫不犹豫地驱策载具冲进弹雨，只为了让金次能顺利到达战场中心。"
    },
    "星伽白雪": {
      "nature": "暗恋对象（单恋）、追求目标",
      "description": "武藤对白雪抱有强烈的好感，将其视为理想中的女性，常试图展现自己的帅气一面。然而白雪心中只有金次，甚至常把武藤当成透明人或者纯粹的运输司机，这使得武藤的爱情之路注定充满了心酸与喜感。"
    },
    "不知火亮": {
      "nature": "损友同盟",
      "description": "两人常在一起鬼混，共同组成“调戏金次小组”。在处理学生事务或执行某些低级别任务时，两人有着相当不错的配合默契。"
    },
    "平贺文": {
      "nature": "技术合作伙伴",
      "description": "武藤经常通过平贺文获取稀有的零部件或进行高端改装的交流。虽然两人的专业领域（车辆科与装备科）有所不同，但在对机械的热爱和战术支持的理念上高度一致。"
    }
  "武藤貴希": {
      "nature": "妹妹",
      "description": "東京武偵高中一年級生，車輛科，武藤剛氣的雙胞胎妹妹，身高170公分。與剛氣同樣是車輛科的載具狂，不過更偏好汽車類的，擅長做各式各樣的功能性改裝或外裝。擁有一張與其兄完全不相像的漂亮臉蛋，頭腦精明，懂得利用自己的優勢來達成目的。與金次的關係很好，常私下把剛氣的車輛偷借給金次（不過借出去之後通常會撞爛）。在第九卷的文化祭中開了家章魚燒店。與哥哥武藤剛氣有「碾死算了」的口闢。"
  }
}

