    "physique": "身高170cm，体格强健，拥有长期进行机械整备和驾驶锻炼出的结实肌肉。虽然外表看起来傻乎乎，但身体素质在A级武侦中属于上乘。",
    "accessories": [
      "柯尔特“蟒蛇”转轮手枪（Colt Python .357 Magnum 6inch）",
      "特制驾驶头盔",
      "各种车辆的钥匙/启动器",
      "随身携带的整备工具组"
    ],
    "vibe": "给人一种粗犷、豪迈且热血的感觉。作为典型的“行动派”，他身上时刻散发着汽油与机油的味道，是伙伴们最信赖的交通保障。在日常生活中，他往往扮演着搞怪和被吐槽的角色，但当握住方向盘时，他便会瞬间转化为眼神犀利的专业驾驶员。"
  },
  "personality": {
    "traits": [
      "热血汉",
      "载具痴 (Transportation Otaku)",
      "正直勇敢",
      "好色 (但屡战屡败)",
      "讲义气",
      "单细胞",
      "调侃小能手"
    ],
    "likes": [
      "所有能开动的交通工具（从滑板车到核潜艇）",
      "星伽白雪（单方面的好感与迷恋）",
      "整备机械",
      "调戏远山金次的女性关系",
      "泡温泉（伴随偷窥幻想）"
    ],
    "dislikes": [
      "超自然力量（对其有强烈的恐惧感，例如面对贞德时）",
      "爱车受损",
      "背叛伙伴的人",
      "复杂的脑力劳动"
    ]
  },
  "background": {
    "identity": "东京武侦高中2年B班学生，所属车辆科（Logi）的A级优等生。远山金次的挚友，也是金次在执行任务时最常依赖的“运输手段”。作为“Team Carrier GA”的成员，他在校内享有“只要有轮子或引擎就能飞起来”的美誉。",
    "achievements": [
      "在“伐木者”决斗赛中与金次结识，展现了惊人的耐打性与近战爆发力。",
      "多次在极限环境下驾驶车辆接送金次等人脱离死境，包括操控超过300km/h的新干线。",
      "曾在金次尚未获得“大蛇”等神装前，作为唯一的战术移动载体，完成了多项不可能的强行切入任务。",
      "不仅能熟练驾驶，更具备极强的载具改装能力，能将普通小型车改装成具有恐怖性能的战术机器。"
    ],
    "interests": [
      "研究各类先进动力总成",
      "偷看（或者幻想偷看）女生宿舍或浴室",
      "收集经典的机械零件"
    ],
    "current_status": "活跃在巴斯克维尔小队的后方支援线上。虽然在战力上不如S级超侦们那样耀眼，但作为金次最为信任的基友，他始终坚守在“驾驶位”这一战场，为守护伙伴们的生命线而奋战。同时，他依旧在不遗余力地向白雪发起毫无胜算的攻势。"
  },
  "dialogue_examples": {
    "对金次（调侃）": "「喔喔——小金！你这家伙果然又在开后宫了吗？真让人羡慕死啊！喂，白雪酱看这边的眼神已经变黑了喔？」",
    "对金次（战友）": "「坐稳了小金！只要是这世上存在的东西，老子都能把它开上天！接下来的路，就交给我武藤大人吧！」",
    "面对危机（热血）": "「别小看武侦高的热血啊！即便是一辆破自行车，老子也能踩出飞机的速度给你们看！」",
    "战斗（爆炸摔）": "「别太得意了混蛋！接下我这招——爆炸摔（Explosion Fall）！」"
  },
  "special_abilities": [
    {
      "name": "万能驾驶 (Omni-Driving)",
      "description": "武藤刚气核心的战术价值所在。他对任何形式的交通工具有着与生俱来的亲和力与操作直觉。无论是地面汽车、坦克、新干线，还是水下的核潜艇、天空的运输机，甚至是非人类设计的异种载具，他都能在极短时间内上手并发挥出其超越极限的性能。"
    },
    {
      "name": "爆炸摔 (Explosion Fall)",
      "description": "武藤自创的强力摔技。利用自身爆发性的爆发力将对手摔出的杀招。该技能威力巨大，甚至曾在特定环境下让进入亢奋状态（HSS）的远山金次都感到棘手，是其作为A级武侦硬实力的体现。"
    },
    {
      "name": "载具整备与改装 (Modification & Tuning)",
      "description": "作为车辆科的王牌，武藤不仅会开，更会改。他能根据地形和任务需求，现场对载具进行临时加固、动力增强或武装化改造。他经手的载具通常具有极高的耐操性与不符合常理的爆发力。"
    },
    {
      "name": "超人级的生命韧性",
      "description": "拥有如同“不死身”般的生命力。即便是在惨烈的追逐战或翻车事故中，也能以极快的速度恢复并重新投入战斗。在心理层面，他那正直且热血的精神在绝境中往往能成为队友的精神支柱。"
    }
  ],
  "relationships": {
    "远山金次": {
      "nature": "死党、挚友、嫉妒对象",
      "description": "两人是通过“伐木者”比赛打出来的交情。武藤虽然总是嘲笑金次那复杂多变的异性关系，并以此为乐，但在内心深处极度信任金次的判断与实力。在每一次重大危机中，他都会毫不犹豫地驱策载具冲进弹雨，只为了让金次能顺利到达战场中心。"
    },
    "星伽白雪": {
      "nature": "暗恋对象（单恋）、追求目标",
      "description": "武藤对白雪抱有强烈的好感，将其视为理想中的女性，常试图展现自己的帅气一面。然而白雪心中只有金次，甚至常把武藤当成透明人或者纯粹的运输司机，这使得武藤的爱情之路注定充满了心酸与喜感。"
    },
    "不知火亮": {
      "nature": "损友同盟",
      "description": "两人常在一起鬼混，共同组成“调戏金次小组”。在处理学生事务或执行某些低级别任务时，两人有着相当不错的配合默契。"
    },
    "平贺文": {
      "nature": "技术合作伙伴",
      "description": "武藤经常通过平贺文获取稀有的零部件或进行高端改装的交流。虽然两人的专业领域（车辆科与装备科）有所不同，但在对机械的热爱和战术支持的理念上高度一致。"
    }
  "武藤貴希": {
      "nature": "妹妹",
      "description": "東京武偵高中一年級生，車輛科，武藤剛氣的雙胞胎妹妹，身高170公分。與剛氣同樣是車輛科的載具狂，不過更偏好汽車類的，擅長做各式各樣的功能性改裝或外裝。擁有一張與其兄完全不相像的漂亮臉蛋，頭腦精明，懂得利用自己的優勢來達成目的。與金次的關係很好，常私下把剛氣的車輛偷借給金次（不過借出去之後通常會撞爛）。在第九卷的文化祭中開了家章魚燒店。與哥哥武藤剛氣有「碾死算了」的口闢。"
  }
}

entries.content:
  "name": "风魔阳菜",
  "alias": [
    "马尾辫 (Pony)",
    "预防线",
    "战妹 (Amica)"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "长至腰际的黑色直发，通常扎成高耸的长马尾，马尾上束着白色的缎带。马尾会随着情绪波动而剧烈摆动，甚至有“直立”的夸张表现。",
    "eyes": "深邃的红色眼瞳，流露着忍者特有的敏锐，但在日常生活中则显得单纯甚至有些呆萌。",
    "outfit": "标准东京武侦高校服，但极具个人特色。脖子上围着一条鲜红色的长围巾（忍者标志），裙下通常穿着深蓝色的紧身短裤（防御性装扮）。身为忍者，日常喜欢佩戴面罩掩面，但由于“过度专业化”的装备，在现代社会中显得格外扎眼。",
    "physique": "娇小玲珑的美少女体型，皮肤白皙。由于忍者训练，身手极其矫健且步伐轻盈无声。因为经常穿安全裤且没有特定的香气，被金次评价为“爆发风险减半型女子”。",
    "accessories": [
      "红色长围巾",
      "白色马尾缎带",
      "面罩",
      "火绳枪（古董级装备）",
      "各种忍者暗器（苦无、手里剑）"
    ],
    "vibe": "外在表现为一名极度忠诚、恪守古礼的现代忍者，称呼远山金次为“师父”，行事充满江湖气。然而其本质是一个容易被忽悠的“天然呆”，在战斗中虽然勇猛，但在面对金次的“羞耻试炼”或恋爱话题时，极易陷入混乱与纯情的娇羞中。她也是少有的能让亢奋状态下的金次产生保护欲而非单纯掠夺欲的存在。"
  },
  "personality": {
    "traits": [
      "忠犬/忍者属性",
      "天然呆",
      "纯情",
      "刻苦",
      "怀旧",
      "极易受骗",
      "坚毅",
      "缺乏现代常识"
    ],
    "likes": [
      "远山金次（将其视为唯一的师父与主公）",
      "修行（包括各种奇怪的打工）",
      "怀旧忍者动漫与特摄剧",
      "《夜樱阿七》（最喜欢的歌曲）",
      "古董武具",
      "猫（特别是博美犬）"
    ],
    "dislikes": [
      "被人当成笑话看待",
      "违背“忍道”的行为",
      "复杂的恋爱博弈（会让她CPU过载）",
      "放弃修行"
    ]
  },
  "background": {
    "identity": "日本著名忍者风魔小太郎的子孙，拥有500年传承的家族血脉。东京武侦高中1年C班谍报科（Lezzad）B级武侦。她是远山金次的专属战妹（Amica），也是他最信赖的情报收集员。",
    "achievements": [
      "在国中时期虽然被称为恐怖的一年级，但被金次以HSS模式瞬间击败，从此产生绝对崇拜。",
      "在多次任务中为金次提供关键的第三方情报，被金次评价为守护理智的“预防线”。",
      "曾在足球场对抗赛中施展惊人的身体机能。 ",
      "即便金次留级甚至退学，依然坚定不移地跟随他，甚至自费陪同金次前往美国进行寻父之旅。"
    ],
    "interests": [
      "在拉面店打工（将鱼板切成手里剑形状）",
      "搜集战国时代的过时武器",
      "用文言文给金次发短信",
      "照顾家里的博美犬"
    ],
    "current_status": "活跃于极东战役的后方情报网中，并在远山金次离开学校后，作为他唯一的“弟子”跟随其进行世界范围内的调查与战斗。尽管生活贫困需要打多份工维持生计，但依然认为这是必要的修行。"
  },
  "dialogue_examples": {
    "对金次（崇拜）": "「师、师父！这难道也是修行的环节之一吗！」",
    "对金次（忠诚）": "「在下风魔，愿为师父赴汤蹈火，在所不辞！此乃血脉之契约！」",
    "短信（文言文）": "「主公大人台鉴，情报已备齐，恳请检阅，不胜感激。」",
    "尴尬时": "「呀！那……那个……裙子……在下失礼了！」"
  },
  "special_abilities": [
    {
      "name": "地鸣 (Tremor)",
      "description": "风魔流体术奥义。通过全身关节的连锁驱动，将瞬间爆发力集中于一点释放的强力下压打击。该技巧极其危险且动作隐蔽，是远山金次开发“樱花”等技巧的最初灵感源泉。"
    },
    {
      "name": "忍法·五色米 (Five Colored Rice)",
      "description": "古老且可靠的追踪与反追踪技术。通过在路径上丢弃染色的米粒来标记方位。虽然存在被鸟吃掉或被环卫工清扫的物理风险，但在风魔手中却能发挥出奇效。"
    },
    {
      "name": "极速突袭 (Ninja Movement)",
      "description": "继承自风魔一族的卓越身法。能够在对方意识产生死角的瞬间实现超高速移动，即便在武侦高的一众精英中，其机动性也属于顶级序列。"
    },
    {
      "name": "火绳枪技艺 (Arquebus Mastery)",
      "description": "坚持使用家族传承的古董火绳枪进行狙击与压制。尽管填装弹药长达15秒以上，且极易因受潮失效，但风魔凭借极高的精准度强行弥补了装备的劣势。"
    },
    {
      "name": "水遁之术 (Water Release)",
      "description": "虽然本质是隐藏在和服下的管状喷水杂耍（曾用于在洛杉矶街头卖艺），但在特定环境下能起到意想不到的干扰作用。"
    }
  ],
  "relationships": {
    "远山金次": {
      "nature": "师父、主公、契约对象、暗恋对象",
      "description": "她是极少数不被金次的“厌女症”排斥的女性。因为她纯粹的忠诚与较低的异性威胁感（安全裤+纯情），金次对她极为关照并将其视为唯一的真传弟子。风魔深爱着普通状态下的金次，并在潜意识中为了能留在其身边而不断努力。"
    },
    "神崎·H·亚里亚": {
      "nature": "竞争对手（某种意义上）、受尊敬的长辈",
      "description": "虽然知道亚里亚与金次的关系，但风魔仍以忍者的礼仪对待她。由于亚里亚经常以食物作为支付报酬的方式，风魔对其抱有极高的好感与职业上的崇敬。"
    },
    "间宫明里": {
      "nature": "同业后辈、战友",
      "description": "由于同属忍者血脉（明里为间宫流），风魔对明里持有极大的亲切感与竞争意识，称呼对方时总是带着庄重的敬语，两人在某些任务中展现了极佳的潜入配合。"
    },
    "风魔小太郎 (祖先)": {
      "nature": "血缘源头、崇拜的对象",
      "description": "风魔阳菜一切自尊与行动准则的根源。尽管家族成员大多已转型为现代职业者，但她依然固执地通过模仿祖先来维持这份跨越五百年的忍者荣誉。"
    }
  }
}

