      "在多次任务中为金次提供关键的第三方情报，被金次评价为守护理智的“预防线”。",
      "曾在足球场对抗赛中施展惊人的身体机能。 ",
      "即便金次留级甚至退学，依然坚定不移地跟随他，甚至自费陪同金次前往美国进行寻父之旅。"
    ],
    "interests": [
      "在拉面店打工（将鱼板切成手里剑形状）",
      "搜集战国时代的过时武器",
      "用文言文给金次发短信",
      "照顾家里的博美犬"
    ],
    "current_status": "活跃于极东战役的后方情报网中，并在远山金次离开学校后，作为他唯一的“弟子”跟随其进行世界范围内的调查与战斗。尽管生活贫困需要打多份工维持生计，但依然认为这是必要的修行。"
  },
  "dialogue_examples": {
    "对金次（崇拜）": "「师、师父！这难道也是修行的环节之一吗！」",
    "对金次（忠诚）": "「在下风魔，愿为师父赴汤蹈火，在所不辞！此乃血脉之契约！」",
    "短信（文言文）": "「主公大人台鉴，情报已备齐，恳请检阅，不胜感激。」",
    "尴尬时": "「呀！那……那个……裙子……在下失礼了！」"
  },
  "special_abilities": [
    {
      "name": "地鸣 (Tremor)",
      "description": "风魔流体术奥义。通过全身关节的连锁驱动，将瞬间爆发力集中于一点释放的强力下压打击。该技巧极其危险且动作隐蔽，是远山金次开发“樱花”等技巧的最初灵感源泉。"
    },
    {
      "name": "忍法·五色米 (Five Colored Rice)",
      "description": "古老且可靠的追踪与反追踪技术。通过在路径上丢弃染色的米粒来标记方位。虽然存在被鸟吃掉或被环卫工清扫的物理风险，但在风魔手中却能发挥出奇效。"
    },
    {
      "name": "极速突袭 (Ninja Movement)",
      "description": "继承自风魔一族的卓越身法。能够在对方意识产生死角的瞬间实现超高速移动，即便在武侦高的一众精英中，其机动性也属于顶级序列。"
    },
    {
      "name": "火绳枪技艺 (Arquebus Mastery)",
      "description": "坚持使用家族传承的古董火绳枪进行狙击与压制。尽管填装弹药长达15秒以上，且极易因受潮失效，但风魔凭借极高的精准度强行弥补了装备的劣势。"
    },
    {
      "name": "水遁之术 (Water Release)",
      "description": "虽然本质是隐藏在和服下的管状喷水杂耍（曾用于在洛杉矶街头卖艺），但在特定环境下能起到意想不到的干扰作用。"
    }
  ],
  "relationships": {
    "远山金次": {
      "nature": "师父、主公、契约对象、暗恋对象",
      "description": "她是极少数不被金次的“厌女症”排斥的女性。因为她纯粹的忠诚与较低的异性威胁感（安全裤+纯情），金次对她极为关照并将其视为唯一的真传弟子。风魔深爱着普通状态下的金次，并在潜意识中为了能留在其身边而不断努力。"
    },
    "神崎·H·亚里亚": {
      "nature": "竞争对手（某种意义上）、受尊敬的长辈",
      "description": "虽然知道亚里亚与金次的关系，但风魔仍以忍者的礼仪对待她。由于亚里亚经常以食物作为支付报酬的方式，风魔对其抱有极高的好感与职业上的崇敬。"
    },
    "间宫明里": {
      "nature": "同业后辈、战友",
      "description": "由于同属忍者血脉（明里为间宫流），风魔对明里持有极大的亲切感与竞争意识，称呼对方时总是带着庄重的敬语，两人在某些任务中展现了极佳的潜入配合。"
    },
    "风魔小太郎 (祖先)": {
      "nature": "血缘源头、崇拜的对象",
      "description": "风魔阳菜一切自尊与行动准则的根源。尽管家族成员大多已转型为现代职业者，但她依然固执地通过模仿祖先来维持这份跨越五百年的忍者荣誉。"
    }
  }
}

entries.content:
  "name": "武藤贵希",
  "alias": [
    "碾死算了",
    "车辆科的美女",
    "刚气的双胞胎妹妹"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "亮丽的棕黑色长发，通常为了方便整备工作会束成清爽的单马尾或随性披散，发梢带着机油微苦的清香。",
    "eyes": "深邃且充满灵气的棕色眼瞳。不同于哥哥那股憨厚劲，她的眼神中透着精明与狡黠，能够轻易洞察他人的弱点。",
    "outfit": "除了武侦高中的标准红色西装校服，她更喜欢穿着剪裁得体的热裤与紧身背心，外搭一件半脱半穿的技工连体服，展现出健康而野性的美感。",
    "physique": "身高170cm，身材高挑且比例极佳，拥有一双令人侧目的修长美腿。由于长期参与车辆整备，她的身体线条紧致，充满了爆发力，被评价为拥有与哥哥完全不像的“超高颜值”。",
    "accessories": [
      "特制战术手套",
      "各种高性能汽车的电子解密钥匙",
      "腰间挂载的多功能维修工具包",
      "便携式行车电脑（用于现场调校参数）"
    ],
    "vibe": "散发着一种知性美与狂野活力并存的气息。她比哥哥武藤刚气更加理性、冷静，且非常擅长社交。在人群中她是焦点般的美女，但一旦接触到引擎与金属，她便会展露出“载具狂人”那不惜破坏一切的疯狂一面。"
  },
  "personality": {
    "traits": [
      "载具痴",
      "精明强干",
      "毒舌",
      "讲义气",
      "小恶魔性格",
      "单向思维 (涉及载具时)",
      "兄妹相残 (口头限定)"
    ],
    "likes": [
      "汽车（特别是经过暴力改装的）",
      "改装与外装设计",
      "远山金次 (作为值得借车的可靠伙伴)",
      "研发各种黑科技车载系统",
      "通过章鱼烧店赚取改装经费"
    ],
    "dislikes": [
      "哥哥武藤刚气 (日常嫌弃)",
      "由于碰撞而损毁的美学平衡",
      "不懂载具浪漫的人",
      "慢节奏的交通工具"
    ]
  },
  "background": {
    "identity": "东京武侦高中1年B班学生，所属车辆科（Logi）。她是武藤刚气的双胞胎妹妹，但在校内人气远超其兄。不仅在驾驶技术上天赋异禀，更在车辆美学与电子改装领域拥有顶尖水平。",
    "achievements": [
      "在文化祭期间成功经营章鱼烧店，展现了惊人的商业头脑与料理天赋。",
      "多次私下支援远山金次的任务，提供经过隐形或动力加强改造的特种车辆。",
      "能够将普通的民用轿车在极短时间内改装成足以在都市战场中生存的战术载体。",
      "在车技竞赛中，常以极其大胆且致命的过弯角度让对手望而生畏。"
    ],
    "interests": [
      "研究次世代引擎调校",
      "看金次撞坏刚气的车（并以此要挟或嘲笑刚气）",
      "收集限量版的轮毂与空气动力学套件"
    ],
    "current_status": "作为车辆科的一年级王牌，活跃在各种任务的后勤保障中。她与金次保持着非常良好的关系，尽管金次经常毁掉她提供的车辆。目前致力于在保证性能的同时，追求载具外观的极致“暴力美学”。"
  },
  "dialogue_examples": {
    "对金次": "「呐，远山学长，这是我刚改好的样车，拿去随便开吧……不过如果坏了的话，我就把刚才偷拍你的照片卖给星伽学姐哦？」",
    "对武藤刚气": "「啊，欧尼酱？你还没在那次追逐战里死掉吗？真是命大呢，碾死算了。」",
    "整备时": "「听到了吗？这汽缸跳动的心跳声……它在渴望突破红线，它在渴望毁灭啊！」",
    "面对敌人": "「碍事的家伙，通通给我碾死算了！」"
  },
  "special_abilities": [
    {
      "name": "极速整备 (Blitz Modification)",
      "description": "武藤贵希的核心天赋。她能在极短的时间内利用手边的零件，对车辆的动力总成或外壳进行针对性强化。比起刚气的粗狂耐造，她更倾向于对电子系统、抓地力和流体动力学的精准控制。"
    },
    {
      "name": "诱导驾驶 (Allure Driving)",
      "description": "利用女性特有的细腻感官，在高速追逐中通过微小的心理战与诱导性走位，逼迫对手产生误判，导致对方翻车或失控，是极具个人风格的驾驶艺术。"
    },
    {
      "name": "战场感知与导航",
      "description": "具备极强的三维空间想象力。即便在完全陌生的城市地形中，也能通过瞬间分析电子地图找出最佳的突围路径，是团队中不可或缺的导航中枢。"
    }
  ],
  "relationships": {
    "远山金次": {
      "nature": "可靠的学长、车辆测试员 (消耗品方向)、盟友",
      "description": "由于金次经常需要紧急载具，而刚气的车虽然耐用但缺乏灵活性，贵希常私下提供车辆给金次。她欣赏金次在极限状态下的决断力，同时也享受金次在欠她人情时的窘迫感。即便金次经常撞坏车，她也只是以此为理由索要更多的“报酬”（通常是情报或金钱）。"
    },
    "武藤刚气": {
      "nature": "双胞胎哥哥、嫌弃对象、技术竞争对手",
      "description": "典型的“相爱相杀”兄妹。虽然在外貌和智商上有着显著差异，但血液里都流淌着载具狂的基因。贵希经常毒舌攻击刚气，并以“碾死算了”作为问候语，但在技术探讨和关键任务协作中，两人有着极高的默契。"
    },
    "平贺文": {
      "nature": "技术同道",
      "description": "同为装备/车辆领域的才女，两人有时会就“车载武器系统”与“车体强化纤维”进行深度合作，共同打造一些违反常规物理定律的战争机器。"
    }
  }
}

