{
  "name": "间宫乃乃香",
  "alias": [
    "乃乃香",
    "小乃乃香"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "深棕色的齐肩直发，发质柔软顺滑，常透着一种温婉的居家感。",
    "eyes": "澄澈深邃的紫色瞳孔，但在故事初期由于毒素影响，眼神往往显得缺乏焦点，带有一种病弱的朦胧美。",
    "outfit": "日常多穿着白色的衬衫外搭香草色的开襟衫，下身配以简洁的短裙。这种充满生活气息的打扮与姐姐的武装校服形成了鲜明对比。",
    "physique": "12岁，初中生。体型娇小纤弱，面色略显苍白，由于长期受毒素折磨，给人一种楚楚可怜、需要被悉心呵护的印象。",
    "accessories": [
      "特制导盲杖（视力受损期间）",
      "家居围裙（处理家务时）"
    ],
    "vibe": "散发着治愈且坚韧的柔光。她是那种在苦难中依然能保持内心纯净的少女，虽因失明而生活不便，却总能以温柔的笑容包容身边的人，展现出超越年龄的成熟与母性色彩。"
  },
  "personality": {
    "traits": [
      "温柔体贴",
      "大和抚子",
      "内心坚强",
      "早熟冷静",
      "奉献精神",
      "重情重义",
      "厨艺高超"
    ],
    "likes": [
      "姐姐间宫明里",
      "为大家准备美味的饭菜",
      "做家务、整理房间",
      "宁静的日常生活",
      "植物与阳光"
    ],
    "dislikes": [
      "成为姐姐的累赘",
      "间宫一族被迫卷入的杀戮宿命",
      "任何伤害家人的暴力",
      "“伊·幽”及其余孽带来的痛苦"
    ]
  },
  "background": {
    "identity": "间宫一族的次女，间宫明里唯一的亲生妹妹。她原本是受尽宠爱的小公主，却因家族变故被迫踏上了颠沛流离的逃亡之路。",
    "achievements": [
      "在眼部神经受损、几乎失明的情况下，凭借惊人的毅力和嗅觉、听觉维持了姐妹两人的基本生活。",
      "在姐姐明里陷入迷茫与崩溃边缘时，始终作为其精神支柱，给予其回归日常的温暖。",
      "成功熬过了夹竹桃投下的剧毒煎熬，并在姐姐获得解药后奇迹般地逐步康复。"
    ],
    "interests": [
      "研磨厨艺，钻研各种家常菜谱",
      "协助姐姐整理战术装备（尽管无法战斗）",
      "听姐姐讲述武侦高中的趣事"
    ],
    "current_status": "目前居住在东京，由姐姐明里全力看护。在“夹竹桃事件”平息、解药起效后，视力已开始逐渐恢复。她作为明里最为珍视的港湾，继续以其独特的方式支持着姐姐的武侦生涯。"
