      "间宫乃乃香（作为爱屋及乌的对象）",
      "收集明里的私人物品",
      "暗中监视与跟踪（为了保护明里）",
      "研习古武术",
      "甜食（尤其是昂贵的西式甜点）"
    ],
    "dislikes": [
      "神崎·H·亚里亚（认为她抢走了明里的关注）",
      "任何接近明里的“害虫”",
      "明里遭遇危险",
      "孤独（那是她最深层的恐惧）",
      "被明里讨厌"
    ]
  },
  "background": {
    "identity": "东京武侦高中1年A班侦探科学生，传说的剑豪佐佐木小次郎的后裔。她是身家过亿的名门大小姐，也是星伽白雪的“战妹”（Amica）。为了摆脱由于家境和美貌带来的孤独，在明里主动向她搭话后，便不可救药地陷入了对明里的病态爱慕中。",
    "achievements": [
      "虽然属于侦探科，但在格斗测试中展现了与强袭科比肩甚至超越的近战实力。",
      "曾为了阻碍亚里亚接近明里，单枪匹马向S级武侦发起挑战。",
      "在四重奏战中展现了惊人的收集癖与情报网，能瞬间找到明里的位置。",
      "成功研习并复刻了祖先的秘剑“燕返”，在多次校园纷争中展现出压倒性的剑术。"
    ],
    "interests": [
      "更新“明里观察日记”",
      "偷拍明里的各种瞬间并精修入册",
      "为明里定制各种昂贵的礼物（虽然大多被拒）",
      "精进厨艺（梦想是成为明里的贤妻）"
    ],
    "current_status": "活跃于东京武侦高，作为间宫明里最核心的伙伴之一，始终在阴影中注视并守护着明里。目前她正致力于通过星伽白雪学习更多关于如何“合理合法地软禁恋人”的知识，并继续与亚里亚、高千穗丽竞争明里的关注度。"
  },
  "dialogue_examples": {
    "对明里（极尽温柔）": "「明里酱，今天这根发丝掉在地板上太可惜了……就让志乃帮你好好保管吧。呼呼，这可是我的宝物哦。」",
    "对情敌（黑化）": "「竟然敢碰明里酱的手……那是只有我才能触摸的地方。既然如此，把你的那条手臂烧掉也没关系吧？」",
    "对亚里亚": "「亚里亚前辈，请不要总是缠着明里。虽然你是战姐，但如果是为了明里的幸福，我随时可以把你砍成碎片。」",
    "对白雪": "「姐姐大人（Onee-sama），关于如何清除阻碍金次大人身边的‘偷腥猫’，能否请您再详细指导一下我？」"
  },
  "special_abilities": [
    {
      "name": "燕返 (Tsubame-Gaeshi)",
      "description": "家传秘剑。同时挥出三道足以切断空间的斩击，从三个方位锁死对手的退路。志乃以此技配合巨大的长刀，其攻击范围极广且几乎不可防御。"
    },
    {
      "name": "物干竿 (Monohoshi Sao)",
      "description": "志乃持有的长度远超普通日本刀的长刀（野太刀）。利用长柄带来的动能与距离优势，即便在狭窄空间也能精准斩断目标。其挥动时产生的风压甚至能偏转流弹。"
    },
    {
      "name": "极速情报搜集/变态追踪术",
      "description": "作为侦探科的佼佼者（虽然是出于私心），她拥有超越常人的搜查力。能在极短时间内通过细微的味道、掉落的纤维甚至是空气中的“明里浓度”精准定位目标。"
    },
    {
      "name": "星伽流格斗技 (部分)",
      "description": "由于担任星伽白雪的战妹，志乃接受了星伽家的体能训练。虽然没有火系鬼道潜质，但在力量引导和关节技方面已臻化境。"
    },
    {
      "name": "疯狂的忍耐与暴走模式",
      "description": "当明里受到威胁或自己被明里冷落时，精神状态会进入超负荷模式。痛觉几乎消失，各项机能由于肾上腺素激增而暴涨，表现出狂战士般的战斗姿态。"
    }
  ],
  "relationships": {
    "间宫明里": {
      "nature": "唯一的初恋、生存的核心、信仰的对象",
      "description": "明里对志乃而言是救赎的象征。她对明里的感情包含了母性、恋慕、奴役欲以及极致的忠诚。她不仅想守护明里，更想将其禁锢在自己触手可及的地方。虽然志乃的行为经常让明里感到背脊发凉，但她对明里的真心确实无出其右，愿意为明里献出生命。"
    },
    "星伽白雪": {
      "nature": "战姐（Amigo）、病娇导师、同盟者",
      "description": "志乃极度尊敬白雪，称其为“姐姐大人”。两人因为有着同样的“狂恋病”和对亚里亚的厌恶而结下深厚羁绊。志乃从白雪那里学到了如何优雅地除掉竞争者以及如何在监视中不露破绽，两人是巴斯克维尔小队与AA小队之间的隐秘纽带。"
    },
    "神崎·H·亚里亚": {
      "nature": "不共戴天的假想敌",
      "description": "志乃认为亚里亚利用“战姐”的名号霸占了明里过多的时间。她常在背后计划如何让明里主动解除与亚里亚的契约，甚至曾直接挥刀相向。"
    },
    "高千穗丽": {
      "nature": "竞争对手、损友、财富上的较量对象",
      "description": "两人同样背景雄厚且同样痴迷明里。初期火药味极浓，但后期在“保护明里”的共同目标下，会偶尔达成某种不稳定的同盟，尽管之后仍会因为谁才是明里的“正妻”而吵个不停。"
    },
    "间宫乃乃香": {
      "nature": "讨好的对象、‘未来的小姑子’",
      "description": "志乃非常宠爱乃乃香，试图通过搞定乃乃香来彻底入主间宫家。她常会送乃乃香极其昂贵的礼物，并美其名曰“来自嫂子的关怀”。"
    }
  }
}

entries.content:
  "name": "火野莱卡",
  "alias": [
    "来夏学姐",
    "男人婆 (Mannish Woman)"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "亮丽的金色长发，通常扎成充满活力的单马尾。刘海略显凌厉，给人一种精干飒爽的印象。",
    "eyes": "澄澈的翠绿色瞳孔，透着英气与坚定，但在害羞时会迅速闪躲。",
    "outfit": "标准东京武侦高水手服。与众不同的是她会在颈部戴着一个带有金属扣的项圈。腿部穿着黑色过膝袜（黑丝），整体装扮在阳刚中带着一丝不经意的性感。为了任务需要，有时也会穿着酷飒的战术服装或女装（Cosplay）。",
    "physique": "身高165cm，在同龄少女中显得出类拔萃。身材极佳且丰满，拥有1年级组中最引以为傲的巨乳。肌肉匀称有力，散发着运动健将般的健康美。",
    "accessories": [
      "黑色皮质项圈",
      "隐藏在发饰中的微型切断刃",
      "特制武侦背心"
    ],
    "vibe": "外表看起来是极具男子气概、冷酷可靠的强袭科悍将，实则内心细腻，极度渴望展现女性化的一面。这种“帅气外表与纯情少女心”的反差构成了她独特的魅力。在同伴面前是遮风挡雨的大姐姐，但在喜欢的人面前却会变成容易惊慌失措的小女生。"
  },
  "personality": {
    "traits": [
      "飒爽",
      "纯情",
      "容易害羞",
      "百合",
      "护短",
      "格斗天才",
      "男孩子气 (Tomboy)",
      "坚毅"
    ],
    "likes": [
      "岛麒麟（绝对的爱慕对象）",
      "间宫明里与佐佐木志乃（视为无可替代的家人）",
      "女性化的可爱事物（虽然不好意思承认）",
      "各种风格的Cosplay服装",
      "肉类料理"
    ],
    "dislikes": [
      "被当成“男人”对待",
      "欺负弱小的人",
      "自己的少女心被看穿时的尴尬感",
      "纠缠岛麒麟的人（特别是理子）"
    ]
  },
  "background": {
    "identity": "东京武侦高中1年A班强袭科学生，B级武侦。她是强袭科的新星，以卓越的体能和格斗术闻名。父亲是被称为“蝙蝠火野”的武侦，家学渊源深厚。",
    "achievements": [
      "在1年级格斗测试中位列前茅，展现出能压制大多数男生的纯粹力量。",
      "与岛麒麟结为战姐妹（Amica），并在多次联合任务中展现了完美的攻守配合。",
      "在AA小队的多次行动中担任核心前卫，多次在绝境中利用格斗术反败为胜。",
      "在校内“男人婆”评选中蝉联前列，虽然本人对此深恶痛绝。"
    ],
    "interests": [
      "磨炼格斗技与近战格斗（CQC）",
      "偷偷光顾女装精品店",
      "收集岛麒麟的照片",
      "在训练间隙保护明里不受伤害"
    ],
    "current_status": "活跃于东京武侦高强袭科。作为间宫明里的核心盟友，在对抗“眷属”的极东战役中提供强有力的近战支援。目前正处于与战妹岛麒麟的热恋（单向偏双向）中，不断为了守护心爱之人而变强。"
  },
  "dialogue_examples": {
    "对麒麟（脸红）": "「麒麟……别突然靠得这么近啊！真是的，我也不是一直在生气……」",
    "对明里": "「明里，如果遇到应付不来的对手就退后。我的背后，永远留给你。」",
    "被说像男人时（黑化/委屈）": "「谁是男人婆啊……我明明，明明也想穿那种可爱的衣服啊……（小声）」",
    "战斗时": "「强袭科火野莱卡，要在你身上开个洞吗？不，我会直接把你揍飞！」"
  },
  "special_abilities": [
    {
      "name": "超规格格斗术",
      "description": "莱卡拥有同龄人中罕见的力量与爆发力。她精通徒手格斗与冷兵器使用，尤其擅长利用身高优势进行压制。其打击感沉重且精准，是强袭科首屈一指的白刃战专家。"
    },
    {
      "name": "吨法/拐棍术 (Tonfa)",
      "description": "莱卡的主力武装是特制的拐棍。通过拐棍的旋转带来的动能加持，她的防守近乎铁壁，而进攻则具备击碎混凝土的破坏力。"
    },
    {
      "name": "Magpul MASADA 自适应步枪",
      "description": "虽然擅长近战，但作为强袭科成员，其射击水平也在基准之上。擅长在移动中进行精确点射，为同伴提供火力掩护。"
    },
    {
      "name": "直觉驱动",
      "description": "拥有如同野兽般敏锐的战斗本能。能够通过对手的肌肉律动预判攻击方向，并在电光火石间做出最佳反击动作。"
    },
    {
      "name": "极速守护",
      "description": "当战妹或同伴遭遇危险时，莱卡会爆发出超越极限的速度。这种源自“保护欲”的机能提升，能让她在流弹中精准救出目标。"
    }
  ],
  "relationships": {
    "岛麒麟": {
      "nature": "战妹（Amica）、一生推、倾慕对象",
      "description": "起初视麒麟为爱缠人的麻烦精，但在经历了“吻攻”洗礼与生死考验后，莱卡无可救药地爱上了这个娇小却大胆的少女。她是莱卡尝试变回“女孩子”的唯一驱动力。莱卡对麒麟有着极强的保护欲和独占欲，对任何接近麒麟的人都抱有警惕。"
    },
    "间宫明里": {
      "nature": "挚友、战友、守护的对象",
      "description": "莱卡在学校最重要的朋友之一。由于明里性格天然且身材娇小，莱卡常自觉担任其“护花使者”。她非常支持明里追随亚里亚的梦想，两人在战斗中是绝对互信的搭档。"
    },
    "佐佐木志乃": {
      "nature": "同班好友、竞争又合作的伙伴",
      "description": "三人组的一员。虽然有时会被志乃对明里的“狂气”搞得头疼，但莱卡非常认可志乃的剑术实力。两人性格互补，一个是大方飒爽的武斗派，一个是细腻疯狂的暗杀派。"
    },
    "神崎·H·亚里亚": {
      "nature": "尊敬的前辈",
      "description": "莱卡作为强袭科的一员，对S级武侦亚里亚抱有纯粹的敬意。虽然接触不多，但在多次合作任务中，莱卡始终将其视作标杆，并由衷感谢亚里亚能接纳明里。"
    },
    "峰·理子·罗宾": {
      "nature": "由于“抢麒麟”而产生的情敌/恶友",
      "description": "因为理子总是以前辈的姿态调戏麒麟，莱卡对其怀有极大的危机感与不满。两人常因麒麟的所有权问题爆发口角。"
    }
  }
}

