    {
      "name": "CVR专业素养 (CVR Professionalism)",
      "description": "作为特殊搜查研究科的A级武侦，精通利用自身魅力进行套话、诱骗及情报收集。她能完美利用自己“富家千金”的外表掩盖真实的武侦身份，进行极高难度的潜入。"
    },
    {
      "name": "超感官观测 (Acute Observation)",
      "description": "虽然并非超能力者，但在长期针对特定目标（如亚里亚）的关注中，磨炼出了极强的细节捕捉能力，能通过细微的神态变化推测对方的心境。"
    },
    {
      "name": "武道/护身术 (A-Rank Combat)",
      "description": "尽管主要负责文职或渗透，但作为武侦高的A级学生，具备坚实的格斗与射击基础，能在突发状况下实现迅速自卫。"
    },
    {
      "name": "家政流搜查 (Domestic Intelligence)",
      "description": "通过插花、烘焙等传统才艺在社交圈中建立极高的人望，从而在无意间获取各界上流社会的高价值情报。"
    }
  ],
  "relationships": {
    "神崎·H·亚里亚": {
      "nature": "单向崇拜、爱慕、憧憬的偶像",
      "description": "由佳里在某次强袭科的研习中被亚里亚那种强大、凛然且充满斗志的身影深深吸引。她将亚里亚视为女性力量的极致体现，对其抱有超越友谊的强烈好感。虽然平时表现内敛，但面对亚里亚时常会陷入轻微的自我陶醉或极度热情的奉献状态。"
    },
    "远山金次": {
      "nature": "竞争对手（由于嫉妒）、观察对象",
      "description": "因为金次总是待在亚里亚身边并担任其搭档，由佳里对他抱有一种隐约的嫉妒心。她认为金次这样的“平凡男性”（在她眼中的伪装）并不足以配得上亚里亚，常以审视甚至排斥的态度对待金次。"
    }
  }
