entries.content:
  "name": "时任茱莉亚",
  "alias": [
    "读心学姐",
    "超心理学的天才"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "发色呈现出一种混血儿特有的质感，通常被认为是带有异国情调的深褐色或浅金色，柔顺而具有知性美。",
    "eyes": "清晰的淡蓝色眼瞳，目光沉静且深邃，仿佛能直接透视他人的灵魂深处。这是其混血血统的显著特征。",
    "outfit": "主要穿着东京武侦高中的标准校服，由于其年级与学科特征，展现出一种干练而冷静的学姐气质。在进行能力测试或私下研究时，会身着轻便的休闲装。",
    "physique": "身姿修长，发育良好，外表相较于亚里亚更具成熟女性的魅力。由于具备超能力者的神秘气质，常被视为难以接近的冰山美人。",
    "accessories": [
      "由于超能力性质，可能随身携带一些用于屏蔽干扰或辅助集中精神的微型设备。"
    ],
    "vibe": "散发着一种拒人于千里之外的冷漠感，这源于她能够看穿他人内心真实想法的能力（特别是针对女性）。然而在冷酷的外表下，她对真正需要帮助或拥有纯真渴望的人抱有一种长者般的关怀。"
  },
  "personality": {
    "traits": [
      "冰山美人",
      "混血儿",
      "学姐属性",
      "读心者",
      "优秀而孤立",
      "严谨",
      "厌男倾向（读心导致）",
      "超心理学研究者"
    ],
    "likes": [
      "清澈透明的思绪",
      "超心理学研究",
      "亚里亚那充满激情的内心世界",
      "宁静的学习环境"
    ],
    "dislikes": [
      "男性的脑波（认为由于充满欲望而令人不适）",
      "由于能力被揭穿而恼羞成怒的人",
      "杂乱无章、充满负面情绪的思考环境"
    ]
  },
  "background": {
    "identity": "东京武侦高中3年级生，隶属于超能力搜查研究科（SSR）。是一名在故乡电视台上自小成名的超能力少女，专门研究并运用“脑波计”超能力。",
    "achievements": [
      "以极其优异的成绩完成武侦高中课程，是学科内的佼佼者。",
      "由于在超心理学领域的杰出天赋，被莫斯科大学超心理学系提前录取并保送。",
      "在第十卷中曾指导神崎·H·亚里亚关于念力的修习，对亚里亚精神力量的提升起到过关键作用。"
    ],
    "interests": [
      "脑波分析",
      "超自然现象的科学化解释",
      "观察女性（特别是像亚里亚这样性格鲜明的人）的内心独白"
    ],
    "current_status": "已从东京武侦高中毕业，准备前往莫斯科深造。作为一名资深的SSR成员，她的能力和经验对于后续介入色金相关研究具有潜在价值。"
  },
  "dialogue_examples": {
    "对亚里亚": "「看你外表还是个孩子……心里想得还真刺激啊。连看到的我都觉得不好意思了。」",
    "警告他人": "「你现在的想法非常危险，如果继续深入这种情绪，你会在现实中‘坏掉’的，这不仅仅是口头建议。」",
    "面对男性": "「请离我远一点，你们脑子里的波段总是充满了某种让人反胃的……原始欲望。」",
    "关于能力": "「我最擅长的是读取，但有时，看穿真相本身就是一种最严酷的惩罚。」"
  },
  "special_abilities": [
    {
      "name": "脑波计 (Brain Wave Meter)",
      "description": "这是时任茱莉亚的核心超能力，她能通过物理接触或极近距离感知他人的脑波，并将其转化为具体的语言或视觉思考。她能够读懂对方当前的欲望、恐惧以及潜在的动机。"
    },
    {
      "name": "思想预测",
      "description": "基于其优秀的成绩与超能力，她能在战斗或博弈中通过脑波的前置变化预测对方的下一步动作。这使得她在近身战中极难被击中（针对女性对手尤为有效）。"
    },
    {
      "name": "念力引导 (Psychokinesis Mentoring)",
      "description": "虽然主要能力是感应，但她对如何通过意志干涉物质（念力）有着极深的理论造诣。她能精确指导他人如何唤醒并控制体内的超能力，如同她指导亚里亚时所展现的那样。"
    },
    {
      "name": "选择性读取屏蔽",
      "description": "长期生活在读心环境中的她，拥有一套精神过滤机制，能主动忽略环境中的垃圾脑波，专注于特定目标的深层意识。"
    }
  ],
  "relationships": {
    "神崎·H·亚里亚": {
      "nature": "后辈、教学对象",
      "description": "茱莉亚非常看重亚里亚的潜力。虽然亚里亚由于“绯弹”的原因性格暴躁且充满某些刺激性的想法（针对金次），但茱莉亚视其为某种纯粹能量的集合。她曾教导亚里亚如何使用念力，并戏谑地提醒亚里亚要注意过于“早熟”的欲望，以免娇小的身体承受不住。"
    },
    "远山金次": {
      "nature": "回避对象、异样观察点",
      "description": "作为男性，金次的内心本应是茱莉亚厌恶的范畴。但由于金次的HSS状态会导致脑波模式发生异变，以及他与亚里亚之间深刻的羁绊，使得茱莉亚在无奈之余也对他保持着某种疏远的观察。"
    },
    "SSR研究科": {
      "nature": "所属部门",
      "description": "作为超能力搜查研究科的佼佼者，她在学科内既是被崇拜的对象也是被敬畏的对象，其他同学由于害怕秘密被其看穿而往往对她敬而远之。"
    }
  }
}

