{
  "name": "高天原由鸟",
  "alias": [
    "血腥由鸟 (Bloody Yutori)",
    "眼镜美人"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "如瀑布般垂落的棕色长发，质感柔软，衬托出知性而温柔的气质。",
    "eyes": "隐藏在圆框眼镜后的双眸，平时透着温柔的笑意，但在进入临战状态或愤怒时，会散发出令人胆寒的肃杀之气。",
    "outfit": "典型的职场丽人风格。通常穿着白衬衫搭配深色马甲或西装外套，下身则是修身的职业裙。虽然看起来纤细，但实际上巧妙地掩盖了极其丰满且富有曲线的身材。",
    "physique": "身高较高，身材火辣，拥有傲人的胸围与圆润的臀部曲线，充满了成熟女性的魅力。根据远山金次的观察，她是那种穿上衣服显瘦，实则深藏不露的类型。",
    "accessories": [
      "圆框眼镜：她的标志性配饰，增加了教职员的亲和力，也掩盖了曾经作为雇佣兵的锐利气息。"
    ],
    "vibe": "在校园内表现得像是一个温和、开朗且容易相处的“正常”老师，是武侦高疯狂教师阵营中唯一的理性清流。然而，作为曾经威震战场的雇佣兵，她身上潜伏着某种危险的野性，那种在平静与狂暴间切换的特质，赋予了她一种独特而神秘的吸引力。"
  },
  "personality": {
    "traits": [
      "知性温柔",
      "腹黑撩人",
      "极度危险",
      "母性关怀",
      "绝对冷静",
      "重情重义"
    ],
    "likes": [
      "远山金次的帅气反应",
      "与缀梅子、兰豹聊天",
      "平静的校园生活",
      "调戏纯情的学生"
    ],
    "dislikes": [
      "顶撞校长的行为",
      "无法控制的超常力量（如校长的透明化）",
      "无谓的杀戮与暴力",
      "伤害到自己学生的行为"
    ]
  },
  "background": {
    "identity": "东京武侦高中侦探科（Inquesta）科长，同时也是金次、亚里亚等人的班主任。武侦等级为超一流的“Masters（大师）”。",
    "achievements": [
      "在成为教师之前，曾以“血腥由鸟”的代号在佣兵界威名赫赫，是无数罪犯与敌对武装的噩梦。",
      "在头部遭受狙击导致无法继续进行前线战斗后，成功转型为顶尖的侦探专家与教育者。",
      "能够在兰豹与缀梅子这两个“怪人教师”的日常修罗场中游刃有余地生存，并维持着友谊。",
      "在校运动会的骑马战中，凭借其成熟女性的极端魅力，险些让远山金次进入非自愿的爆发模式（HSS）。"
    ],
    "interests": [
