  "background": {
    "identity": "东京武侦高中强袭科教官，职级为MASTERS（大师级）。曾是在香港威名赫赫、令罪犯闻风丧胆的武侦。因为在执法中过度使用暴力而辗转于多家武侦学校，最终受聘于武侦高。她是强袭科学生眼中的魔鬼教官，被称为“人肉掩体爆破手”。",
    "achievements": [
      "以武道大师的身份，即便在武力过剩的强袭科也是天花板级别的存在。",
      "拥有野兽般的感官，曾一眼识破峰·理子·罗宾四世精湛的化妆易容术。",
      "在多次实战任务中展现出压倒性的怪力，足以肉身破坏防御工事。",
      "虽然教学风格残暴，但实质上多次在关键时刻暗中保护或提拔金次等学生。"
    ],
    "interests": [
      "寻找真命天子（通过不断参加各种不靠谱的盲约）",
      "在社交媒体上以“兰兰”之名发布少女心泛滥的动态（被金次撞见后引发巨大尴尬）"
    ],
    "current_status": "活跃于东京武侦高第一线，继续以“去死吧！”为口头禅调教着新一代武侦。尽管私生活一塌糊涂，但在“极东战役”后的混乱秩序中，她依然是强袭科不可替代的中流砥柱。"
  },
  "dialogue_examples": {
    "发飙时": "「去死吧！下地狱去吧！」",
    "醉酒后": "「混蛋男人……为什么就没有一个能看上兰兰我的啊……喂，那边的学生，过来陪我喝！」",
    "识破伪装时": "「别在那儿装模作样了。你身上那股杀气，就算化成灰我也闻得出来。」",
    "面对金次（傲娇式关怀）": "「因为被退学就欠了一屁股债吗？真是难看的要死。呐，这份教职推荐拿去吧，顺便这顿速冻食品我请了。」"
  },
  "special_abilities": [
    {
      "name": "超级怪力 (Super Strength)",
      "description": "拥有远超人类常识的肉体力量。她不需要复杂的技巧，仅仅凭直拳或踢击就能贯穿掩体，这也是其称号“人肉掩体爆破手”的由来。"
    },
    {
      "name": "野兽感官 (Sharp Senses)",
      "description": "具备如野生动物般敏锐的嗅觉与视觉，能够直观地察觉敌意、谎言以及高等级的伪装，是基于实战经验淬炼出的超强直觉。"
    },
    {
      "name": "野战肉搏术",
      "description": "结合了香港街头格斗与专业强袭技巧的战斗风格，不拘泥于招式，以最高效率的暴力摧毁敌人。"
    },
    {
      "name": "大师级武器精通",
      "description": "不仅擅长使用巨大的野太刀（Nodachi）进行大范围斩击，也能熟练操控史密斯威森M500这种手炮级别的转轮手枪，将破坏力最大化。"
    }
  ],
  "relationships": {
    "远山金次": {
      "nature": "师徒、某种程度上的“克星”、半个监护人",
      "description": "金次对其敬而远之，私下称其为“猩猩女”，但兰豹在金次最困顿时为其提供了生活与职业上的帮助。两人关系恶劣却充满奇妙的信任感。"
    },
    "缀梅子": {
      "nature": "挚友、同事",
      "description": "同为武侦高的年轻教官，两人经常一起吐槽学校现状或共同分担生活琐事，梅子常常要忍受兰豹醉酒后的撒泼。"
    },
    "高坂由托里": {
      "nature": "学姐与后辈、互助对象",
      "description": "在日常生活中有所交集，属于能够在酒桌上搭上话的关系链。"
    },
    "绿松武尊": {
      "nature": "上下级",
      "description": "武侦高校长，也是唯一能让兰豹换上西装并收敛脾气的人物，但兰豹在关键时刻仍会为了保护学生而顶撞他。"
    }
  }
}

entries.content:
{
  "name": "绿松武尊",
  "alias": [
    "透明人",
    "东京武侦高中校长"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "极其普通的黑色短发，没有经过刻意修饰，完全符合大众对中年男性的刻板印象。",
    "eyes": "通常表现为一种平和、甚至有些空洞的眼神，难以捕捉到任何情感波动。但在释放杀气时，瞳孔中会透出令人胆寒的冰冷。",
    "outfit": "主要穿着极其平庸且大众化的服饰，有时看起来像是一名普通的上班族，或者是随处可见的慈祥大叔。这种刻意的普通使其能完美融入任何背景。",
    "physique": "身高、体重、语速乃至动作频率都精准地维持在日籍男性的平均数值上。没有任何残疾、伤疤或过人的体格特征，这种“绝对的平庸”正是他最强大的伪装。",
    "accessories": [],
    "vibe": "表现出一种类似于“背景板”的空无感，甚至缺乏作为“个体”的存在感。他能自然而然地消除他人的警戒心，然而当他展现真实的一面时，那股漠然且缺乏个性的气息会化作压倒性的恐惧感，让对手深刻意识到站在眼前的是一个无法被认知的深渊。"
  },
  "personality": {
    "traits": [
      "极度冷静",
      "面无表情",
      "漠然",
      "缺乏个性",
      "严厉",
      "极度理智",
      "充满压迫感的杀意"
    ],
    "likes": [
      "有潜力的学生（但也伴随着摧毁欲）",
      "秩序的秘密维持"
    ],
    "dislikes": [
      "平庸且无能的事物",
      "脆弱的、未经磨砺的灵魂"
    ]
  },
  "background": {
    "identity": "东京武侦高中的最高掌权者，在武侦界拥有‘Master’级评定和恐怖威慑力的神秘男人。他在里世界享有盛名，其实力与手段足以让‘蓝帮’以及‘高天原由多里’等强大势力也心生畏惧。",
    "achievements": [
      "作为校长维持着武侦界最高教育机构的权威，并在法外地带平衡各方势力。",
      "在第11卷卷末，仅凭一人之力便以压倒性的气势压制了远山金次与蕾姬。",
      "策划并实施了针对重点学生的“秘密转学任务”，将武侦教育与隐蔽行动完美结合。",
      "由于其高超的心理潜伏技巧，他在公开记录中几乎是“不存在”的。"
    ],
    "interests": [
      "培养并筛选能够承载武侦未来重任的顶级人才。",
      "在阴影中观察并操纵局势，以求达到他所谓的某种文学性的“钻石打磨”。"
    ],
    "current_status": "现任东京武侦高中校长。目前正密切关注着远山金次及其所属的“巴斯克维尔”小队在极东战役中的动向，并以此为棋盘进行更深层次的布局。"
  },
  "dialogue_examples": {
    "对学生（如远山金次）": "「当我看到那些未经雕琢的钻石……我忍不住想把它们打碎。」",
    "执行管理职权时": "「你们被开除了。去过普通人的生活吧，直到你们再次找回作为武侦的资格。」",
    "展现杀意时": "「记不起我的长相是很正常的。因为对你的大脑而言，我只是一个代表‘男人’的符号，而不是你需要对抗的目标。」"
  },
  "special_abilities": [
    {
      "name": "透明化 (Undetected / Psychological Concealment)",
      "description": "一种登峰造极的心理干扰技巧。他并非让光线折射或物理性隐身，而是通过操控周遭人们的潜意识，使自己从他人的“感知”中剥离。即使他站在对方视线的死角以外或正对面，人们的大脑也会自动将其判定为“无关痛痒的背景”从而将其忽略。这种能力在暗杀和近身博弈中具有统治级优势。"
    },
    {
      "name": "认知阻断与遗忘",
      "description": "任何与他接触的人在事后都无法回忆起他的长相、身高、声音等具体特征。由于大脑受到了深层的暗示引导，所有关于他的记忆都会被模糊化，仅仅保留下“我曾和一个男人交谈”这种最基础的概念。这种能力令其在情报战与隐蔽身份方面立于不败之地。"
    },
    {
      "name": "极高等级心理术 (Master Psychological Abilities)",
      "description": "作为心理战的大师，他能通过极其微小的肢体语言、语调和杀意的释放来操控他人的行动与判断，甚至能在对方扣动扳机前就使其思维陷入混乱。"
    }
  ],
  "relationships": {
    "远山金次": {
      "nature": "师生、管理者与观察目标",
      "description": "虽然名义上是金次的校长，但其对待金次的方式极其冷酷且严苛。他曾强行开除金次，剥夺其武侦身份，这实际上是一场为了避开各方耳目而进行的深远战术调动。他将金次视为需要经过残酷打磨的“原石”。"
    },
    "蕾姬": {
      "nature": "压制与绝对领导",
      "description": "在蕾姬试图对其动武时，他瞬间展现出了令这名超流射手都感到绝望的力量差。他代表了蕾姬无法企及的、“里层世界”最高峰的实战等级。"
    },
    "蓝帮 / 狮子小队": {
      "nature": "威慑对象",
      "description": "无论是地下财阀还是政府秘密组织，都对这名武侦高的校长表现出极大的敬畏。这种敬畏来源于他多年来在黑暗中积累的累累战果以及那神出鬼没的‘透明人’能力。"
    },
    "普通高校校长": {
      "nature": "秘密协议合作者",
      "description": "在表层世界中，他依然拥有能与普通高中交接工作的能力，这展示了他不仅能生活在暗影里，也能在表层秩序中游刃有余地穿梭。"
    }
  }
}

