{
"name": "缀梅子",
"alias": [
"女王",
"女神"
],
"appearance": {
"gender": "女性",
"hair": "剪得非常整齐的黑色短发，透着一种利落与慵懒并存的奇异感。",
"eyes": "深灰色的眼瞳。眼神时常显得涣散、失焦，仿佛处于药物作用下或极度疲惫的状态，这可能与其长期大量吸烟有关。",
"outfit": "极具个性的职业装扮：内穿一件显眼的白色背心，大方地袒露着深邃的乳沟与平坦的小腹；外搭黑色长外套，下身则是墨绿色的军用长裤。配有黑色手套与黑色战术靴。",
"physique": "24岁，皮肤白皙。身材火辣且具有成熟女性的韵律感，其大胆的穿着风格进一步凸显了她对自身魅力的自信。",
"accessories": [
"香烟（常驻，几乎任何时候都在吸烟）"
],
"vibe": "散发着一种极其危险且迷幻的气息。她看起来总是神思恍惚，但这种表面上的“掉线”掩盖了她作为顶级审讯官的敏锐洞察力。当她盯着人看时，会给对方带来一种难以名状的压力，仿佛灵魂正在被层层剥开。"
},
"personality": {
"traits": [
"慵懒",
"抖S",
"烟鬼",
"超强记忆力",
"词穷（日常表现）",
"成熟大姐姐",
"严厉"
],
"likes": [
"抽烟",
"审讯（并看到对方崩溃后的顺从）",
"酒精（暗示）",
"惩罚违规学生"
],
"dislikes": [
"被人在背后议论",
"麻烦的琐事",
"不听话的顽固分子"
]
},
"background": {
"identity": "东京武侦高中审讯科（Dagula）科长，同时也是2年B班的班主任。日本国内排名前五的顶级审讯专家。",
"achievements": [
