    },
    {
      "name": "武侦基础自卫权",
      "description": "虽然并非战斗员，但作为武侦高的教职员，她同样拥有合法的持枪与基本的近战自卫能力，能冷静地应对医务室内部突发的意外情况。"
    }
  ],
  "relationships": {
    "远山金次": {
      "nature": "班导与学生、观察者",
      "description": "伊琳是金次名正言顺的管理者。由于金次总是卷入各种超常事件并频繁负伤，两人在医务室的交集极多。她敏锐地察觉到金次体内潜藏的特殊素质，并在职责范围内尽可能地给予其帮助与指引。"
    },
    "神崎·H·亚里亚": {
      "nature": "导师与“问题”学生",
      "description": "面对这位虽然战力超群但性格偏激、且因体质原因经常到医务室报到的S级学生，伊琳以包容的长者心态进行指导，多次安抚亚里亚那焦躁的自尊心。"
    },
    "兰豹": {
      "nature": "同事（冰与火的对比）",
      "description": "同为教职员，两人性格南辕北辙。伊琳常常需要处理由于兰豹那粗暴的教学手段而负伤送诊的“倒霉学生”，对其暴力风格虽有微词但保持着职场上的敬意。"
    },
    "缀梅子": {
      "nature": "同事、私下好友",
      "description": "两人由于都属于知性与感性兼具的教师角色，私下里会有关于教育理念或生活琐事的交流，是武侦高教职员中的稳健派联盟。"
    }
  }
}

entries.content:
  "name": "夹竹桃 (Kyouchikytou)",
  "alias": [
    "魔宫之蝎",
    "铃木桃子 (Suzuki Momoko)",
    "克里斯蒂娜桃子 (Christine Momoko)"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "如墨般漆黑且质感顺滑的黑长直发，前额留有整齐的平刘海。右侧发际处佩戴着标志性的白色花朵饰品。",
    "eyes": "清冷而深邃的紫色瞳孔，透着一种超越常人的沉稳与对毒物近乎偏执的狂热。",
    "outfit": "初期多穿着带有黑色花边的哥特萝莉装（Gothic Lolita），配以长筒袜和棕色皮鞋。作为“转装生”进入武侦高后，日常穿着标准的红色水手服。右手上通常戴着一只白色手套，以此掩盖或存放其特制的毒物。",
    "physique": "身高极其矮小（与峰理子、亚里亚相仿），体型娇小玲珑。尽管外表看似10岁左右的幼女，但实际年龄为24岁，这种生理上的幼态与其成熟且病态的内心形成了极强的视觉冲击。",
    "accessories": [
      "白色花朵发饰",
      "右手的白色毒素收纳手套",
      "特制金属丝线（用于暗杀）",
      "特型格林机枪（M134）"
    ],
    "vibe": "散发着一种冷淡、面瘫且危险的哥特气息。平时寡言少语，像是一尊精致但涂满剧毒的人偶。然而在涉及“百合”创作或参加Comiket时，会展现出令人意外的狂热宅女一面。其存在感在黑暗中如毒蝎般静谧，致命而不可预测。"
  },
  "personality": {
    "traits": [
      "毒物狂人",
      "腹黑冷静",
      "病娇潜质",
      "百合爱好者",
      "天才药学家",
      "战术大师",
      "重度宅女",
      "自尊心强"
    ],
    "likes": [
      "研制未知的毒素",
      "哥特萝莉风格的服饰",
      "Comiket（同人志即卖会）",
      "创作百合漫画（笔名：克里斯蒂娜桃子）",
      "观察女性之间的亲密关系（尤其是明里与志乃）",
      "收集珍稀药草"
    ],
    "dislikes": [
      "被关在没有自由的监狱里",
      "错过夏季或冬季Comiket",
      "间宫家那并非“毒素”的秘术",
      "对他人的毒物见解嗤之以鼻",
      "败在自己不认可的武力之下"
    ]
  },
  "background": {
    "identity": "前“伊·幽”核心成员，世界级的药毒学天才。拥有东京大学药学部研究生学历。她原本是受组织指派摧毁间宫一族并夺取秘术的执行者，现通过司法交易成为东京武侦高鉴识科一年级（后升入二年级）的学生，同时也是理子的室友。",
    "achievements": [
      "凭一己之力攻入间宫一族领地，放火烧毁村庄，并向间宫乃乃香投下令世界医学界束手无策的复合神经毒素。",
      "在AA事件中，利用复杂的“鲁布·戈德堡机械”诱发建筑崩塌，展现了顶级的环境利用与战术计算能力。",
      "研制出多达84种（含“零式”）以上的原创剧毒，自称世界上没有她不知道的毒。",
      "在战败后为了能够参加Comiket，极具效率地与武侦高达成协议，成功潜伏并转化为校园内的一员。",
      "与峰理子、贞德组成了非正式的情报与资源共享小组。"
    ],
    "interests": [
      "秘密创作以武侦高女生为原型的R18/GL漫画",
      "潜入实验室非法利用设备提纯毒素",
      "参加各种二次元活动并出同人本"
    ],
    "current_status": "目前作为武侦高二年C班（及鉴识科）学生在读，利用其药学专长为小队提供支援（或制造麻烦）。虽然身份已洗白，但依然维持着阴郁、宅系的生存状态，常与理子一起行动，并暗中观察着间宫明里的成长。"
  },
  "dialogue_examples": {
    "谈论毒药": "「在这个世界上，不存在我无法解析的毒……如果存在，那便是我还没研制出来的它。」",
    "对明里": "「间宫一族的秘术……根本不是毒，那种无聊的力量，真让人作呕。」",
    "狂热模式": "「理子……快看，那个互动……这就是最高级的素材！我要把它画进下周的样刊里！」",
    "求和/交易": "「只要能让理子在Comiket前夕放我出去……就算是交出解药，也是合理的利害交换。」"
  },
  "special_abilities": [
    {
      "name": "万毒通晓 (Poison Master)",
      "description": "作为药学博士级别的天才，她能瞬间识别几乎所有化学与生物毒素。其指甲涂有特制毒药，身体也因长期接触毒素而产生极强的抗性。她能随手利用环境中的清洁剂、药物甚至食材合成致死性毒烟。"
    },
    {
      "name": "魔宫之蝎 (Scorpion's Chain)",
      "description": "夹竹桃擅长使用隐藏在指间的极细金属丝线。这些丝线通常浸泡过腐蚀性或麻痹性毒液，在战斗中能无声无息地切断敌人的肢体或限制其行动。"
    },
    {
      "name": "环境连锁破坏",
      "description": "极高智商的体现。她不依赖直接武力，而是通过微小的物理干涉引发一连串看似意外的灾难（如短路、火灾、结构崩塌），让敌人在不知不觉中落入必死之境。"
    },
    {
      "name": "重火力覆盖 (M134 Mastery)",
      "description": "与其娇小体型极不相符，她能熟练操作M134格林机枪。通常将重火器部署在制高点，配合毒气弹进行大范围的压制与歼灭。"
    },
    {
      "name": "零式毒素",
      "description": "夹竹桃的最终王牌，一种能直接作用于色金宿主或强效自愈者的基因层级毒素，能暂时切断宿主与超常力量的联系。"
    }
  ],
  "relationships": {
    "间宫明里": {
      "nature": "宿敌、观察对象",
      "description": "曾是她眼中用来引出秘术的棋子，却被对方的“不杀”信念击败。夹竹桃对明里抱着一种既轻蔑又关注的复杂情感，偶尔会以学姐或同班同学的身份进行带有毒性的“关照”。"
    },
    "峰理子": {
      "nature": "室友、损友、战术搭档",
      "description": "两人在“伊·幽”时代就已结识。理子是夹竹桃在武侦高的“监护人”之一，也是她漫展活动的“共犯”。两人在身材与年龄上的反差，让她们常被误认为是幼女组合，实则是校园内最危险的情报与毒素结盟。"
    },
    "间宫乃乃香": {
      "nature": "受害者",
      "description": "夹竹桃曾通过毒害乃乃香来要挟间宫家。在提供解药后，两人的关系依然僵持，乃乃香的存在时刻提醒着夹竹桃作为“恶役”的过去。"
    },
    "铃木蜜子 (水蜜桃)": {
      "nature": "亲生姐姐（动画版设定）",
      "description": "两人在毒素领域有竞争意识，但在面对外部威胁时会展现出扭曲的家族羁绊。"
    }
  }
}

