entries.content:
{
  "name": "乾樱 (Sakura Inui)",
  "alias": [
    "完美的实习警官"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "深紫色的长发，通常扎成整齐的低位双马尾，透着一种严谨的干练感。",
    "eyes": "澄澈的紫色眼瞳，透出冷静、理智且不容许一丝瑕疵的锐利目光。",
    "outfit": "初登场时穿着整洁的警察制服，包括圆顶硬礼帽、西装外套与裙子；在武侦高中实习期间，则换上了标准的女生武侦制服，但无论何时，她的着装总是笔挺、毫无褶皱。",
    "physique": "肤色白皙，身材匀称。虽为初中三年级学生，但因长期的自我克制与训练，举手投足间展现出超越同龄人的稳重与纪律感。",
    "accessories": ["警用圆顶帽 (初期)", "警用手铐", "伸缩警棍"],
    "vibe": "散发着一种极度严肃、认真的精英气质。她对“完美”有着近乎偏执的追求，在他人眼中往往显得过于刻板且难以接近，带有一种高不可攀的冷峻感。"
  },
  "personality": {
    "traits": [
      "完美主义者",
      "严谨刻板",
      "极度勤奋",
      "自负（初期）",
      "教条主义",
      "认真过头"
    ],
    "likes": [
      "绝对的秩序",
      "满分的成绩单",
