    "对远山金次": "「……多谢你的枪，我会好好利用它的。」",
    "战斗中": "「你的动作，在我的红眼中不过是慢镜头罢了。」",
    "对妹妹": "「祈，只要我还在，谁也别想把你带走。」",
    "日常": "「这种麻烦的日常生活，真希望能早点结束啊。」"
  },
  "special_abilities": [
    {
      "name": "绯红之瞳 (Eye of Vermillion)",
      "description": "静刃的核心超感官异能。激活时右眼呈现血红色，类似于实时战斗平显（HUD）。赋予使用者夜视、热成像及X光视觉。其核心功能是极其精确的“预读”，能根据目标的肌肉收缩和重心移动预测敌方下一步动作。持续时间约3分钟，之后需要较长的冷却时间。"
    },
    {
      "name": "碎裂之牙 (Piercing Fang)",
      "description": "利用极速挥动的剑刃压缩空气，瞬间释放出超音速冲击波。这种非物理接触的攻击威力巨大，足以粉碎混凝土并将目标击飞。缺点是威力随距离增加呈指数级下降。"
    },
    {
      "name": "刃剪 (Blade Shears)",
      "description": "一种精妙的捕获技。将双剑以“X”形交叉嵌入墙面或地面，将目标的颈部或其他部位卡在剑脊之间，用于在不伤及性命的情况下制服敌人以便审讯。"
    },
    {
      "name": "Quadra 精通",
      "description": "具备在移动中完美切换近身刀剑搏杀与中远距离精确射击的顶级战斗天赋。其战术逻辑是以冷兵器制造破绽，用热兵器进行收割，或反之，达到了“四相全能”的实战境界。"
    }
  ],
  "relationships": {
    "远山金次": {
      "nature": "宿命的竞争对手、战友、镜像映射",
      "description": "两人性格与经历惊人相似。金次曾将枪械借予静刃，这象征着某种战士间的认可与信赖。虽然所属组织与立场不时有交叉甚至冲突，但两人在灵魂深处存在强烈的共鸣。"
    },
    "橘·宾妍·爱莉丝贝尔": {
      "nature": "搭档、命运共同体、契约者",
      "description": "由于偶然的邂逅改变了彼此的命运。她是静刃踏入残酷战斗世界的契机，两人在生离死别的战斗中建立起了不可动摇的深厚羁绊，尽管相处过程中也充满了各种令静刃头疼的琐事。"
    },
    "原田祈": {
      "nature": "亲妹妹、唯一的亲人、心理支柱",
      "description": "静刃一切行动的动力源泉。为了让祈过上平凡幸福的生活，静刃甘愿深陷黑暗的异能世界，独自承担所有的血腥与罪恶。"
    }
  },
  "equipment_inventory": {
    "妖刕 & 黑漆": {
      "type": "打刀",
      "description": "静刃使用的两把特殊合金制武士刀。不仅极其锋利，还能与“绯红之瞳”产生感官共鸣，刀身的轻微震动可以向静刃反馈目标的方位信息。"
    },
    "陶鲁斯愤怒公牛 (Taurus Raging Bull)": {
      "type": "左轮手枪",
      "description": "大威力手枪，静刃常用来在剑斗中突然发难，利用大口径弹药的停止作用强行中断敌方技能。"
    },
    "温彻斯特 M1887": {
      "type": "杠杆式霰弹枪",
      "description": "作为备用武装，用于应对复数敌人的压制射击或近距离的破坏性突击。"
    }
  }
}

entries.content:
 {
  "name": "立花·冰焰·爱丽丝贝尔",
  "alias": [
    "魔剑",
    "Samurai Girl",
    "立花·冰焰·阿理斯贝尔"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "如夜空般深邃的黑色长发，通常扎成标志性的双马尾，末端系有红色的发绳，透出一种灵动而干练的气息。",
    "eyes": "澄澈如冰的蓝色眼瞳，如同蓝宝石般明亮，在战斗或动情时会流露出极强的意志力。",
    "outfit": "由于曾是香港名流并后流转至日本，她常穿着东京武侦高中的女生制服：经典的白色水手服上衣搭配红色领结，以及红色格纹百褶短裙，兼具少女感与战术实用性。",
    "physique": "体态娇小玲珑（Loli体型），但肌肉分布极其紧凑，拥有超越常人的平衡感与爆发力。皮肤白皙，整体给人一种精致如玩偶却充满攻击性的反差感。",
    "accessories": [
      "红色发带",
      "东京武侦高校徽"
    ],
    "vibe": "外冷内热。在陌生人面前表现出如贵族般不可侵犯的矜持与疏离感，但在熟人及恋人面前则会显露出易怒、羞涩且傲娇的少女本性，这种极端的性格反差使她被周围人戏称为典型的“傲娇”角色。"
  },
  "personality": {
    "traits": [
      "傲娇",
      "双马尾",
      "天才战斗者",
      "名门出身",
      "极度重感情",
      "暴力倾向（针对特定对象）",
      "萝莉"
    ],
    "likes": [
      "原田静雪",
      "守护正义",
      "磨练刀法",
      "被在意的人夸奖"
    ],
    "dislikes": [
      "背叛",
      "被轻视",
      "无能为力的情况",
      "对原田静雪图谋不轨的女性"
    ]
  },
  "background": {
    "identity": "轻小说《魔剑的爱丽丝贝尔》的女主角，亦在《绯弹的亚里亚》主线第16卷起登场。原本是香港知名的名流与战士，因故漂泊至日本冲绳。她是神崎·H·亚里亚在平衡世界中的对应存在（Counterpart），同样拥有顶级的血统与武力。",
    "achievements": [
      "曾作为香港的明星级人物活跃，拥有极高的社会知名度。",
      "在冲绳经历了残酷的战斗，并在此期间与原田静雪邂逅，确立了战斗伙伴关系。",
      "成功掌握了超越常规武术的特殊能力“莫比乌斯”。",
      "作为持有“魔剑”称号的强者，在里层世界的争斗中声名远扬。"
    ],
    "interests": [
      "研究格斗技艺",
      "与静雪相处的日常生活",
      "时尚穿搭（虽然表现得不在意）"
    ],
    "current_status": "目前与原田静雪组成了被誉为“动态双人组”的搭档。在多方势力角逐的世界观中，她既是强大的战斗力，也是连接不同篇章与势力的关键人物，始终活跃在对抗邪恶组织的第一线。"
  },
  "dialogue_examples": {
    "对原田静雪": "「笨、笨蛋静雪！谁允许你自作主张保护我的？我可是……‘魔剑’啊！」",
    "对敌人": "「在我的剑刃下颤抖吧。你应该感到荣幸，因为斩断你命运的是立花·冰焰！」",
    "害羞时": "「闭嘴！不许再盯着我看了，再看就……就把你砍成两段！」",
    "坚定意志": "「既然你已经救了我两次，那么这份契约就由我来终结。从此以后，你的背后由我守护。」"
  },
  "special_abilities": [
    {
      "name": "莫比乌斯 (Mebius)",
      "description": "一种能够扭曲或无限化物理干涉概念的高级异能。使其能够在战斗中展现出不可预测的位移与攻击轨迹，犹如莫比乌斯环一般没有终点且循环往复。"
    },
    {
      "name": "方舟之剑“环形边缘” (Ark Sword - Circle Edge)",
      "description": "她的核心武器。一柄构造特殊、蕴含强大能量传导性的单分子振动刃。由于其形状与操作系统的独特性，能够配合其超人的身手发挥出足以切断重装甲的杀伤力。"
    },
    {
      "name": "格斗天才",
      "description": "天生具备对身体重心的完美控制和对弹道的直觉感应，即便不依赖超能力，其剑术与徒手搏击技巧也足以位列武侦社会的顶级阶层。"
    }
  ],
  "relationships": {
    "原田静雪": {
      "nature": "恋人、灵魂伴侣、生死契约者",
      "description": "她生命中最重要的存在。在两次被静雪拯救后，不仅将他视为唯一的依靠，更投入了深沉且纯粹的爱慕。尽管言语上经常冷嘲热讽，但在行动上对他有着绝对的忠诚与保护欲，甚至会为了保护他而不顾自身安危。"
    },
    "神崎·H·亚里亚": {
      "nature": "平行对应者、竞争对手（？）、宿命般的相似感",
      "description": "两人在不同作品中处于相似的定位：同样是双马尾萝莉、同样拥有高贵的血统与顶尖的武力、同样对各自的搭档表现出极度的傲娇。这种跨越作品的同步性，使得她们在设定上存在着某种难以言说的联系。"
    }
  }
}

