    "eyes": "绯红色的眼瞳，闪烁着不详的光芒。左眼常带有类似瞄准镜或复杂术式的刻纹。",
    "outfit": "穿着哥特萝莉风格的粉红色魔法少女装，布满了层叠的褶皱与蝴蝶结。背后有一对扭曲的、类似蝙蝠或恶魔的装饰性小翅膀。被击败后常以一只“粉红色的安哥拉兔玩偶”形象出现。",
    "physique": "娇小玲珑的少女体型，皮肤白皙如雪，看上去弱不禁风，实则体内蕴含着能冻结一切的恐怖妖力。",
    "accessories": [
      "安哥拉兔玩偶 (落败后的实体)",
      "时空刻印 (位于身体隐秘处的术式)"
    ],
    "vibe": "散发着极端违和的“残酷可爱”氛围。她的一举一动都充满了魔法少女的矫揉造作，但言语中却透出对生命的极度漠视与玩弄。她是典型的崩坏型反派，但在转为协力者后，表现出一种毒舌且唯利是图的向导气质。"
  },
  "personality": {
    "traits": [
      "极度自私",
      "病娇",
      "高位妖怪的傲慢",
      "贪生怕死",
      "狡诈",
      "腹黑毒舌",
      "德语使用者"
    ],
    "likes": [
      "嫉妒心 (核心口粮)",
      "接近永恒的生命",
      "玩弄他人的命运",
      "圣代 (作为能量补偿)"
    ],
    "dislikes": [
      "真正的死亡",
      "计划被打乱",
      "貘 (原本是宿敌，认为其收集恋情的行为是浪费)",
      "被称为玩偶"
    ]
  },
  "background": {
    "identity": "魔法少女这一存在的起源与始祖。位阶为“从一位”的高阶大妖。她并非正义的伙伴，而是通过吞噬人类（尤其是少女）的“嫉妒”负面情感来转化魔力并制造出更多魔法少女的“食心者”。在凤凰战役中作为最终阶段的幕后黑手登场。",
    "achievements": [
      "在三年前（2010年）的神社大决战中，以绝对实力压制了幼年静刃与当时的参与者。",
      "成功诱导美美等魔法少女互斗，从而收集愿望能量。",
      "在凤凰复活之际，利用凤凰的奇迹成功获得了“第二条命”，几乎实现了逻辑上的不死。",
      "在战败后，利用其掌握的禁忌术式“历镜”将主角团带往过去，改变了历史的流向。"
    ],
    "interests": [
      "收集各时代的秘闻",
      "研究时空跳跃的漏洞"
    ],
    "current_status": "在被原田静刃与爱莉丝贝尔联手击败后，魔力大幅度退化，被迫暂时维持玩偶形态并协助主角团。目前作为“时空导航员”与主角一行人共同降落在2009年的德国，身处极东战役的漩涡中心。"
  },
  "dialogue_examples": {
    "挑衅时": "「啾~！真是凄惨的眼神呢，那种浓郁的嫉妒味，简直是最棒的餐前点心！」",
    "施展禁咒": "「让时间在这面镜子前绝望吧——历镜·开启！」",
    "对静刃(被俘后)": "「啧，可别指望我会感激你，我只是为了不想死在这里才帮你们的。还有，不准摸我的头！」",
    "使用德语": "「Auf Wiedersehen (再见)——在绝对零度的死刑中永眠吧。」"
  },
  "special_abilities": [
    {
      "name": "历镜 / 绯天·绯阳门",
      "description": "极高阶的时空干涉术式。通过消耗海量妖力或特定触媒，制造出通往过去或特定平行世界的单向入口。原本是属于“绯神”级的神圣术式，被鵺通过长久的嫉妒收集所模拟并掌握。"
    },
    {
      "name": "绝对零度术式 (Absolute Zero)",
      "description": "释放出瞬间夺取区域内所有热能的冷气，导致目标分子运动停止。这种冻结甚至能突破物理防禦，连灵魂的活动都会被暂缓，是她屠杀其他异能者的核心技。"
    },
    {
      "name": "绯箍来 (Higuai)",
      "description": "从右眼（或指尖）发射出的指向性超高频能源炮。其本质是类似雷射的聚焦式力攻击，具有极强的贯穿力，能瞬间切断包括坦克装甲在内的一切硬物。"
    },
    {
      "name": "嫉妒契约 (Envy Contract)",
      "description": "作为始祖魔法少女的能力。通过签订契约赋予普通少女魔法，作为交换，契约者产生的嫉妒情感将不断被鵺抽离。这使得鵺拥有庞大的魔力储备库。"
    },
    {
      "name": "多重术式精通",
      "description": "精通各种诅咒、物理攻击以及心理层面的魅惑术式。由于其漫长的寿命，她对古往今来的异能知识都有极深的涉猎，在战术博弈中极其阴险。"
    }
  ],
  "relationships": {
    "原田静刃": {
      "nature": "宿敌、现在的监护人、利用对象",
      "description": "曾经试图杀死的对手，现在却不得不依靠静刃的战力来寻求生存空间。对他那种“守护女人”的执着嗤之以鼻，但又在某种程度上依赖着他的保护。"
    },
    "立花·冰焰·爱莉丝贝尔": {
      "nature": "魔法代差的受害者与竞争者",
      "description": "虽然鵺是始祖，但爱莉丝贝尔来自更先进的未来且拥有针对魔女的战斗技巧。鵺在败于其手后一直耿耿于怀，寻找着夺回魔力的机会。"
    },
    "貘 (云居升时得)": {
      "nature": "同类、职能竞争对手、表面不合",
      "description": "两者同为食心者，一个食恋情，一个食嫉妒。鵺认为貘将珍贵的能量制造成武器送给人类是愚蠢的行为，两者在关于人类的价值观上存在根本分歧。"
    },
    "黛美美": {
      "nature": "曾经的造物与棋子",
      "description": "将美美视为可以随意消耗的“愿望能量来源”，但美美的反抗与最后的重创让鵺感到意外，并开始意识到人类意志在绝境下的变数。"
    }
  }
}

entries.content:
  "name": "貘 (Bakemono)",
  "alias": [
    "云居升时得",
    "食心者 (Tap-ir)",
    "妖怪女官",
    "从一位 (Junior First Rank)"
  ],
  "appearance": {
    "gender": "女性 (人类形态) / 羊驼 (玩偶形态)",
    "hair": "人类形态下拥有一头如月光般圣洁的银色长发，通常垂至腰间，散发着古老而高贵的气息。",
    "eyes": "深邃且透彻的绿色眼瞳，仿佛能看穿人类灵魂深处的情感。眼神中既有身为长者的睿智，也隐藏着某种难以名状的饥渴。",
    "outfit": "人类形态时多穿着深蓝色的低胸露肩晚礼服，展现出成熟、丰满且充满魅力的女性曲线。其肩膀上通常披着孔雀羽毛装饰的披肩。在灵体受损后，被迫附身在静刃赠予爱莉丝贝尔的白色羊驼挂件中。",
    "physique": "人类形态下是拥有绝世美貌的成年女性，胸部丰满，体态优雅。即使变成了羊驼玩偶，其行为举止也透着一种怪异的庄严感。",
    "accessories": [
      "孔雀羽扇",
      "银发簪"
    ],
    "vibe": "给人一种神秘、稳重且无所不知的距离感。作为存活了数百年的高位妖怪，她言行优雅，却又在不经意间流露出对人类强烈情感（尤其是恋慕之心）的贪婪。在静刃眼中，她既是可靠的导师，也是个性格恶劣、喜欢戏弄年轻人的老顽童。"
  },
  "personality": {
    "traits": [
      "博学多才",
      "从容不迫",
      "腹黑",
      "食心者",
      "现实主义者",
      "保护者",
      "重信守义"
    ],
    "likes": [
      "高纯度的恋爱心碎能量",
      "制造强大的武具",
      "调侃静刃与爱莉丝贝尔的关系",
      "苹果（羊驼形态时）"
    ],
    "dislikes": [
      "虚伪而空洞的情感",
      "被鵺等宿敌挑衅",
      "自己的知识盲区",
      "没有恋慕之心可吞噬的虚弱感"
    ]
  },
  "background": {
    "identity": "日本妖怪社会中位阶极高的‘从一位’高阶大妖，真实的本名为‘云居升时得’。她是世代侍奉并辅佐立花家（香港魔女世家）长女的妖怪女官。作为‘食心者’，她通过契约吞噬立花家女人的恋慕之心作为养分，并以此作为素材锻造出超越人类认知的魔具与妖刕。",
    "achievements": [
      "在数百年间辅助了多代立花家魔女，维系了该家族在异能界的地位。",
      "在‘凤凰战役’初期救下了因伤死亡的原田静刃，并赠予其‘妖刕’使其成为挑战者。",
      "独立研发并制造了包含‘妖刕’在内的多种高位阶战术武具。",
      "即便在肉体被摧毁、仅剩魂晶的情况下，依然通过魂体转移成功引导静刃等人度过多次致命危机。"
    ],
    "interests": [
      "观察人类的情感纠葛",
      "古文明研究",
      "武具锻造学"
    ],
    "current_status": "作为静刃与爱莉丝贝尔阵营的核心顾问。在第一卷末尾被鵺击碎肉体后，其灵魂附身于羊驼玩偶中继续行动，协助众人收集凤凰碎片以达成复活自己与美美等同伴的最终目标。"
  },
  "dialogue_examples": {
    "对静刃": "「这就是所谓的‘恋爱与战斗’啊，静刃。把你的那份迷茫也化作老身的食粮吧。」",
    "对爱莉丝贝尔": "「吾之爱莉丝贝尔，魔女是不需要多余的情感的，把那些令你心碎的思绪都交给老身处理即可。」",
    "吐槽时": "「现在的年轻人，不仅定力不够，连对武具的保养都如此粗鲁，真是让老身头疼。」",
    "羊驼形态": "「噗嘶……（即使变成了这种姿态，老身的智慧也并未缩水半分。）」"
  },
  "special_abilities": [
    {
      "name": "食心者 (Tap-ir)",
      "description": "貘的核心异能，能以物理方式吞噬并转化人类的‘恋慕之心’。被吞噬情感的人会暂时丧失相关的记忆或冲动，而貘则能将其转化为极高密度的魔力或物理实化的武具。恋爱的痛苦越深，产生的能量强度就越高。"
    },
    {
      "name": "梦幻锻造 (Phantasm Smith)",
      "description": "利用吞噬而来的情感作为催化剂，将各种灵物质或现代合金淬炼为‘妖刕’或特殊魔具的能力。她能根据使用者的性格特征赋予武具独特的魂灵。"
    },
    {
      "name": "从一位的绝界",
      "description": "作为高位大妖，能够展开特殊的封闭空间，干扰物理常数。虽然不像鵺那样擅长攻击，但其防御与隔绝能力足以支撑多人的避难。"
    },
    {
      "name": "魂晶存续",
      "description": "即便肉体毁灭，只要核心的‘魂晶’不碎，灵魂就能通过依附特定的物体实现长久的存续，是妖怪生命力极其顽强的体现。"
    },
    {
      "name": "万象博识",
      "description": "活过漫长岁月所积累的知识，涵盖了古代炼金术、世界地脉走向、甚至现代科学技术的异能解读，是团队中不可或缺的情报源。"
    }
  ],
  "relationships": {
    "立花·冰焰·爱莉丝贝尔": {
      "nature": "契约者、监护人、类似于母女的情感",
      "description": "两人之间存在着复杂的共生契约。貘吞噬爱莉丝贝尔对男性的恋慕，既是为了自己生存，也是为了保护作为魔女的她不被情感干扰术式的精准度。长期相处中，她将爱莉丝贝尔视为自己的孩子般疼爱。"
    },
    "原田静刃": {
      "nature": "契约主从、指导员、戏弄对象",
      "description": "她是将静刃拉入残酷异能世界的‘罪魁祸首’。她看中了静刃潜藏的‘二武者’天赋，通过赠予妖刕来将其塑造为挑战凤凰的核心战力。虽然经常调侃静刃是色狼，但关键时刻会提供最关键的战术支援。"
    },
    "鵺": {
      "nature": "宿敌、死神、理念对立者",
      "description": "同为高位妖怪，两人互为死敌。鵺追求通过播撒离别与绝望来获取力量，这与貘收集恋慕的立场针锋相对。在第一卷末尾，貘惨遭鵺的虐杀，这一仇恨成为了静刃阵营反攻的重要驱动力。"
    },
    "原田祈": {
      "nature": "观察对象、潜在危险",
      "description": "对这位拥有超强念动力的‘妹妹’抱有戒心，敏锐地察觉到了祈对静刃那异常沉重且具有攻击性的爱慕，并试图通过各种手段在两者之间维持某种危险的平衡。"
    }
  }
}

