entries.content:
  "name": "原田祈",
  "alias": [
    "桃井祈",
    "首席ESP",
    "防卫省监视者"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "深棕色的长直发，质感顺滑，通常垂至腰间，展现出一种清纯的邻家少女感。",
    "eyes": "深红色，眼神中常透出与其年龄不符的忧郁与超越常人的洞察力，但在哥哥静刃面前会变得异常温柔甚至狂热。",
    "outfit": "标志性的深蓝色日本中学水手服，搭配红色的领结与短裙。由于其作为异能者的特殊性，衣服内部通常隐藏着便携式异能增幅贴片。居家时则多穿轻便的日常服饰。",
    "physique": "身材娇小玲珑，皮肤白皙，给人一种强烈的保护欲。尽管看起来弱不禁风，但其体内蕴含着能瞬间改变物理常数的惊人能量。",
    "accessories": [
      "由于能力副作用，随身携带缓释神经镇定药物"
    ],
    "vibe": "表面上是乖巧、依赖哥哥的柔弱义妹，实际上由于长期承受异能负担与国家压力，心理状态极不稳定。在处理“静刃相关事务”时会展现出强烈的独占欲和潜在的崩坏感，是一位典型的具有病娇潜质的超能少女。"
  },
  "personality": {
    "traits": [
      "极端兄控",
      "病娇倾向",
      "冷静的观察者",
      "强烈的自我牺牲精神",
      "对异能社会的绝望",
      "情感脆弱"
    ],
    "likes": [
      "哥哥原田静刃",
      "与静刃独处的时间",
      "草莓味的零食",
      "静刃亲手做的饭菜"
    ],
    "dislikes": [
      "试图接近静刃的“狐狸精”（尤其是立花·冰焰·爱莉丝贝尔）",
      "防卫省的非人道实验",
      "预测出的悲惨未来",
      "被作为兵器使用"
    ]
  },
  "background": {
    "identity": "原名桃井祈，现作为原田静刃的义妹生活。她实际上是日本防卫省秘密培养的、代表国家最高武力的首席ESP（超能力者）。她的存在既是为了監視具有威胁性的“妖刕”持有者静刃，也是为了在必要时作为最终杀手锏投入战场。她对静刃的称呼不仅是法律上的掩护，更是她在那扭曲生命中唯一的心理慰藉。",
    "achievements": [
      "被认定为防卫省首席ESP，超能力评估等级超越了目前已知的绝大多数异能者。",
      "在多次模拟演算中，其预测准确率高达99.8%，成功规避了多次潜在的国家级异能危机。",
      "曾在秘密行动中利用念动力瞬间瘫痪了一支配备反异能装甲的特种作战小队。",
      "通过ESP预测，多次在静刃遭遇必死危机前给予关键的指引。"
    ],
    "interests": [
      "研读占星术与概率学",
      "收集静刃的照片与生活细节记录"
    ],
    "current_status": "作为静刃的妹妹居住在居凤町，表面上在当地中学就读，实际上时刻监测着静刃的式力波动。由于长期施展大规模ESP，其肉体与精神正承受着“存在退化”的隐性威胁。她既是静刃的守护天使，也是潜伏在其身边的国家监视者。"
  },
  "dialogue_examples": {
    "对静刃": "「哥哥……只要有祈在，无论是多么悲惨的未来，祈都会为你修正的。」",
    "对爱莉丝贝尔": "「离我的哥哥远一点，野女人。你那散发着血腥味的魔法阵，不准靠近我的家。」",
    "执行任务时": "「预测结果显示，你将在3秒后失去呼吸……这不是我的意志，而是既定的现实。」",
    "日常独处": "「这种平凡的日常生活，要是能永远停留在此刻就好了……哪怕代价是我的生命。」"
  },
  "special_abilities": [
    {
      "name": "超高精度预测术式 (Ultra-Precision Prevision)",
      "description": "祈的核心能力。通过大脑直接连接高维信息场，预测极短时间至中等跨度时间内的未来走向。其准确率几乎等同于“确定事实”，唯一的干扰因素是具有强力历史干涉权的“不连续体”。"
    },
    {
      "name": "静态念力爆发 (Static Psychokinesis)",
      "description": "无需物理媒介，通过意志直接干涉空间内的分子运动。能制造极高强度的念力护盾、或是瞬间产生数吨级的压力将目标彻底粉碎。其特点是发力毫无征兆。"
    },
