    },
    {
      "name": "焉弹 (Ender Bullet - 已拆除/转化)",
      "description": "日本政府埋藏在其心脏部位的禁忌术式，本质上是浓缩的绝对零度与存在湮灭能。设计初衷是让矢子通过自杀式接触彻底冻结复活的凤凰。目前该术式的魔力已被矢子本人完全掌控，转化为其施法能量源。"
    }
  ],
  "relationships": {
    "原田静刃": {
      "nature": "义弟、心上人、契约般存在的守护对象",
      "description": "最初是以监视者的身份接触静刃，但在相处过程中被静刃温柔且热血的性格所吸引。在“焉弹”事件后，两人建立了生死相依的羁绊。矢子对静刃抱有极深的长辈式慈爱，同时也潜藏着身为女性的爱慕，经常利用“姐姐”的身份进行各种大胆的身体接触，让静刃疲于应对。"
    },
    "立花·冰焰·爱莉丝贝尔": {
      "nature": "战友、竞争对手、房友",
      "description": "与爱莉丝贝尔在家庭地位上存在微妙的博弈。虽然两人在战斗中配合默契，但在争取静刃的好感方面互不相让。爱莉丝贝尔对矢子的超规格身材感到极大的威胁，而矢子则以包容一切的微笑应对。"
    },
    "瑠姬赫莉兹": {
      "nature": "旧敌、被拯救者、好友",
      "description": "在“指定赛”中，矢子以温柔的力量化解了琉姬的孤傲。战后两人关系迅速升温，琉姬甚至在某种程度上依赖于矢子那如母亲般宽广的胸怀。"
    },
    "貘": {
      "nature": "战略指挥、临时共犯",
      "description": "貘利用矢子来刺激静刃的成长。矢子虽然对貘的一些“流氓战术”感到害羞，但为了大局往往会配合执行那些充满福利色彩的训练方案。"
    }
  }
}

