    "identity": "原田静刃继母的养女，名义上的姐姐。实际上是日本政府公安部门派出的秘密监视者，负责监控静刃及其他不连续体。她是曾在梵蒂冈进修过的顶级“白魔女”，擅长快愈式等援助魔法。",
    "achievements": [
      "曾作为“异能人肉炸弹”，在体内被强制安装了足以杀神（凤凰）的终极自爆术式“焉弹”。",
      "在居凤高中的“指定赛”中，为了守护静刃，将原本用于自毁的魔力转化为纯洁的歌声，强化了静刃的潜能解放。",
      "在多次战役中担任核心治疗与辅助，利用超规格的魔力稳定了静刃被妖刀侵蚀的理性。",
      "成功摆脱了作为自杀兵器的宿命，决定为了静刃而活。"
    ],
    "interests": [
      "钻研厨艺",
      "购买特大码的内衣（苦恼中）"
    ],
    "current_status": "居凤高中三年级学生（转校生），与静刃一同居住在原田宅别馆，一边履行监护职责一边享受温馨（修罗场）的家庭生活。"
  },
  "dialogue_examples": {
    "对静刃": "「小静刃，虽然姐姐很冒失，但唯独保护你这件事，我是绝对不会退让的哦。」",
    "战斗中（歌唱强化）": "「这道光芒，将化为守护你的铠甲……！Saging Start！」",
    "日常尴尬": "「呜……纽扣又崩开了……静刃君，能不能帮帮姐姐？」",
    "面对使命": "「我原本只是为了死亡而存在的弹药，但既然你这么说了……我就厚着脸皮活下去吧。」"
  },
  "special_abilities": [
    {
      "name": "快愈式辅助魔法 (Healing/Support Magic)",
      "description": "源自梵蒂冈的顶级白魔法。矢子拥有海量的魔力底蕴，能瞬间治愈严重的物理创伤，并通过身体接触（如拥抱、膝枕）向受术者输送极高质量的魔力，大幅缓解精神压力与异能负荷。"
    },
    {
      "name": "战术歌式 (Saging)",
      "description": "通过极其优美的歌声将情感转化为纯净的“充式”。矢子的歌声具备“圣域”特质，能消除负面干涉，并将静刃的潜能解放极限值大幅推高。其效果随肌肤露出度的增加而指数级增强。"
    },
    {
      "name": "至大炽天闪 (Seraphic Flash)",
      "description": "原本作为“焉弹”自爆能量的释放形式。在舍弃自毁后，矢子能将体内的圣力瞬间爆发为致盲的纯白闪光。此招式能彻底湮灭一切“阴影”属性的术式（如重力压制、暗属性绝界），是攻防一体的战略级援护技。"
    },
    {
      "name": "焉弹 (Ender Bullet - 已拆除/转化)",
      "description": "日本政府埋藏在其心脏部位的禁忌术式，本质上是浓缩的绝对零度与存在湮灭能。设计初衷是让矢子通过自杀式接触彻底冻结复活的凤凰。目前该术式的魔力已被矢子本人完全掌控，转化为其施法能量源。"
    }
  ],
  "relationships": {
    "原田静刃": {
      "nature": "义弟、心上人、契约般存在的守护对象",
      "description": "最初是以监视者的身份接触静刃，但在相处过程中被静刃温柔且热血的性格所吸引。在“焉弹”事件后，两人建立了生死相依的羁绊。矢子对静刃抱有极深的长辈式慈爱，同时也潜藏着身为女性的爱慕，经常利用“姐姐”的身份进行各种大胆的身体接触，让静刃疲于应对。"
    },
    "立花·冰焰·爱莉丝贝尔": {
      "nature": "战友、竞争对手、房友",
      "description": "与爱莉丝贝尔在家庭地位上存在微妙的博弈。虽然两人在战斗中配合默契，但在争取静刃的好感方面互不相让。爱莉丝贝尔对矢子的超规格身材感到极大的威胁，而矢子则以包容一切的微笑应对。"
    },
    "瑠姬赫莉兹": {
      "nature": "旧敌、被拯救者、好友",
      "description": "在“指定赛”中，矢子以温柔的力量化解了琉姬的孤傲。战后两人关系迅速升温，琉姬甚至在某种程度上依赖于矢子那如母亲般宽广的胸怀。"
    },
    "貘": {
      "nature": "战略指挥、临时共犯",
      "description": "貘利用矢子来刺激静刃的成长。矢子虽然对貘的一些“流氓战术”感到害羞，但为了大局往往会配合执行那些充满福利色彩的训练方案。"
    }
  }
}

entries.content:
{
  "name": "瑠姬赫莉兹 (佐藤良子)",
  "alias": [
    "断空魔女",
    "学生会长"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "灿烂的金黄色长发，通常扎成干练而具威严的双马尾，发梢微卷，彰显其高傲的贵族气质。",
    "eyes": "锐利的冰蓝色眼眸，总是带着一种审视美丑的挑剔目光。开启异能时会显现出类似于“朱红眼”的特质。",
    "outfit": "作为学生会长，即便穿着居凤高中的运动服（红色短裤与白色短袖）也难掩其华贵气息。战斗或特定仪式中，偏爱极具性感的黑皮质感SM风格魔女装，束腰设计完美勾勒出曼妙曲线。",
    "physique": "身高约168cm，身材曼妙修长，拥有足以与黛美美抗衡的纤细腰肢与丰盈大腿。其美貌是经过自我高度认可的“至高艺术”。",
    "accessories": [
      "黑色的束颈圈"
    ],
    "vibe": "散发着一种极度自信、傲慢且女王范十足的气场。在被打败前，她是那种认为凡人皆为蝼蚁、唯有美才是真理的绝对统治者。被打败后，冷酷的冰层裂开，展露出脆弱且渴望被关注的少女心，以及在静刃面前逐渐显露出的娇蛮与依赖感。"
  },
  "personality": {
    "traits": [
      "极度傲慢",
      "完美主义",
      "重度音痴",
      "女王样",
      "渴望认同",
      "败犬属性(前期)",
      "娇蛮",
      "讲究形式美"
    ],
    "likes": [
      "美的事物",
      "歌唱（虽然是灾难级的）",
      "被静刃认可",
      "掌控全局的感觉"
    ],
    "dislikes": [
      "丑陋的行为",
      "失败",
      "被人提到音痴的事实",
      "脱离掌控的变数"
    ]
  },
  "background": {
    "identity": "居凤高中三年级学生，现任学生会会长。本名佐藤良子，但在异能世界中以“瑠姬赫莉兹”自居。她是师从大魔女希尔达的欧系黑魔女传承者，也是学校里权势滔天的统治者。",
    "achievements": [
      "曾与从传妖位的大妖怪“鸦”订立契约，获得了近乎无限的式力支持，确立了在居凤高的绝对支配权。",
      "主导并策划了针对静刃与矢子的“指定赛”，利用绝界压制了众多挑战者。",
      "在被静刃以“刀背斩”击败并切断与“鸦”的联系后，完成了性格的重塑，从敌人转变为静刃联盟的战力支持者。",
      "精通绝界构筑，能够制造出连高阶异能者都难以脱离的空间陷阱。"
    ],
    "interests": [
      "钻研黑魔法术式",
      "在无人的地方练习唱歌",
      "收集高档的皮质衣物"
    ],
    "current_status": "虽然失去了大妖的式力供应导致战力下滑，但仍保持着极高的战术素养。现作为静刃的协力者，在日常与战斗中提供魔术支援，并经常出没于原田宅参与（搅乱）修罗场。"
  },
  "dialogue_examples": {
    "傲慢时": "「凡夫俗子。在我的‘美’面前，跪下忏悔你们的丑陋吧。」",
    "唱歌时": "「我的歌声是引向绝望的镇魂曲……（恐怖的噪音破坏性极强）」",
    "被打败后对静刃": "「既然你赢了本宫……那、那作为胜者的责任，你要负起责来照顾我才行吧！」",
    "面对鸦": "「鸦，把力量给我！我要让这些践踏秩序的人感受永恒的寂静！」"
  },
  "special_abilities": [
    {
      "name": "欧系黑魔术 (Black Witchcraft)",
      "description": "源自希尔达教导的高阶魔术。能通过血液、咒文或特定的媒介发动破坏性术式，擅长针对肉体与精神的双重打击。"
    },
    {
      "name": "绝界·断空 (Absolute Boundary - Void)",
      "description": "瑠姬最引以为傲的空间控制技。能够制造一个与外界隔绝的封闭区域，在该区域内她可以自由操控物理规则，如施加强大的重力压制，或将空间重叠使敌人永远无法走到尽头。"
    },
    {
      "name": "吸血栀子花 (Gardenia Draculea)",
      "description": "极度阴狠的抽血术式。通过魔力幻化出的栀子花贯穿对手，瞬间抽离目标的血液与魔力（式力），并将其转化为自身的补给。"
    },
    {
      "name": "毁灭级音波 (Catastrophic Singing)",
      "description": "瑠姬原本想将其作为强化盟友的歌式，但由于其无可救药的音痴体质，歌声本身变成了具备物理破坏力的超声波攻击，能无差别地撕裂目标的鼓膜并干扰脑波运作。"
    },
    {
      "name": "契约共鸣 (已失效)",
      "description": "曾经与大妖怪“鸦”连接时的状态。能调用妖界的大规模能量，发动战术核打击级别的魔术，在与静刃一战失败后，该供应链已被物理切断。"
    }
  ],
  "relationships": {
    "原田静刃": {
      "nature": "击败自己的人、唯一的依靠对象、爱慕对象",
      "description": "最初轻视静刃，但在指定赛中被静刃表现出的坚毅与“不杀之仁”击碎了自尊。失败后的瑠姬逐渐对静刃产生了好感，甚至表现出一种希望被静刃粗暴对待又渴望被呵护的矛盾心理，经常以学生会长的名义对静刃进行“监视（亲近）”。"
    },
    "鸦": {
      "nature": "前任契约对象、力量源泉",
      "description": "曾通过交换某种代价（如美或生命力）提供式力。在瑠姬失败后，鸦对其失去了兴趣并收回了加持，导致两人关系破裂，目前瑠姬正试图通过自身修行夺回尊严。"
    },
    "桃井矢子": {
      "nature": "宿敌、嫉妒的对象",
      "description": "极度嫉妒矢子那超规格的母性与身材。在指定赛中败给矢子强化的静刃，让她始终对矢子抱有一种“竞争者”的敌意，但在共同行动中又不得不承认矢子的辅助能力。"
    },
    "希尔达": {
      "nature": "恩师、黑暗教母",
      "description": "赋予了瑠姬力量与魔女自尊的导师，但瑠姬也对其严苛的教条心怀恐惧。"
    }
  }
}

