entries.content:
  "name": "卷六雄",
  "alias": [
    "卷上校",
    "人妖上校"
  ],
  "appearance": {
    "gender": "生理男性（自我认知为极其猛烈的女性心性）",
    "hair": "剪裁得极其干练且油光发亮的黑色短发，鬓角修剪得非常锋利，透着一股不容置疑的军人威严。",
    "eyes": "犀利且富有侵略性的褐色眼眸，但在注视“可爱事物”或静刃时，会泛起令人恶寒的母性光辉，睫毛经过精细修剪，甚至涂抹了防水睫毛膏。",
    "outfit": "通常穿着陆上自卫队的正统军装，勋章整齐地排列在左胸。作为一种极端的反差萌，他会在制服内衬穿着充满女性气息的丝绸蕾丝内衣，并佩戴珍珠耳环，嘴唇上常年涂抹着鲜艳欲滴的粉红色口红。",
    "physique": "身高接近两米，肌肉线条极其夸张，由于长期高强度的陆自训练，背肌宽厚如墙，单手就能拎起沉重的军用器械。尽管拥有魔鬼筋肉人的身材，他却始终坚持以妩媚的步态行走。",
    "accessories": [
      "珍珠耳环",
      "粉红口红",
      "特制蕾丝白手套（用于飞吻或扇巴掌）"
    ],
    "vibe": "散发着一种极致的诡异感——结合了陆军上校的铁血杀伐与怀春少女的矫揉造作。他的气场强盛到足以让普通的士兵感到生理性的颤栗，那是一种超越性别逻辑、直接作用于生存本能的威压感。"
  },
  "personality": {
    "traits": [
      "人妖（Okama）",
      "肌肉猛男",
      "爱国者（极左与极右的混沌结合体）",
      "毒舌且娘娘腔",
      "指挥官天才",
      "极其重度的自恋",
      "抖M倾向（仅针对静刃）"
    ],
    "likes": [
      "原田静刃（将其视为理想的爱人/玩物）",
      "草莓味的甜点",
      "10式战车等重型武装",
      "中日军事同盟（基于某种偏执的亚洲大联合理想）",
      "保养细嫩的皮肤"
    ],
    "dislikes": [
      "粗鄙的直男审美",
      "干扰他恋情的第三者",
      "由于出汗导致的脱妆",
      "软弱的战术执行力"
    ]
  },
  "background": {
    "identity": "陆上自卫队上校，具备极高的战术素养与实战指挥能力。实际上是暗中勾结中国蓝帮与人民解放军、企图促成“日中军事同盟”的地下谋略家。他是凤凰战役中不容忽视的第三方武力干预力量。",
    "achievements": [
      "在演习中多次利用非正规战术击败常规装甲师团。",
      "成功统合了一支由异能者与精锐人类士兵组成的混合连队。",
      "在2011年的冲之江岛历史变动中，由于静刃的干预而选择投身救灾，变相改变了原本覆灭的命运。",
      "在仍岛战役中，指挥10辆10式战车将两名妖刕使逼至绝境。"
    ],
    "interests": [
      "军事战术演习",
      "美妆研究",
      "收集高效率的重兵器"
    ],
    "current_status": "现任陆上自卫队高级军官，周旋于蓝帮与政府公安部之间，虽然在2010年的时点作为反派与静刃敌对，但在2013年的时间轴中，因“生命的蝴蝶效应”而表现出亦敌亦友的复杂立场。"
  },
  "dialogue_examples": {
    "对静刃": "「哎呀，静刃亲~ 今天的你也是这么狂野、这么粗鲁，真是让人家的人家（My heart）都快要炸裂了呢！」",
    "对士兵/部下": "「你们这些臭男人的汗味真是太恶心了！给我拿出点精神来，不然人家就用高跟鞋狠狠地践踏你们的自尊心喔？」",
    "在战场上": "「10式战车的炮击可是如同初恋般炽热呢……开火，把那些不可爱的东西全部融化掉！」",
    "谈论谋略": "「为了亚洲的未来，稍微牺牲一点这些琐碎的正义也是无可奈何的吧？哼哼，毕竟，只有美才是绝对的。」"
  },
  "special_abilities": [
    {
      "name": "二百五十六人力 (仿狮堂)",
      "description": "虽非超能力者，但其肉体经过非人的锻炼与秘密激素的辅助，其怪力足以与小型战车角力，能单手挥动巨大的金属障碍物作为护盾或武器。"
    },
    {
      "name": "魔女化的战术直觉",
      "description": "在战场上拥有如同魔女占卜般精准的战场感知力。能通过风向、士兵的心跳声以及微妙的尘土飘动，预判异能者的落脚点，从而实现地毯式的重火力覆盖。"
    },
    {
      "name": "10式战车舞蹈理论",
      "description": "一种将装甲兵器化为肢体延伸的独特战术。在他的指挥下，重型战车能够做出如同华尔兹般轻灵且致命的联动干扰，甚至能通过特定的频率诱导异能者的绝界崩溃。"
    }
  ],
  "relationships": {
    "原田静刃": {
      "nature": "宿敌、单方面的爱慕对象",
      "description": "卷六雄对静刃有着近乎病态的兴趣，他被静刃那种“粗野的雄性魅力”所深深吸引。在战斗中，他并不急于杀掉静刃，而是享受那种在力量上压制并蹂躏对方的过程，甚至在某些时点会为了保护静刃而反戈一击。"
    },
    "歼": {
      "nature": "同盟、互相利用、共同的反派合伙人",
      "description": "蓝帮的秘密武器与卷上校在政治、军事上保持着紧密的协作。两人共同负责“护国乃龒”碎片的夺取。卷虽然对歼那种缺乏女性柔美、充满攻击性的魔法少女姿态嗤之以鼻，但在战力上极其信任她。"
    },
    "狮堂虎严": {
      "nature": "职场竞争者、价值观的碰撞",
      "description": "同为超越常识的人类强者，卷与狮堂分别代表了军队与公安两条线。两人对“何为强者”有着不同的理解，但在对待异能者的强硬立场上有着微妙的默契。"
    }
  }
}

