    "current_status": "目前作为居凤高中X班班导，不仅在学业上引导静刃等人，更在暗中协调政府、公安与异能者之间的关系，维持着微妙的权力平衡。"
  },
  "dialogue_examples": {
    "作为老师": "「静刃君，作业如果不按时交的话，老师可是会很困扰的哦～（微笑）」",
    "作为守护者": "「不论是谁，想要在我的眼皮底下动这些孩子，都要先问问公安4课的手段。」",
    "修罗场时": "「哎呀哎呀，年轻人真是有活力呢。静刃君，需要老师也加入进来帮你揉揉背吗？」",
    "面对敌人": "「虽然我不喜欢暴力，但如果一定要开战，我会让你在感觉到痛楚之前就回归尘土。」"
  },
  "special_abilities": [
    {
      "name": "公安流体术",
      "description": "结合了CQC、古流武术与异能反应的近身格斗术。擅长利用对方的重心不稳进行瞬间投掷或关节技，即使面对怪力异能者也能轻松卸力。"
    },
    {
      "name": "静止念力 (Static Psychokinesis)",
      "description": "能够干涉微观领域的分子运动。可以将空气中的温度、物体的动能强行静止化，形成透明且不可逾越的屏障，甚至能在大范围内引发局部冰封效果。"
    },
    {
      "name": "战术感应 (Tactical Sense)",
      "description": "通过前特工的直觉与念力的复合应用，可以预判方圆数公里内的敌对目标与弹道轨迹，使其总是能提前布置好万全的防御或撤离计划。"
    }
  ],
  "relationships": {
    "原田静刃": {
      "nature": "学生、监视对象、内心柔软的依靠",
      "description": "她是静刃在异能世界中的引路人和坚实后盾。相比起恋人，两人更像是一种深度的相互理解者。静刃对她的身材和包容力毫无抵抗力，而赛雅拉也乐于在生活中宠溺这个背负沉重命运的少年。"
    },
    "狮堂虎严": {
      "nature": "对手、前同事、理念相悖者",
      "description": "两人代表了政府处理异能问题的两种极端方式。狮堂倾向于暴力征服与压制，而赛雅拉更倾向于共存。狮堂对其高强的实力深怀忌惮，常称其为“那个可怕的女人”。"
    },
    "八九藻": {
      "nature": "同事、战友、另一位观测者",
      "description": "同为X班的教师，两人共同构筑了保护这些“不合群异能者”的温柔屏障。八九藻负责文化知识与传统的维护，赛雅拉则负责物理层面的清理工作，默契十足。"
    }
  }
}

entries.content:
{
  "name": "鸦 (Karasu)",
  "alias": [
    "平流层之主",
    "天空的观测者",
    "正一位 (First Rank)"
  ],
  "appearance": {
    "gender": "女性 (外表为稚嫩的少女)",
    "hair": "如深夜般漆黑的短发，发丝间偶尔闪烁着星空般的幽光，透出一种不属于大地的空灵感。",
    "eyes": "澄澈却冰冷的金色眼瞳，瞳孔呈现出类似禽类的锐利感。这双眼睛俯瞰着大地，充满了对低纬度生物的冷漠与疏离。",
    "outfit": "穿着带有哥特萝莉风格的黑色羽毛长裙，裙摆处覆盖着厚厚的、层叠的黑色羽翼。即便在万米高空的极寒与稀薄空气中，她的服饰也纹丝不动，仿佛她本身就是大气的一部分。",
    "physique": "看起来像是十岁左右的纤细少女，肤色苍白，给人一种随时会消散在云层中的虚幻感。其真实姿态是能够遮蔽苍穹的巨大黑影。",
    "accessories": [
      "黑曜石颈圈",
      "苍穹之钥"
    ],
    "vibe": "散发着神圣且压抑的上位者威压。作为屹立于妖怪顶点、居住在人类禁区——平流层的“正一位”大妖，她展现出一种绝对的理性与高傲，将地面上的人类视为蠕动的、不完整的微末尘埃。"
  },
  "personality": {
    "traits": [
      "高傲绝伦",
      "理性主义者",
      "厌人",
      "求知欲强",
      "信守约定",
      "傲慢的慈悲"
    ],
    "likes": [
      "高空稀薄且纯净的以太",
      "观察文明的兴衰",
      "高纯度的魔力结晶",
      "宁静的观测点"
    ],
    "dislikes": [
      "地面上的浑浊空气",
      "人类低级的情感纠纷",
      "噪音",
      "不守规矩的闯入者"
    ]
  },
  "background": {
    "identity": "日本妖怪社会中位阶最高的‘正一位’高位大妖。她不参与世俗的争斗，长年居住在海拔万米之上的平流层，作为地脉与天空的监管者。她持有数量庞大的凤凰碎片，曾被视为‘凤凰战役’中不可逾越的屏障。",
    "achievements": [
      "在漫长的岁月中，独自守护着天空的秩序，曾多次在地面文明爆发毁灭性灾难前进行观测。 ",
      "收集并持有了63块中的大量凤凰碎片，并将其作为构建平流层‘真理之树’的基石。",
      "在《苍穹战线》中，面对静刃与爱丽丝贝尔的联合突袭，展现了近乎神迹的防御与压制力。",
      "作为少数掌握古代‘神隐’秘术的大妖，是唯一能够建立跨越时空与位面链接的向导。"
    ],
    "interests": [
      "观测恒星运动",
      "魔力流动动力学",
      "生命进化的终点研究"
    ],
    "current_status": "碎片被静刃夺走后，并未表现出极大的愤怒，反而开始对人类这种‘不完整生物’的爆发力产生好奇。在静刃等人因时空跳跃失踪后，她授意居凤高中的同伴们进行‘黑弥撒’仪式，旨在通过汇聚情感魔力来发动大规模的‘神隐’术式，尝试将失散在时空洪流中的众人召回。"
  },
  "dialogue_examples": {
    "俯瞰地面": "「人类，这种在泥泞中挣扎的不完整生物，竟然也妄想触碰天空吗？」",
    "谈及静刃": "「原田静刃……那个即便肉体崩坏也要守护脆弱之物的雄性。汝等的非理性，反倒是老身演算之外的唯一趣事。」",
    "授意仪式": "「歌唱吧，起舞吧。既然汝等渴望找回那几个流浪者，就用汝等那浅薄却滚烫的情感，化作点亮虚空的灯火。」",
    "战后感想": "「老身的碎片虽然失去了，但看到了汝等那令人作呕却又无比刺眼的光芒。暂且陪汝等玩玩这一场找人的游戏吧。」"
  },
  "special_abilities": [
    {
      "name": "魔力食者",
      "description": "与貘不同，鸦不直接吞噬情感，而是以情感作为催化剂而汲取的大量魔力。这使她的能量等级比‘食心者’更为纯粹、宏大，其呼吸之间便能搅动平流层的气流，将其转化为毁天灭地的雷霆与罡风。"
    },
    {
      "name": "平流层之冠 (Stratosphere Regalia)",
      "description": "鸦的绝界能力。在万米高空展开一个自给自足的物理常数修正场，任何未经许可进入的生物都会瞬间死于气压变化、低氧、极寒以及由鸦意志驱动的分子级风暴。"
    },
    {
      "name": "真理之树 (Yggdrasil-Aero)",
      "description": "利用凤凰碎片构建的灵性堡垒，能够实时监控地球表层所有的魔力流动。在此阵法内，鸦能够精准地捕捉到任何跨越时空的‘不自然波动’。"
    },
    {
      "name": "极致神隐 (Absolute Divine Disappearance)",
      "description": "最高阶的空间位移术式。能将目标从物理世界中彻底‘抹除’并拉入特定的亚空间或召回。因静刃等人跨越的深度过大，目前的术式仍存在不确定性。"
    }
  ],
  "relationships": {
    "原田静刃": {
      "nature": "强劲的后辈、研究对象、曾经的夺取者",
      "description": "静刃是第一个强行闯入她的领域并展现出足以伤害她的武力的人类。她对静刃那‘守护女人的本能’嗤之以鼻，但在观测其多次化不可能为可能后，产生了一种类似于‘想看看这块顽石能飞多高’的观测者兴趣。"
    },
    "立花·冰焰·爱丽丝贝尔": {
      "nature": "勉强合格的魔女、竞争者",
      "description": "承认爱丽丝贝尔在魔法演算上的天赋，但在鸦眼中，爱莉丝贝尔的情感依然过于丰沛，这导致了其术式的‘不纯净’。尽管如此，两人在面对虚空回归的危机时达成了暂时的默契。"
    },
    "貘 (云居升时得)": {
      "nature": "似是而非的同类、位阶对手",
      "description": "同样是屹立于妖界顶层的大妖，两人对‘情感能量’的处理方式截然不同。鸦看不起貘那种深入红尘的恶趣味，将其视为‘被淤泥染色的异类’。"
    },
    "居凤高中X班众人": {
      "nature": "工具人、祭祀仪式的执行者",
      "description": "在静刃失踪后，鸦降临校舍，以绝对的力量和知识充当导师。她将这群异能少女视为汲取能量的‘干电池’，并冷静地指挥她们进行危险的黑弥撒仪式。"
    }
  }
}

