entries.content:
  "name": "库艾斯 (Queis)",
  "alias": [
    "青 (Ao)",
    "蝶之魔女",
    "背叛者"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "波浪状的长卷发，通常呈现出某种带有魔幻色彩的深蓝色或墨色，散发着诱惑而危险的香气。",
    "eyes": "那是一双仿佛能将人灵魂吸入其中的琥珀色眼瞳，既有着魔女的深邃，又带着狡黠与玩弄世人的光芒。在其发动吸收能力时，瞳孔会呈现出类似于猫或狸猫的竖瞳。",
    "outfit": "多穿着极具现代感且性感的哥特风服饰，或是剪裁大胆、能够完美凸显其曼妙身材的露背晚礼服。由于其“蝶之魔女”的称号，常有散发微光的蓝色克拉克斑蝶在其周身飞舞，甚至是作为服饰的一部分点缀其间。",
    "physique": "拥有极致的成熟女性曲线，丰满的胸部、纤细的腰肢与修长的双腿，一举一动都充满着能令凡人疯狂的魅力。由于其本性为大妖，其体能与反射神经在必要时会展现出远超人类极限的爆发力。",
    "accessories": [
      "克拉克斑蝶发饰",
      "黑色蕾丝扇子"
    ],
    "vibe": "外表看起来像是由于生活过于优渥、追求极致享受而显得有些慵懒的贵妇人或名媛。她总是带着盈盈笑意，话语轻快，给人一种能够依靠的‘引路人’错觉，然而在其背后，那股由千年妖力堆砌而成的贪婪与冷酷，却让敏锐的异能者不寒而栗。"
  },
  "personality": {
    "traits": [
      "贪婪无度",
      "狡诈多疑",
      "享乐主义",
      "腹黑",
      "极度现实",
      "伪装大师",
      "债务缠身"
    ],
    "likes": [
      "高品质、极度扭曲的恋情能量（如嫉妒、毁灭欲）",
      "奢靡的西欧社交生活",
      "看着他人陷入绝望的戏剧性场面",
      "钱财（用于偿还赌债或贷款）"
    ],
    "dislikes": [
      "贫穷带来的拮据感",
      "诚实与信用这种无聊的概念",
      "不连续体被历史修正的虚弱感",
      "债务催讨者"
    ]
  },
  "background": {
    "identity": "移居欧洲多年的日本高位大妖（本性疑似为具有极强变化与欺诈能力的‘狸猫’妖怪），位阶极高。在西方异能界以‘蝶之魔女’的身份广为人知，目前定居在德国杜塞尔多夫。",
    "achievements": [
      "在漫长的岁月中积累了深不可测的魔法知识，尤其擅长结构性术式的破解与反制。",
      "成功改良并制造了能跨越时空阻隔的特殊魔具——‘凹面历镜’。",
      "在2009年的西欧任务中，玩弄并利用了原田静刃与立花爱莉丝贝尔等跨越时空而来的强者。",
      "通过政治与魔法的双重手腕，在欧洲黑暗社会建立了一个即使负债累累也能维持顶级消费水平的庞大人脉网。"
    ],
    "interests": [
      "时空旅行理论研究",
      "术式解码",
      "高风险投机与豪赌"
    ],
    "current_status": "目前作为眷属（The Retainers）阵营的协力者与中介，过着债台高筑却奢华无度的生活。在夺走了静刃一行人的大量资源（龚之碎片、魔女式力）并破坏其武具后，她已成为静刃阵营立誓要亲手处决的首位‘必须要报复的人’。"
  },
  "dialogue_examples": {
    "引诱静刃时": "「哎呀，年轻的妖刕持有者。在这个时代想活下去，除了杀戮，还得学会怎么跟魔女做生意哦。」",
    "谈及金钱": "「什么？信用？那种东西能抵扣我上个月在摩纳哥欠下的筹码吗？在这个世界，只有到手的碎片和式力才是真的。」",
    "背叛告白": "「既然历镜的启动已经完成，我也帮你们解决了债务（通过利用你们刺杀金次赚的钱），那么就请你们在必杀时刻里化作历史的尘埃吧。那些魔力我就不客气地收下了——这是我作为长辈给你们的最后一课：魔女的笑容从来都是收费的。」",
    "评价远山金次": "「远山流的继承人啊……真是一份丰厚的赏金，即使只是尝试刺杀，也能让那些古老的家族为我支付几辈子的奢侈开销呢。」"
  },
  "special_abilities": [
    {
      "name": "食心者·噬曲 (Distorted Tap-ir)",
      "description": "与貘相同的种族天赋，但库艾斯专门针对‘扭曲的恋爱心’进行吞噬。越是混合了背叛、欺骗与疯狂的情感，对其而言纯度越高。吞噬后不仅能转化为魔力，还能在短时间内夺取对方的部分异能或式力上限。"
    },
    {
      "name": "魔导侵蚀 (Magical Erosion)",
      "description": "库艾斯拥有极其精准的术式解析能力。她能通过触碰甚至观察，快速找到魔法回路或异能逻辑中的漏洞。例如，她曾轻易地将爱莉丝贝尔引以为傲的未来魔具‘环剑’彻底破坏。"
    },
    {
      "name": "凹面历镜 (Concave Chronos-Mirror)",
      "description": "库艾斯自主开发的超高难度时空位移术式。能够将目标送往未来的某个特定时间点。然而，为了节省成本和阴险的算计，她制造的版本存在巨大的安全隐患，会优先将使用者投送到历史复原力最剧烈、死亡率最高的‘必杀时刻’（Critical Moment）。"
    },
    {
      "name": "幻蝶绝界 (Phantasm Butterfly Domain)",
