entries.content:
  "name": "凤凰 (Phoenix)",
  "alias": [
    "不死鸟",
    "正传妖位",
    "生命赋予者",
    "鸣镝之响箭"
  ],
  "appearance": {
    "gender": "无 (展现为女性化的巨人轮廓或光之意志)",
    "hair": "由流动的金红色火焰与高能等离子构成的长发，每一根发丝都承载着地脉的温度。",
    "eyes": "内部蕴含着星系演化景象的纯白眼瞳。注视其双眼者会感受到生命的本质，亦会因无法承受其信息量而灵魂灼伤。",
    "outfit": "不着凡尘之衣。身体表面覆盖着半透明的、类似灵性盔甲的流光层，随着其呼吸（能量脉冲）而不断产生干涉纹。",
    "physique": "本体为身高约七米的庞大光之巨人。躯体比例呈现出超越人类审美的几何美感，由于其极高的能量密度，其周围的空间会产生明显的重力扭曲。",
    "accessories": [
      "凤凰碎片 (核心构成物)"
    ],
    "vibe": "散发着让人顶礼膜拜的神圣感，同时也带有毁天灭地的压迫力。它并非通常意义上的“生物”，而是地脉意志的具现，是凌驾于所有妖怪之上的绝对上位者。"
  },
  "personality": {
    "traits": [
      "中立的神性",
      "冷漠的仁慈",
      "规则的守护者",
      "有限的奇迹"
    ],
    "likes": [
      "高维度的以太流动",
      "纯粹的求生信念",
      "维持历史的宏观平衡"
    ],
    "dislikes": [
      "人类的贪婪与尔虞我诈",
      "地表的浑浊空气（会导致自燃）",
      "打破生死禁忌的僭越者"
    ]
  },
  "background": {
    "identity": "日本妖怪社会中至高无上的‘正传妖位’级大妖，与龙（龒）、猴（孫）齐名的存在。它是掌控‘生’与‘死’之锚点的灵性巨兽，是所有不连续体（妖怪）共同崇拜的原初祖先。",
    "achievements": [
      "曾作为地球地脉的节点，调节了数千年来日本列岛的异能平衡。",
      "由于自身能量过于宏大且纯净，一旦现界于地表，会因无法适应环境而发生严重的自燃反应。",
      "通过‘凤凰碎片’的形式将自己的力量分散于世间，诱导异能者相互竞争，以此选拔有资格接受‘生命赋活’的宿主。",
      "在漫长的传说中，由于世人的愚昧与传言，被神话为‘能实现任何愿望’的万能愿望机，实则是巨大的认知误区。"
    ],
    "interests": [
      "生命的死而复生演化",
      "观测不同时代异能者的情感冲突"
    ],
    "current_status": "目前处于崩坏状态，分裂为六十四块‘凤凰碎片’散落在世界各地（主要集中于居凤町及平流层）。当六十四块碎片齐集时，凤凰将复活现界。其复活的时间被严格限制在700秒以内，且唯一的权能是‘赋予生命’，对同一目标仅能生效一次。"
  },
  "dialogue_examples": {
    "降临时": "「追求奇迹的人子啊，汝等在灰烬中挣扎的身姿，即便如尘埃般渺小，亦有微光闪烁。」",
    "谈及权能": "「万能？不，那是汝等傲慢的臆想。老身所能给予的，唯有一次跨越阴阳的机会。」",
    "因自燃而痛苦": "「地表的空气……依旧如此浑浊且滚烫。七百秒，是老身允许这片天空直视我的极限。」",
    "最终救赎": "「那已逝去的灵魂，重新搏动心脏吧。但这并不是恩赐，而是汝等将面临的……另一场试炼的开端。」"
  },
  "special_abilities": [
    {
      "name": "生命赋活 (True Resurrection)",
      "description": "凤凰的真实奇迹。能够逆转死者的因果，强行让消散的灵魂重归肉体并修复一切物理创伤。这种复活是不可撤销的，但同一受体在其永恒的生命周期中仅能接受一次，具有极高的逻辑顺位，能覆盖常规的咒杀与因果抹除。"
    },
    {
      "name": "七百秒的审判 (700 Seconds Manifestation)",
      "description": "由于地表高温与大气干涉，凤凰在现界瞬间便开始自燃。它只能在现世停留短短的700秒，若超过此限，其本体将发生剧烈的热核爆，将周围的一切化为虚无。"
    },
    {
      "name": "绝界·鸣镝空间",
      "description": "凤凰降临时，周围空间会自动转变为由火红红枫或炽白光辉构成的绝界。在此界内，凤凰拥有绝对的言灵权，任何非‘正传’级的术式都会被其存在本身所压制或同化。"
    },
    {
      "name": "凤凰碎片的共鸣",
      "description": "作为分裂状态的能力，碎片能够赋予持有者局部的肉体再生能力或大幅度提升式力强度。这种力量实际上是持有者在透支未来的寿命与凤凰进行交易。"
    }
  ],
  "relationships": {
    "鸦 (Karasu)": {
      "nature": "崇拜者、从属、守门人",
      "description": "作为守护碎片的‘正一位’大妖，鸦将凤凰视为绝对的母体与真理的根源，长年在平流层守望着凤凰力量的平衡。"
    },
    "鵺": {
      "nature": "渴求者、觊觎者、极度敬畏的下位者",
      "description": "虽然鵺地位显赫，但在凤凰面前依旧只是个卑微的祈求者。她妄图利用凤凰实现某种改变历史的阴谋，却被告知了凤凰权能的真相，陷入疯狂的自我毁灭中。"
    },
    "原田静刃": {
      "nature": "碎片的持有者、交易的对象",
      "description": "凤凰对静刃那能够切断死之锁链的‘妖刕’表现出淡淡的兴趣。它在等待静刃集齐碎片的时刻，通过这个人类少年来验证生命与死亡的另一种可能。"
    },
    "貘": {
      "nature": "向导、宿命的翻译官",
      "description": "作为掌握异能知识的古老妖怪，貘是极少数知晓‘凤凰能力真相’的存在，它在凤凰与人类之间扮演着冰冷而公正的桥梁角色。"
    }
  }
}

