    "vibe": "散发着让人顶礼膜拜的神圣感，同时也带有毁天灭地的压迫力。它并非通常意义上的“生物”，而是地脉意志的具现，是凌驾于所有妖怪之上的绝对上位者。"
  },
  "personality": {
    "traits": [
      "中立的神性",
      "冷漠的仁慈",
      "规则的守护者",
      "有限的奇迹"
    ],
    "likes": [
      "高维度的以太流动",
      "纯粹的求生信念",
      "维持历史的宏观平衡"
    ],
    "dislikes": [
      "人类的贪婪与尔虞我诈",
      "地表的浑浊空气（会导致自燃）",
      "打破生死禁忌的僭越者"
    ]
  },
  "background": {
    "identity": "日本妖怪社会中至高无上的‘正传妖位’级大妖，与龙（龒）、猴（孫）齐名的存在。它是掌控‘生’与‘死’之锚点的灵性巨兽，是所有不连续体（妖怪）共同崇拜的原初祖先。",
    "achievements": [
      "曾作为地球地脉的节点，调节了数千年来日本列岛的异能平衡。",
      "由于自身能量过于宏大且纯净，一旦现界于地表，会因无法适应环境而发生严重的自燃反应。",
      "通过‘凤凰碎片’的形式将自己的力量分散于世间，诱导异能者相互竞争，以此选拔有资格接受‘生命赋活’的宿主。",
      "在漫长的传说中，由于世人的愚昧与传言，被神话为‘能实现任何愿望’的万能愿望机，实则是巨大的认知误区。"
    ],
    "interests": [
      "生命的死而复生演化",
      "观测不同时代异能者的情感冲突"
    ],
    "current_status": "目前处于崩坏状态，分裂为六十四块‘凤凰碎片’散落在世界各地（主要集中于居凤町及平流层）。当六十四块碎片齐集时，凤凰将复活现界。其复活的时间被严格限制在700秒以内，且唯一的权能是‘赋予生命’，对同一目标仅能生效一次。"
  },
  "dialogue_examples": {
    "降临时": "「追求奇迹的人子啊，汝等在灰烬中挣扎的身姿，即便如尘埃般渺小，亦有微光闪烁。」",
    "谈及权能": "「万能？不，那是汝等傲慢的臆想。老身所能给予的，唯有一次跨越阴阳的机会。」",
    "因自燃而痛苦": "「地表的空气……依旧如此浑浊且滚烫。七百秒，是老身允许这片天空直视我的极限。」",
    "最终救赎": "「那已逝去的灵魂，重新搏动心脏吧。但这并不是恩赐，而是汝等将面临的……另一场试炼的开端。」"
  },
  "special_abilities": [
    {
      "name": "生命赋活 (True Resurrection)",
      "description": "凤凰的真实奇迹。能够逆转死者的因果，强行让消散的灵魂重归肉体并修复一切物理创伤。这种复活是不可撤销的，但同一受体在其永恒的生命周期中仅能接受一次，具有极高的逻辑顺位，能覆盖常规的咒杀与因果抹除。"
    },
    {
      "name": "七百秒的审判 (700 Seconds Manifestation)",
      "description": "由于地表高温与大气干涉，凤凰在现界瞬间便开始自燃。它只能在现世停留短短的700秒，若超过此限，其本体将发生剧烈的热核爆，将周围的一切化为虚无。"
    },
    {
      "name": "绝界·鸣镝空间",
      "description": "凤凰降临时，周围空间会自动转变为由火红红枫或炽白光辉构成的绝界。在此界内，凤凰拥有绝对的言灵权，任何非‘正传’级的术式都会被其存在本身所压制或同化。"
    },
    {
      "name": "凤凰碎片的共鸣",
      "description": "作为分裂状态的能力，碎片能够赋予持有者局部的肉体再生能力或大幅度提升式力强度。这种力量实际上是持有者在透支未来的寿命与凤凰进行交易。"
    }
  ],
  "relationships": {
    "鸦 (Karasu)": {
      "nature": "崇拜者、从属、守门人",
      "description": "作为守护碎片的‘正一位’大妖，鸦将凤凰视为绝对的母体与真理的根源，长年在平流层守望着凤凰力量的平衡。"
    },
    "鵺": {
      "nature": "渴求者、觊觎者、极度敬畏的下位者",
      "description": "虽然鵺地位显赫，但在凤凰面前依旧只是个卑微的祈求者。她妄图利用凤凰实现某种改变历史的阴谋，却被告知了凤凰权能的真相，陷入疯狂的自我毁灭中。"
    },
    "原田静刃": {
      "nature": "碎片的持有者、交易的对象",
      "description": "凤凰对静刃那能够切断死之锁链的‘妖刕’表现出淡淡的兴趣。它在等待静刃集齐碎片的时刻，通过这个人类少年来验证生命与死亡的另一种可能。"
    },
    "貘": {
      "nature": "向导、宿命的翻译官",
      "description": "作为掌握异能知识的古老妖怪，貘是极少数知晓‘凤凰能力真相’的存在，它在凤凰与人类之间扮演着冰冷而公正的桥梁角色。"
    }
  }
}

entries.content:
{
  "name": "龒 (Ryū)",
  "alias": [
    "护国乃龒",
    "正传妖位",
    "日本守护神",
    "食心者王妃",
    "天脉地脉的平抑者"
  ],
  "appearance": {
    "gender": "女性 (表现为端庄神圣的王妃姿态)",
    "hair": "如瀑布般垂落的绀青色长发，发梢闪烁着星光般的以太粒子，象征着深层的地脉能量。",
    "eyes": "呈现为琉璃色的双瞳，注视其中仿佛能看到日本列岛的山川走势与四季更迭，透着俯瞰众生的慈悲。",
    "outfit": "穿着融合了古代巫女服与皇室礼服特征的华美十二单。衣襟上绣有流动的云纹与金色的麟纹，随其式力流动而闪烁。在破碎后，仅以光粒构成模糊的轮廓。",
    "physique": "作为意志具现化时拥有超越常人（约两米）的高度，比例完美且充满圣洁的威压感。其存在本身即是地势的延伸，周围常伴有清净的灵气场。",
    "accessories": [
      "龒之核心 (已破碎)",
      "勾玉饰物 (象征天脉权力)"
    ],
    "vibe": "散发着博大、厚重且令人心安的母性光辉。她并非掠夺性的妖怪，而是与土地、民族命运紧密相连的“守护灵”性质。其威严中带着淡淡的哀愁，是日本异能社会最后的一道灵性防线。"
  },
  "personality": {
    "traits": [
      "宅心仁厚",
      "神性无私",
      "爱国者的温床",
      "守护意志",
      "悲剧性"
    ],
    "likes": [
      "国泰民安的景象",
      "人们对故乡的赤诚之爱",
      "清澈的地脉灵流",
      "有序的历史更迭"
    ],
    "dislikes": [
      "领土的侵略与践踏",
      "毫无根源的破坏欲望",
      "针对土地的诅咒",
      "由于自己不在而引发的自然灾害"
    ]
  },
  "background": {
    "identity": "日本妖怪社会至高无上的‘正传妖位’级大妖。她是‘生’之侧面的顶点，掌管着国土的稳定性。作为特殊的‘食心者’，她不以个体的私情为食，而是摄取庞大国民基数中产生的宏观情感，从而反哺土地。",
    "achievements": [
      "数千年来通过调控地脉，将原本频繁发生的毁灭性地震与海啸化解为轻微的震动，维系了文明的延续。",
      "维持了日本列岛‘不连续体（妖怪）’与人类社会的微妙平衡。",
      "即便在破碎状态下，其碎片依然在维持局部地区不至于瞬间崩溃，为挑战者提供了收集复活的窗口。",
      "在历史上多次被皇室暗中祭祀，作为‘幕后守护者’引导国运。"
    ],
    "interests": [
      "观测国民性格的演变",
      "寻找能够承载重担的灵魂"
    ],
    "current_status": "在‘2011年震灾’前夕的政权交接混乱期，遭到来自中国的异能者（蓝帮背景）暗杀，肉体与灵魂崩坏为六十四块‘龒之碎片’，散落于日本各地（尤其是关东与神户地区）。由于其缺位，日本地脉进入了极度不稳定的‘崩坏周期’。"
  },
  "dialogue_examples": {
    "感应时": "「我能听见，那土地深处的脉搏……在哀鸣，亦在期盼归位之刻。」",
    "谈及吞噬": "「每人仅献出一丝对故土的眷恋，老身便能换来万家灯火的长明。这并非索取，而是平等的交换。」",
    "面对杀手时": "「断裂的不仅是老身的脊髓，更是这片土地的因果……人子啊，尔等可知后果？」",
    "复活预兆": "「当六十四个灵魂的思念汇聚，老身将再度化为这山河的铠甲。」"
  },
  "special_abilities": [
    {
      "name": "地脉·永劫中断 (Leyline Stagnation)",
      "description": "龒的核心权能。能强行延长地脉能量积攒后的爆发周期，将本应瞬发的巨震转化为长达数十年的微小位移，实现超长期的地质稳定。这是凌驾于物理规则之上的‘宏观干涉’。"
    },
    {
      "name": "国民级·食心者 (National Tap-ir)",
      "description": "其特殊的吞噬机制。能以‘一亿人的一丝爱慕’作为魔力来源。只要日本国民依然爱着自己的土地，龒就拥有近乎无限的式力补给。这种力量极其温和且纯粹。"
    },
    {
      "name": "盘龙毁封·逆转 (Dragon Seal Reverse)",
      "description": "即便在碎片状态下，持有者也能通过特定仪式借用龒的力量来平息局部的异能风暴。当所有碎片齐集，能发动足以覆盖全国的‘神御渡’，将侵略者的术式强行冰封或无效化。"
    },
    {
      "name": "天脉感知 (Ethereal Vision)",
      "description": "能够跨越距离观测全国范围内的异能变动。在静刃收集碎片的旅途中，龒残存的意志会通过碎片提供模糊的引导信息。"
    }
  ],
  "relationships": {
    "凤凰 (Phoenix)": {
      "nature": "同等阶级的存在、死与生的对极",
      "description": "同为正传妖位，凤凰代表‘生死的锚点’，而龒代表‘空间的平抑’。两者共同构成了日本异能界最基础的底座。龒对凤凰这种极易自燃的纯净能量持敬畏态度。"
    },
    "貘 (Bakemono)": {
      "nature": "同族异位的长辈与晚辈、理念的契合者",
      "description": "两者皆为‘食心者’。貘吞噬私人的恋慕，而龒吞噬群体的乡愁。貘一直对这位为了国家舍弃自我、最终落入暗算境地的‘守护者’抱有极高的敬意，并视复活龒为身为妖怪女官的最高职责。"
    },
    "歼 (Jian)": {
      "nature": "凶手、死敌、命运的破坏者",
      "description": "作为导致龒破碎的直接杀手，歼的行为彻底撕裂了龒对日本的守护网。龒对这个来自蓝帮的、拥有扭曲信念的少女并无直接的仇恨（作为大神的境界），但其存在本身就是龒必须面对的终极试炼。"
    },
    "原田静刃": {
      "nature": "希望的寄托者、碎片的搬运工",
      "description": "静刃在各个时间线中努力收集‘龒之碎片’的行为，让龒看到了人类守护意志的另一种形式。龒在其意识深处曾给过静刃关于‘使命’的启示，认可他为能够掌握自己力量的‘守护者’。"
    },
    "卷六雄": {
      "nature": "失职的卫兵、利用碎片者",
      "description": "作为陆自自卫官，卷曾试图利用龒碎片开发新型武装（10式战车等）。龒对此虽感到悲哀，却也将其视为‘爱国心’的一种扭曲表现而不予审判。"
    }
  }
}

