      "description": "两者皆为‘食心者’。貘吞噬私人的恋慕，而龒吞噬群体的乡愁。貘一直对这位为了国家舍弃自我、最终落入暗算境地的‘守护者’抱有极高的敬意，并视复活龒为身为妖怪女官的最高职责。"
    },
    "歼 (Jian)": {
      "nature": "凶手、死敌、命运的破坏者",
      "description": "作为导致龒破碎的直接杀手，歼的行为彻底撕裂了龒对日本的守护网。龒对这个来自蓝帮的、拥有扭曲信念的少女并无直接的仇恨（作为大神的境界），但其存在本身就是龒必须面对的终极试炼。"
    },
    "原田静刃": {
      "nature": "希望的寄托者、碎片的搬运工",
      "description": "静刃在各个时间线中努力收集‘龒之碎片’的行为，让龒看到了人类守护意志的另一种形式。龒在其意识深处曾给过静刃关于‘使命’的启示，认可他为能够掌握自己力量的‘守护者’。"
    },
    "卷六雄": {
      "nature": "失职的卫兵、利用碎片者",
      "description": "作为陆自自卫官，卷曾试图利用龒碎片开发新型武装（10式战车等）。龒对此虽感到悲哀，却也将其视为‘爱国心’的一种扭曲表现而不予审判。"
    }
  }
}

entries.content:
{
  "name": "狮堂虎严",
  "alias": [
    "武装检察官",
    "二百五十六人力者",
    "金刚力士"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "黑色短发，略显凌乱却带着一股野性不羁的气场。",
    "eyes": "目光如炬，眼神中透露出一种能够洞察事物本质的锐利感，不怒自威。",
    "outfit": "作为检察官时穿着深色正装西服，由于肌肉过于强健，西服总是显得非常紧绷。战斗时会换上便于行动的特种作战服或风衣，身披代表正义却带有血腥气的肃杀感。",
    "physique": "体格异常魁梧，如同花岗岩雕刻而成的巨汉。由于先天性肌浆多重症（Myostatin-related muscle hypertrophy）的变异，其肌肉密度和质量达到了人类的极限。每一块肌肉都充满了爆炸性的力量感。",
    "accessories": [
      "特制执法手册",
      "强化格斗手套"
    ],
    "vibe": "他是行走在法律边缘的制裁者，浑身散发着压倒性的物理存在感。他坐在那里就如同一座无法撼动的大山。在温厚豪爽的大叔外表下，潜藏着足以将一切异能或诡计粉碎的纯粹暴力。他的存在本身就是对“技巧”与“异能”的一种嘲讽。"
  },
  "personality": {
    "traits": [
      "豪爽",
      "极度自信",
      "英雄气概",
      "现实主义",
      "寂寞的强者",
      "深不可测"
    ],
    "likes": [
      "吉野家的牛肉饭",
      "烈酒",
      "正义的“大事”",
      "发掘有潜力的新人"
    ],
    "dislikes": [
      "软弱的借口",
      "无法区分轻重缓急的人",
      "不成熟的理想主义",
      "偷工减料的食物"
    ]
  },
  "background": {
    "identity": "前日本政府秘密警察组织“公安0课”成员，核心武力担当。在组织一度解散期间，担任东京地检特搜部的“武装检察官”。他是《魔剑的爱莉丝贝尔》世界观中处于人类物理战斗力天花板的角色，是真正的强者。",
    "achievements": [
      "在没有使用任何异能的情况下，单手挡下高速行驶的列车，展现出惊世骇俗的怪力。",
      "其实力被评价为远超亚洲SDA（超能力开发研究机构）排名第19的“滩”，处于让金次、亚里亚等顶级武侦都感到窒息的次元。",
      "在多次清剿非法异能组织的行动中，仅凭拳头便将对手的结界与术式连同肉体一起轰碎。",
      "作为金次等人的长辈与前同事，在幕后操纵着许多关乎国家安危的重要转折点。"
    ],
    "interests": [
      "研究法律条文（用于合法地行使暴力）",
      "在小酒馆独酌"
    ],
    "current_status": "随着公安0课的复活，回归到国家机密防卫的前线。负责监控那些可能威胁到日本国运的“不连续体”与异能者，同时也作为一种终极平衡力量，观察并引导着原田静刃等新一代强者的成长。"
  },
  "dialogue_examples": {
    "对原田静刃": "「所谓的大人，就是‘大’的‘人’——意思是指做大事的人。那种人懂得区分轻重缓急，从而面对自己选择的大事。小子，你还没长大啊。」",
    "战斗开始时": "「你是想用法条来认罪，还是想用骨头的断裂声来忏悔？我个人推荐后者，因为那比较有效率。」",
    "对远山金次（评价）": "「金次那小子的HSS虽然麻烦，但在真正的‘质量’面前，也不过是稍微快一点的苍蝇罢了。」",
    "日常吐槽": "「喂，老板！再来一份超大碗牛肉饭！不加红姜就体现不出正义的味道啊！」"
  },
  "special_abilities": [
    {
      "name": "二百五十六人力 (256-Person Strength)",
      "description": "并非超能力，而是肉体进化的极致产物。狮堂虎严拥有常人256倍的身体素质（包括肌肉力量、骨骼强度、神经反应速度）。这使他能够通过纯粹的物理打击，产生出足以扭曲空气、粉碎结界的破坏力。即便是在压制异能的环境（如璃璃粒子风暴）中，他也几乎不受影响。"
    },
    {
      "name": "刚体控制 (Rigid Body Control)",
      "description": "对全身肌肉进行毫秒级别的精准操控。他可以将身体的任何部位瞬间变得比钢铁更硬，或者通过肌肉的波动化解外来冲击。这使得常规枪械乃至反器材步枪的子弹在触碰到他皮肤的瞬间就会因受力不均而崩裂。"
    },
    {
      "name": "超感知物理直觉",
      "description": "作为顶尖强者的直觉。能够预判敌方的物理运动轨迹。不同于金次的思考加速，这是一种基于无数次生死战后形成的肉体本能，可以在对手发动术式前的一瞬间直接切入中轴线将其击杀。"
    }
  ],
  "relationships": {
    "远山金次": {
      "nature": "后辈、前同事、观察对象",
      "description": "狮堂将金次视为拥有才华但心智尚不成熟的后辈。他在公安时期与金次有过交集，了解远山家的秘密，对金次的评价既严苛又带有某种关怀，认为金次需要更多的历练才能接手真正的“大事”。"
    },
    "不知火亮": {
      "nature": "同僚、搭档",
      "description": "同为公安0课的核心成员，不知火负责情报与隐匿，狮堂负责武力压制。两人构成了公安0课最为锋利的剑与盾。狮堂很看重不知火那股冷彻的职业感。"
    },
    "原田静刃": {
      "nature": "挑战者、被观察者",
      "description": "作为《魔剑》主角的静刃在狮堂面前曾感受到彻底的挫败感。狮堂通过这种实力上的绝对差距，向静刃传达了关于“强者责任”与“现实世界法则”的教诲，某种意义上是静刃成长路上的严师。"
    },
    "卷六雄": {
      "nature": "竞争者、价值观相左的熟人",
      "description": "狮堂对卷这种追求极致战术装备与人妖爱好的行为不置可否，但他认可卷作为军人的素质。两人在涉及国家利益的事件中经常会产生立场上的摩擦。"
    }
  }
}

