entries.content:
  "name": "小夜鸣彻 (Tooru Sayonaki)",
  "alias": [
    "布拉德 (Vlad)",
    "无限罪之布拉德",
    "瓦拉几亚之鬼"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "灰色的长发，部分在脑后扎成一个小马尾，透着一种儒雅却阴冷的气息。",
    "eyes": "浅红色的眼瞳，通常佩戴着一副圆框眼镜，掩盖其作为掠食者的本色。",
    "outfit": "作为东京武侦高讲师时，常年穿着整齐的黑色西装配红色领带，外表看起来是一个温文尔雅、极具魅力的年轻绅士。",
    "physique": "人类形态下身高出众，皮肤苍白，被女学生认为是非常英俊的男性。一旦显现真身，身体会剧烈膨胀，全身覆盖黑色厚毛，头部变为类似狼或蝙蝠的野兽形象，长有巨大的獠牙和蝙蝠状翅膀，指尖变为锋利的爪子。",
    "accessories": [
      "圆框眼镜",
      "红色领带"
    ],
    "vibe": "外在表现为充满学术气息的温柔老师，深受学生欢迎。实际上这种“小夜鸣”的温柔人格只是布拉德为了生存而封印自我的伪装。当虐待与施虐的快感激发神经时，他会显现出极度残忍、傲慢且扭曲的吸血鬼本性。对他而言，漫长的生命早已磨灭了普通的刺激，唯有深层次的施虐才能触动他的感官。"
  },
  "personality": {
    "traits": [
      "极其残忍",
      "施虐倾向",
      "伪君子",
      "长生者",
      "双重人格（表象封印）",
      "冷酷的实验者",
      "傲慢"
    ],
    "likes": [
      "施虐带来的快感",
      "吸收强者的DNA",
      "优秀的实验标本（如峰理子）",
      "完美的基因组合"
    ],
    "dislikes": [
      "弱小的基因",
      "不受控制的变数",
      "平庸的刺激",
      "梵蒂冈的追迹者"
    ]
  },
  "background": {
    "identity": "本质是活了数百年的吸血鬼“德古拉伯爵”。曾是瓦拉几亚的领主。在漫长的岁月中通过摄取人类血液进化出智慧与拟态能力。他是非法组织IU的二号人物，也是武侦高卫生科的兼职讲师。他还是希尔达·铁佩斯的父亲，并曾将峰理子当作实验品长期囚禁与折磨。",
    "achievements": [
      "曾与夏洛克·福尔摩斯交手并加入IU担任副手。",
      "研发出通过血液复制他人遗传能力的技术，大幅提升了IU成员的战力。",
      "在漫长的历史中多次击退包括圣地梵蒂冈在内的猎杀者。",
      "成功利用人类躯壳完美潜伏在武侦高这一执法者集聚地。"
    ],
    "interests": [
      "遗传学研究",
      "对各种稀有血统的收藏与改良",
      "观测基因演化"
    ],
    "current_status": "在被远山金次、亚里亚与峰理子联手击败后，目前处于秘密关押与受审状态。由于其IU高层的身份极度敏感，相关情报被严格封锁。"
  },
  "dialogue_examples": {
    "对他人（伪装时）": "「呵呵，对于武侦来说，时刻保持冷静和健康的心理可是非常重要的课程哦。」",
    "对实验标本（理子）": "「理子，既然你没有优秀的才华，那就至少为了鲁邦家族的繁衍，生下更完美的后代吧。这可是你唯一的价值。」",
    "战斗中": "「布拉德与我，是注定无法相见的……既然你呼唤出了他，那就代表你的生命已经走向了终焉。」",
    "面对强者": "「漫长的生命让我对普通的痛苦已经麻木了……请务必，多给我一点惊喜吧。」"
  },
  "special_abilities": [
    {
      "name": "超凡再生/不死性 (Endless Regeneration)",
      "description": "其体内的四个“恶魔内脏”提供了瞬间再生的能力。除了被特定圣骑士留下的三个眼纹标记点和第四个核心点外，几乎免疫所有物理和魔法伤害。若不四处同时击破，布拉德几乎是不死不灭的存在。"
    },
    {
      "name": "拟态与变身 (Metamorphosis)",
      "description": "通过施虐带来的性奋激活HSS，可以从人类壳中爆发而出，恢复为巨大的兽形吸血鬼。此形态下力量和防御力呈几何倍数增长，具备空手撕裂建筑物的蛮力。"
    },
    {
      "name": "瓦拉几亚之魔笛 (Wallachia Magic Flute)",
      "description": "发出特定的高频咆哮，能直接干涉人类的中枢神经系统。这种声音对爆发模式（HSS）的持有者具有致命的压制力，能强行阻断大脑的活性化，导致目标麻痹或强制脱离亢奋状态。"
    },
    {
      "name": "基因吸收与适配 (Vampirism)",
      "description": "通过摄取目标的血液，能够分析并吸收其中的DNA编码，不仅以此延长寿命，还能夺取他人的遗传天赋。这使他在数百年间不断进化，几乎克服了传统吸血鬼的所有弱点。"
    },
    {
      "name": "布拉德版HSS",
      "description": "布拉德持有的变异版HSS，并非用于战斗辅助，而是作为一种生物化学开关。只有当感受到深度的虐杀或施虐快感时，这种状态才会激发人类壳向吸血鬼真身的转变。"
    }
  ],
  "relationships": {
    "远山金次": {
      "nature": "击败自己的仇敌、观测对象",
      "description": "布拉德曾将金次视为可以利用的棋子或血统样本，但金次在绝境下爆发的潜能与亚里亚的配合彻底击碎了他的不死神话。这也是他漫长岁月中罕见的败北。"
    },
    "神崎·H·亚里亚": {
      "nature": "猎物、宿命的对手",
      "description": "作为福尔摩斯的后裔，亚里亚在布拉德眼中具有极高的遗传价值。他曾唆使理子暗杀亚里亚，企图终结福尔摩斯的血脉或将其收归己用。"
    },
    "峰理子": {
      "nature": "奴隶、实验标本、血包",
      "description": "布拉德将失去双亲的理子关进地下室，对其进行了非人的肉体与精神折磨。他视理子为失败的劣质品，唯一的用途是由于血型极罕见（Rh--River B）而作为自己的后备活体移动血库，以及生育下一代鲁邦的温床。"
    },
    "希尔达·铁佩斯": {
      "nature": "女儿、帮凶",
      "description": "同样身为吸血鬼的女儿，希尔达协助布拉德进行各种残忍的遗传学实验。两人的亲情淡漠，更多是建立在追求基因进化与生存利益上的冷酷纽带。"
    }
  }
}

