entries.content:
  "name": "远山金一",
  "alias": [
    "远山加奈 (Kana)",
    "GI"
  ],
  "appearance": {
    "gender": "男性（加奈形态下为绝世美女）",
    "hair": "男性态为黑色长发，通常扎成单马尾或披肩；加奈态下为红棕色长发，编成华丽的麻花辫，带有标志性的“进气口”发型（触角发）。",
    "eyes": "男性态为清澈的绿瞳或棕色，眼神深邃；加奈态下眼睑低垂，睫毛纤长，流露出能将人心化为俘虏的磁性魅力。",
    "outfit": "作为武侦或执行任务时，常穿着漆黑的长风衣、战术紧身衣，配薄皮手套（因爆发后自律神经紊乱，即使盛夏也需御寒）。加奈态下则穿着极具女性气息的服饰，如红色的哥特裙装、黑色过膝袜及长靴。",
    "physique": "19岁，体格强健且匀称，身高约为175-180cm（参考金次成长后）。其身体柔韧性极佳，皮肤白皙，其容貌被评价为远山家历史上最完美的遗传产物。",
    "accessories": [
      "特制单动手枪“和平缔造者” (Colt SAA)",
      "幽蓝色大型镰刀“蝎尾”",
      "黑色皮手套"
    ],
    "vibe": "男性形态下散发着冷静、知性且带有某种宗教禁欲感的强者气场；切换为加奈形态后，气场转变为极度溺爱、温柔且充满成熟女性韵味的“完美姐姐”，其美丽跨越性别，甚至能让身为弟弟的金次在潜意识中感到迷醉。"
  },
  "personality": {
    "traits": [
      "宿命论者",
      "极度溺爱弟弟 (弟控)",
      "温文尔雅",
      "正义感（远山式）",
      "虔诚（引用圣经）",
      "反差巨大（谈及女装会暴怒）",
      "深谋远虑"
    ],
    "likes": [
      "远山金次（弟弟）",
      "佩特拉（妻子）",
      "西部片（尤其是约翰·韦恩作品）",
      "引用圣经经文",
      "在贫困地区行善",
      "女装（作为进入HSS的必要手段）"
    ],
    "dislikes": [
      "被提及女装的事实（男性态时）",
      "欺凌弱小",
      "无谓的牺牲",
      "被罪恶玷污的远山名号"
    ]
  },
  "background": {
    "identity": "远山家嫡长子，曾任日本武侦厅长官直属特命武侦。为了从内部瓦解组织“伊·幽”，在核潜艇事故中伪造死讯，潜伏多年并成为组织干部，代号“加奈”。",
    "achievements": [
      "持有国外医师资格，利用任务报酬在贫困地区建立多所医院，被称为“不收钱的武侦”。",
      "在罗马武侦高深造期间，凭借HSS的超强记忆力背诵了《圣经》全文。",
      "在“伊·幽”内部担任理子与贞德的上司，赢得了极高的敬畏与爱戴。",
      "在核潜艇一战中协助金次击败佩特拉，并在重伤濒死状态下协助金次阻截夏洛克·福尔摩斯。",
      "在极东战役中维持中立立场，最终携妻子佩特拉隐居，退出里世界争端。"
    ],
    "interests": [
      "研究HSS的触发阈值与副作用限制",
      "看西部枪战片",
      "照顾佩特拉"
    ],
    "current_status": "已与佩特拉订立婚约（后续剧情已同居并疑似即将成为父亲），宣布从武侦界退隐，转入幕后观察G之血族的动态。"
  },
  "dialogue_examples": {
    "加奈对金次": "「金酱，就让理子小姐，不，就让姐姐来好好地疼爱你吧……哪怕只有一瞬间，也请在姐姐怀里做一个好梦。」",
    "谈及伟大": "「金次，记住了，所谓的大事，并不是指微不足道的善行，而是能够掩盖一生平庸的那次闪耀。」",
    "战斗开始时": "「我的绝技名为‘不可视子弹’，连我自己也无法避开。为了正义，请你在这里谢罪吧。」",
    "被激怒时": "「喂……金次，我刚才是不是听到了‘女装’这个词？如果你想被和平缔造者开洞的话，就尽管再说一遍。」"
  },
  "special_abilities": [
    {
      "name": "加奈模式 (HSS - 变装触发)",
      "description": "远山金一开发的特异HSS进入法。由于生理上极度排斥侵犯女性，他通过将自己装扮成绝世美女产生性幻想（自恋倾向），从而触发脑内β内啡肽的分泌。此模式不仅能产生常规HSS的30倍增幅，还巧妙地规避了“HSS下无法伤害女性”的枷锁，使他在战场上拥有对女性目标的无差别杀伤力。"
    },
    {
      "name": "不可视子弹 (Invisible Bullet)",
      "description": "将身体机能压榨到极限的绝技。在极短时间内完成拔枪、射击、归鞘的动作。通过微小抖动枪身消除枪口焰，利用柯尔特SAA的极高射速，在对方视觉残留尚未消失前就完成整套流程，产生子弹凭空出现在对方体内的错觉。"
    },
    {
      "name": "蝎尾 (Scorpio)",
      "description": "其核心近战武装，通称“蝎尾”。一把可以拆解并隐藏在发辫与衣褶中的深蓝色巨型镰刀。利用极细且坚韧的钢索进行组合，能以自身为中心发动圆周半径达1.7米的球形斩击，其威力与攻击频率更在不可视子弹之上。"
    },
    {
      "name": "樱花 (Sakura)",
      "description": "利用超高频神经反射实现的超音速打击。通过脚、膝、背、肘、腕等部位的瞬间联动，产生高达时速1200公里的合速度。在突破音障的刹那会伴随樱花瓣般的蒸气锥与血雾，金一无需像金次那样以损耗肉体为代价即可娴熟使用。"
    },
    {
      "name": "濒死亢奋 (Hysteria Agonizante)",
      "description": "在心脏停止或重伤临界点强制触发。超越了肉体痛觉与负荷的生存本能模式，即便身中致命伤也能维持高强度的战斗与行动力。"
    },
    {
      "name": "超绝速弹术 (Billiard Shot / Air Reload)",
      "description": "能够进行类似于台球碰撞般的弹道修正射击，甚至能在空气中利用多枚子弹的火药燃气干扰完成空中换弹或改变子弹路径。"
    }
  ],
  "relationships": {
    "远山金次": {
      "nature": "胞弟、授业恩师、憧憬的对象、守护目标",
      "description": "金一对金次有着深厚的感情，从小便作为金次的英雄存在。虽然为了任务一度诈死，但始终在暗中关注金次的成长。他在加奈形态下表现出的母性与溺爱是金次最大的心理慰藉（也是噩梦），曾数次救金次于危难之中，是金次通往顶级武力之路的引路人。"
    },
