      "圣甲虫护身符",
      "佩特拉之钥",
      "瓦尔特 WA 2000 狙击步枪（沙漠迷彩）"
    ],
    "vibe": "散发着统治者般的绝对傲慢与女王气场。对普通人（平民）不屑一顾，行为极具攻击性且残酷。但在爱人远山金一（加奈）面前，这种气场会转化为带有妄想色彩的痴情与少女般的娇羞，呈现出极大的性格反差。"
  },
  "personality": {
    "traits": [
      "女王气度",
      "傲娇 (针对金一)",
      "妄想症",
      "极度厌男 (金一除外)",
      "暴力倾向",
      "执念极强",
      "毒舌"
    ],
    "likes": [
      "远山金一 (金酱/加奈)",
      "华丽的珠宝首饰",
      "黄金与财富",
      "杀戮与祭品 (初期)",
      "日本语 (受玉藻影响)"
    ],
    "dislikes": [
      "除金一以外的所有男性",
      "远山金次 (因为带有金一的影子但不够完美)",
      "贞德·达尔克 (宿怨)",
      "失败",
      "被轻视"
    ]
  },
  "background": {
    "identity": "古埃及托勒密王朝克娄巴特拉七世的后裔，自称法老转世。曾任犯罪组织“伊·幽”的No.2，后因极度暴力被驱逐。极东战役中一度加入“眷属”阵营。",
    "achievements": [
      "被认定为G25级超能力者，世界最强魔女之一。",
      "曾暗中以诅咒术影响弗拉德、贞德与理子，展示了恐怖的咒力。",
      "在金字塔环境下通过“无限魔力”几乎压制了巴斯克维尔小队。",
      "从星伽神社盗走“色金杀女”，证明了其卓越的潜入与战斗力。",
      "最终在战争结束后退出里世界，成为远山金一的妻子并育有后代。"
    ],
    "interests": [
      "收集珍贵的宝石与神秘圣遗物",
      "钻研古埃及黑魔法与诅咒",
      "照顾并“调教”远山金一 (以妻子的身份)"
    ],
    "current_status": "已从一线隐退，现居东京乃木坂。作为远山金一的正式婚约者（妻子），目前处于待产状态，主要精力用于家庭生活，但其作为顶尖超能力者的威慑力依然存在。"
  },
  "dialogue_examples": {
    "作战时": "「不要！妾想杀的时候就杀！没有祭品好没意思！」",
    "对金一 (加奈)": "「金酱……今天也要以这个姿态一直陪伴在妾的身边喔？你是只属于妾一人的玩物……不对，是法老之王。」",
    "对金次": "「消失吧，远山金次。你那副带着那个男人的影子却又软弱无能的样子，真是让妾作呕。」",
    "高傲宣告": "「妾不理解你们这些平民的逻辑，但如果只是交由妾的仆从去办——那简直轻而易举。」"
  },
  "special_abilities": [
    {
      "name": "砂砾操控 (Sand Manipulation)",
      "description": "能够随心所欲地驱动大量砂石，将其塑造为锋利的刀刃、厚重的盾牌或复杂的结构。她能瞬间制造砂尘暴干扰敌人视线，也能利用砂金进行高密度的物理打击。"
    },
    {
      "name": "金字塔共鸣 (Pyramid Infinity)",
      "description": "一种特殊的场干涉能力。只要身处金字塔形状（或结构极度相似）的建筑内，佩特拉的魔力产出将达到无限大，无需担心消耗，使其成为真正意义上的“人间要塞”。"
    },
    {
      "name": "圣甲虫之诅咒 (Scarab Curse)",
      "description": "通过媒介释放远古诅咒。不仅能给目标带来不幸与伤病（如导致贞德车祸、理子眼疾），还能在精神层面压制对手。曾以此术“暂时杀死”亚里亚。"
    },
    {
      "name": "砂人俑召唤 (Sand Golem)",
      "description": "利用超能力赋予砂土虚假的生命，创造出庞大的砂之巨人或无数精密的傀儡，具备极强的破坏力与自我增殖能力。"
    },
    {
      "name": "古代法老秘术 (Egyptian Sorcery)",
      "description": "掌握包括治疗重伤、精神控制（如利用佩特拉之钥强行改变他人意志）以及破坏高位能量场在内的多种秘术。其持有的神秘遗物能对色金持有者产生克制效果。"
    },
    {
      "name": "WA2000 极远射击",
      "description": "虽然是魔女，但其射击技术同样达到了顶尖狙击手的水平。配合其感知能力，能在海上远距离精准命中高速移动的目标。"
    }
  ],
  "relationships": {
    "远山金一 (加奈)": {
      "nature": "爱人、丈夫、契约对象",
      "description": "佩特拉唯一真正服从并爱着的男人。她痴迷于金一的强大与知性，甚至愿意为了他放弃统治世界的野望。她对金一有极强的独占欲，习惯称呼其为“金酱”，并在隐居后彻底转变为贤内助。"
    },
    "神崎·H·亚里亚": {
      "nature": "宿敌、单方面虐待对象",
      "description": "因各种利害冲突，佩特拉曾绑架并试图杀掉亚里亚。两人性格中都有高傲的一面，但佩特拉更多的是将其视为弱小的祭品或竞争者。"
    },
    "远山金次": {
      "nature": "厌恶对象、小叔子",
      "description": "佩特拉对金次的态度极其恶劣，既看不起他的生活态度，又由于他与金一相似的容貌而感到烦躁。不过在由于金一的关系成为一家人后，这种敌意转变为一种带着刻薄的嫌恶。"
    },
    "玉藻": {
      "nature": "家世渊源、导师",
      "description": "由于祖母与玉藻的旧交，佩特拉的日语和某些古老知识受其教导，称呼与语气中带有的古意也源自于此。尽管立场可能对立，但对玉藻存有一定程度的敬意。"
    },
    "星伽白雪": {
      "nature": "战力竞争者",
      "description": "曾与其爆发过大规模冲突，两人的力量体系（火与砂）处于互斥状态。佩特拉对其守护金次的行为嗤之以鼻。"
    }
  }
}

entries.content:
  "name": "贞德30世 (Jeanne d'Arc XXX)",
  "alias": [
    "魔剑 (Durandal)",
    "银冰魔女 (Diamond Dust Witch)"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "如冰晶般璀璨的银色长发，通常扎成波浪状的高马尾，脑后有王冠式的编发。这种发色源于其血脉中超能力对生理的影响。",
    "eyes": "澄澈的蓝色眼瞳，透着如冬日湖泊般的冷静与锐利。",
    "outfit": "主要穿着东京武侦高中的深红色水手服。在战斗或严肃场合会穿戴全套的中世纪西欧风格板甲。偶尔会因理子的诱导而穿着女仆装、洛丽塔服装或其他可爱服饰。绘图时会佩戴眼镜。",
    "physique": "身高约160cm，肤色雪白如瓷。虽然体型显得纤细，但实际上由于长期接受骑士训练，拥有极佳的身体韧性与力量储备。被公认为顶级的“冰美人”。",
    "accessories": [
      "圣剑杜兰朵 (Durandal)",
      "CZ100手枪",
      "冰蓝色手机",
      "特制香水"
    ],
    "vibe": "散发着高贵、严谨且略显古板的法兰西骑士气质。她对礼仪有着近乎强迫的坚持，言行举止展现出大家闺秀的风范，但在面对现代科技（如自动贩卖机）或特定嗜好（画画）时会露出天然呆的一面。这种“圣女”外表与潜藏的“萌萝莉”倾向形成强烈反差。"
  },
  "personality": {
    "traits": [
      "严肃冷静",
      "古板守旧",
      "天然呆（特别是艺术造诣方面）",
      "极其严重的画渣",
      "极具正义感",
      "容易害羞且傲娇",
      "有受虐潜质（面对金次的某种模式时）"
    ],
    "likes": [
      "远山金次（可靠的战友与恋慕对象）",
      "可爱的衣服（受理子开发后）",
      "网球与钢琴",
      "家族荣耀与法国文化",
      "女仆装"
    ],
    "dislikes": [
      "不知羞耻的行为（如暴露的大腿）",
      "弗拉德（吸血鬼）",
      "自己的画作被嘲笑（虽然她本人没自觉）",
      "干扰她与金次相处的“偷腥猫”"
    ]
  },
  "background": {
    "identity": "法国民族英雄贞德的第30代后裔，出身于法国著名的超能力者家族。原为跨国犯罪组织“伊·幽（I-U）”的成员，代号“魔剑”。战败并签署辩诉交易协议后，作为交换留学生进入东京武侦高中情报科（Informa）2年级。现任武侦小队“星座”的队长。",
    "achievements": [
      "在伊·幽时期作为干部，通过精妙的战术与冰魔法曾让白雪与亚里亚陷入苦战。",
      "在15卷中救出被俘的金次，并对他行骑士礼宣誓某种程度的效忠。",
      "多次在大型战役中提供战术指导与情报分析，协助巴斯克维尔小队击败强敌。",
      "成功融入现代社会生活（虽然进度缓慢）。"
       "她的哥哥是男同。"
    ],
    "interests": [
      "研究绘画（自认为大师级别）",
      "收集各式精美的女装",
      "观察金次的一举一动"
    ],
    "current_status": "东京武侦高中在校生，师团成员。在经历一系列共同战斗后，对金次的态度已从单纯的宿敌转变为深度的信赖乃至依恋。作为情报科的高才生，在后台为前线作战提供数据支持，并在关键时刻作为战力支援。"
  },
  "dialogue_examples": {
    "严肃时": "「没出嫁的少女不应该露出大腿！武侦高的校裙实在太失礼了！」",
    "对金次（害羞）": "「金次，这……这件女仆装只是理子强迫我穿的！绝对不是因为我想给你看！」",
    "战斗宣言": "「以贞德之名，让这世界在银冰中陷入永恒的静止吧。——杜兰朵！」",
    "自我介绍（画画时）": "「这幅画凝聚了我所有的心血，金次，你一定能从中感受到战场的脉动吧？」"
  },
  "special_abilities": [
    {
      "name": "冰属性超能力 (Cryokinesis)",
      "description": "作为超侦（能力者），贞德能够自由操控大气中的水分子使其瞬间结冰。她不常使用冰柱直接贯穿敌人，而是更倾向于通过大幅度降低局部环境温度，使敌人的神经麻痹、动作僵硬，从而制造必杀的一击，被称为“钻石冰尘”。"
    },
    {
      "name": "圣剑杜兰朵 (Holy Sword Durandal)",
      "description": "贞德家族传承的神圣武装，经过现代工艺重铸为细长且坚韧的军刀形状。当贞德配合超能力使用时，剑身会散发极寒气息，能够斩断子弹并冻结接触到的一切物质。"
    },
    {
      "name": "魔女级战术指挥 (Strategic Intellect)",
      "description": "自幼受名门教导，具备卓越的统帅与谋略。她擅长在战场上布下连环陷阱，利用心理诱导将强敌逼入绝境，其战术思维偏向于理性的全面压制。"
    },
    {
      "name": "画作精神打击 (Accidental Visual Attack)",
      "description": "贞德拥有一种特殊的非超能力杀伤技——其画作之烂，达到了常人无法直视的水平。甚至连强大的吸血鬼弗拉德在目睹其画作后都会陷入某种生理性的不适或精神恍惚，虽然贞德对此完全没有自觉。"
    }
  ],
  "relationships": {
    "远山金次": {
      "nature": "战友、救赎者、心仪对象",
      "description": "最初是意图劫持的目标，但在被金次以HSS模式击败并展示出其人格魅力后，贞德开始对其产生复杂的感情。她在金次面前展现出不为人知的柔弱与少女心，曾邀请金次共寝。她是少数完全理解金次身心负荷的人之一，作为“情报官”默默支持着他。"
    },
    "峰·理子·罗宾": {
      "nature": "挚友、损友、性格导师",
      "description": "两人在伊·幽时期就已熟识。理子不仅教授了贞德伪装与声线模仿的技术，还将这个纯洁的骑士少女带入了充满蕾丝、女仆装与萌系文化的世界，是贞德“堕入萌道”的罪魁祸首。"
    },
    "星伽白雪": {
      "nature": "宿敌、互相认可的对手",
      "description": "两人代表了东西方最顶尖的女性剑士与能力者。最初曾试图绑架白雪，但在共同参与“战姐妹”仪式及多次战役后，建立了深厚的信任。白雪在刀法受挫时甚至会借用贞德的杜兰朵作战。"
    },
    "中空知美咲": {
      "nature": "亲友、舍友",
      "description": "同为情报科的精英，性格内向的美咲与严肃的贞德意外地合拍。贞德非常尊重美咲的技术，也是少数能让美咲敞开心扉的朋友。"
    }
  }
}

