entries.content:
  "name": "远山雪花",
  "alias": [
    "远山夕华 (Tohyama Yuka)",
    "海军中佐",
    "首席通信官"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "如夜色般深邃的黑色长发，发量丰盈且质感柔顺。她在脑后位置用一条纯白色的丝带将长发系起，垂至腰际，展现出一种古朴而庄重的和风美感。",
    "eyes": "一双晶莹剔透的碧绿色眼眸（Green Eyes），眼神锐利如刀，透着军人特有的果敢与威严，与她温婉的外表形成强烈反差。",
    "outfit": "主要穿着旧日本海军风格的改制服：上半身为带有红色领缘的白色水手衬衫，佩戴带有金色海军徽章的白色军帽，斜跨战术皮带；下半身则是红色褶皱百褶裙配黑色过膝袜与漆皮皮鞋。其腰间总是挂着一柄作为身份象征的长刀。",
    "physique": "外表年龄约20岁。身材高挑且凹凸有致，拥有令人瞩目的丰满上围（Large Breasts）。肤质雪白如瓷，尽管常年处于军旅生涯，却依然保持着极高水准的女性魅力。其容貌与星伽白雪有几分神似。",
    "accessories": [
      "指挥刀 (佩刀)",
      "海军中佐军帽",
      "白色丝带 (发饰)"
    ],
    "vibe": "散发着一种超越时代的“旧帝国军官”气场。她坚毅、果敢且不苟言笑，言行举止中带着一种近乎僵硬的荣誉感。作为被强行带到现代的“断层之人”，她那肃穆的军人气质与现代社会的浮躁氛围格格不入，却又因其极高的颜值和独特的人设，在网络上被误解为一种极具反差萌的“角色扮演”。"
  },
  "personality": {
    "traits": [
      "极度民族主义",
      "武断与霸道",
      "古板守旧",
      "军事化思维",
      "强硬派",
      "行动派",
      "隐藏的大和抚子 (指家事万能)",
      "由于被当作男性培养而产生的性别认知错位 (不自觉的暴力倾向)"
    ],
    "likes": [
      "纪律与绝对服从",
      "剑术锻炼",
      "远山家的家族荣誉",
      "传播其右翼政治理念 (通过Youtube平台)",
      "将现代软弱的年轻人“回炉重造”"
    ],
    "dislikes": [
      "现代社会的奢侈与软弱",
      "不守规矩的“草食男”",
      "任何轻视远山家 bloodline 的言论",
      "无法适应的高科技日常 (虽作为通信官但对生活电子产品陌生)"
    ]
  },
  "background": {
    "identity": "旧日本海军陆战队中佐、首席通信官。远山金叉的姑母，远山金次等人的曾祖姑母（遗传学意义上的直系长辈）。她是远山家隐藏于历史阴影中的重要支脉，曾参与过二战期间的绝密军事计划，现因某种原因（涉及色金或异世界重叠）在现代苏醒并执行跨越时代的密命。",
    "achievements": [
      "在二战期间以20岁的年纪升任海军中佐，展现出卓越的指挥与战略天赋。",
      "成功执行了持续数十载的机密军事任务，并将自身状态维持至今。",
      "派遣部下（恩蒂米拉）精准接触远山金次，试图重整“巴斯克维尔”战力以应对世界级危机。",
      "意外成为人气网红，其传播的激进言论被现代网民视为高水平的“傲娇角色塑造”。"
    ],
    "interests": [
      "运营Youtube频道宣传军国思想",
      "指导金次如何成为“真男人”",
      "研究现代武器与旧式剑术的融合"
    ],
    "current_status": "活跃于极东战役的阴影中。目前以远山家“长辈”的身份介入金次的生活，试图利用其旧时代的价值观纠正现代武侦的“不正之风”，并指挥着一支拥有古老背景的隐秘部队。"
  },
  "dialogue_examples": {
    "对金次": "「这就是现代远山家的后裔吗？这副颓废的样子，简直是家族的耻辱！给我站好，接受海军式的洗礼！」",
    "录制视频时": "「各位国民，现代的繁荣只不过是虚假的幻象，唯有磨砺脊梁与灵魂，才能在接下来的浩劫中存续……记得点击订阅和投币。」",
    "战斗中": "「在绝对的力量面前，现代的软弱逻辑毫无意义。远山家血脉的真正恐怖，你还没见过万分之一。」",
    "关于时代": "「即便世界改变了颜色，远山家的武士魂也绝不会在此凋零。我会亲手将这个偏离航道的社会纠正回来。」"
  },
  "special_abilities": [
    {
      "name": "HSS (爆发模式 - 纯净血脉)",
      "description": "由于身处血脉稀释度极低的旧时代，雪花的HSS极度稳定且强大。进入模式后，其反射神经与思维加速达到常人的40倍以上，且几乎没有现代远山后裔那种剧烈的副作用。"
    },
    {
      "name": "星伽流鬼道术/天降之术",
      "description": "通过远山家与星伽家的姻亲关系，掌握了古老的超自然战斗技法。能够通过特殊的咒力干涉大气电场，施展类似“落雷”或“重力压制”的效果。"
    },
    {
      "name": "超凡剑技 (海军式古剑术)",
      "description": "将实战中的刺杀术与远山家的物理干涉技巧结合。其刀锋不仅能切断物质，甚至能通过精准的力量传导切开炸药的引信而不触发爆炸，其技艺位列大剑豪级别。"
    },
    {
      "name": "战术通信干涉 (Expert Communication)",
