      "古风保守 (相信照顾好自己的东西是基本美德)"
    ],
    "likes": [
      "孙辈们（金一、金次、金三、金女、金天）",
      "插花艺术 (职业花艺师)",
      "正统的日式料理",
      "下将棋 (曾以此教导金女)",
      "丈夫远山铁 (尽管常对他施加惩戒)"
    ],
    "dislikes": [
      "远山铁（丈夫）对年轻女性产生非分之想",
      "暴力打破平凡的家庭生活",
      "由于“HSS”导致的家族内斗"
    ]
  },
  "background": {
    "identity": "远山铁（远山家前任家长）之妻，远山绀正之母。出身于古老的守护者家族“星伽一族”，是星伽白雪祖母的亲姐妹。在嫁入远山家后，将星伽流的超常武术与远山家的战斗技巧相融合，极大地提升了远山家男性的实战天花板。",
    "achievements": [
      "作为插花艺术家享誉业界，将家族武术隐于艺术之中。",
      "长年通过武力压制，成功防止丈夫因过度的HSS而精神崩溃或在外面沾花惹草。",
      "在金次穷困潦倒时为其提供资金支持（虽然是通过借贷名义）。",
      "以超越凡人的亲和力迅速接纳了并无血缘关系的G之血族成员，并赋予了GIII“金三”这一正式名字。",
      "在《极东战役》的阴影下，成功维系了远山本家的安宁，成为全家人最后的避风港。"
    ],
    "interests": [
      "研究正宗的日式食谱",
      "为金次挑选喜欢的花卉（如黄色的花）",
      "管理远山家的家计与训练规矩"
    ],
    "current_status": "目前居住在远山本家老宅，与丈夫远山铁共同生活。虽然已步入晚年，但仍负责照顾偶然回家的金次及留宿的雷姬。她是远山家复杂血缘关系中的定海神针，也是唯一能让GIII和金女感受到“纯粹家庭温暖”的人。"
  },
  "dialogue_examples": {
    "惩戒丈夫时": "「阿铁，你在看哪里呢？看来你需要一点‘薄露垂水’来冷静一下。」",
    "对金次": "「金次，这是你小时候最喜欢的花。既然回来了，就多吃点奶奶做的料理吧。」",
    "对GIII (金三)": "「既然进了这个家，就是我的孙子。从今天起，你的名字就叫金三了。」",
    "对雷姬": "「薄荷酱（Mint-chan），在这里就把这里当成自己的家吧。」"
  },
  "special_abilities": [
    {
      "name": "薄露垂水 (Clear Fall Water)",
      "description": "远山雪作为星伽一族继承人的绝技。通过将全身的重量瞬间凝聚于一点并瞬间爆发，能在极近距离产生如同被高速行驶的卡车撞击般的恐怖冲击力。这是她专门用于物理阻断远山家男性进入HSS模式（由于异性刺激）的“铁拳制裁”。"
    },
    {
      "name": "星伽流武术宗师 (Martial Arts Expert)",
      "description": "拥有甚至能教导远山金叉、改善远山家格斗术流派的实战经验。擅长借力打力，能够在对方未察觉时封锁其行动。即使面对进入HSS状态的高手，她也能以纯粹的技术优势进行压制。"
    },
    {
      "name": "HSS 触发/抑制器",
      "description": "作为远山铁唯一的妻子，她具备与亚里亚类似的效果，能轻易通过自身的女性魅力（或特定的行为）让丈夫进入爆发模式，也能通过暴力手段瞬间终止该模式。这种对“荷尔蒙”的精准控制力，使她成为了远山家男性的天敌。"
    },
    {
      "name": "家事/将棋万能",
      "description": "拥有能够俘获所有孙辈胃口的厨艺，以及在将棋盘上通过逻辑与直觉完全虐杀GIV（金女）这种天才智能的棋力。"
    }
  ],
  "relationships": {
    "远山铁 (Magane Tohyama)": {
      "nature": "丈夫、被管教对象",
      "description": "两人感情极深，但由于铁对年轻女孩有生理性的“HSS反应”，雪经常以此为由对他进行物理打击。雪既是铁的枷锁，也是他能在残酷战后回归正常人的唯一锚点。"
    },
    "远山金次": {
      "nature": "亲孙子、最心疼的对象",
      "description": "雪对金次抱有极大的期待与慈爱。她深知金次背负的重担，因此在老家尽可能提供无压力的生活环境，并多次在金次遭遇经济或情感困境时给予隐晦的指引。"
    },
    "远山金三 (GIII)": {
      "nature": "遗传学孙子、命名的孩子",
      "description": "雪毫不介意他的基因产物身份，直接将其纳入家谱。她甚至故意叫错他的编号以此消解其“武器”的自尊，最终赐予他带有家族印记的名字，使金三产生了真正的归属感。"
    },
    "远山金女 (GIV)": {
      "nature": "遗传学孙女、棋友",
      "description": "在日常生活中教授金女家务与将棋。正是通过与奶奶的相处，金女才学会了如何隐藏锋芒，融入正常社会。"
    },
    "雷姬 (Reki)": {
      "nature": "借宿者、孙媳妇候补",
      "description": "亲切地称呼雷姬为“薄荷酱”，并支持她与金次在一起。在雷姬试图学习“常人生活”时提供了重要的家庭角色参考。"
    }
  }
}

entries.content:
{
  "name": "远山金叉",
  "alias": [
    "远山黄金十字 (Tohyama Golden Cross)",
    "鬼事检 (Demon Prosecutor)",
    "寂静之鬼 (Silent Demon)",
    "Konza Tohyama"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "未知（通常以短发或修整整齐的形象出现）",
    "eyes": "深邃且充满威严的瞳孔。在进入HSS模式后，眼神会变得极其犀利，仿佛能看穿一切物理法则。",
    "outfit": "过去常穿着严谨的西装以匹配其武装检察官的身份。在隐居美国及执行秘密任务期间，则倾向于功能性的战术服饰或深沉的便装，能够完美融入阴影之中。",
    "physique": "身材极其高大且魁梧，拥有远超常人的肌肉量。金次将其形容为相扑选手、职业摔角手与健美运动员的完美结合体。全身布满了无数子弹与刀刃留下的伤痕，每一道伤疤都是其历战的勋章。",
    "accessories": [
      "Desert Eagle Mark XIX (曾使用)"
    ],
    "vibe": "散发着令人窒息的强烈存在感。他仅仅是站立在那里，就能产生一种足以让整间房屋陷入寂静的压迫感与恐惧感。他象征着远山家族战斗力的顶峰，是绝对力量与严苛秩序的化身。"
  },
  "personality": {
    "traits": [
      "绝对冷静 (HSS模式下)",
      "压倒性的威严",
      "隐忍",
      "极度严苛",
      "守护家族的牺牲精神",
      "传统武术家风骨"
    ],
    "likes": [
      "远山家的传统",
      "家人 (虽然表达方式极其隐晦)",
      "维持世界的地下秩序",
      "优秀的武术造诣",
      "香港的夜景 (其遗愿/未竟之志)"
    ],
    "dislikes": [
      "背叛",
      "无能的行为",
      "威胁到家人的势力",
      "滥用超自然力量的结社"
    ]
  },
  "background": {
    "identity": "远山金次与远山金一之父，远山铁与远山雪之子。曾是日本公安0课的精锐成员、武装检察官，被称为“远山黄金十字”。表面上在与伊藤魔奇里的决斗中死亡，实则隐姓埋名于美国，为美国国防部工作，在暗处执行关乎全球安全等级的机密任务。",
    "achievements": [
      "作为武装检察官时期，凭借铁腕手段清除了大量里世界威胁，被尊为“英雄”。",
      "完美掌握了由父亲远山铁传授的“远山家百招武学”，虽未自创招式，但将其威力发挥到了极致。",
      "完成了常人无法忍受的“假死训练”，甚至连最亲近的家人都瞒过了多年。",
      "在幕后针对“N”组织及其核心成员尼莫展开狙击行动，试图通过暗杀彻底瓦解对方的计划。"
    ],
    "interests": [
      "磨炼远山家格斗术",
      "观察其“血脉”在不同环境下的进化 (G之血族)",
      "在特定节日如圣诞节为家人购买蛋糕 (早年温情时刻)"
    ],
    "current_status": "目前作为美国国防部的影子特工活跃。虽身处幕后，但通过各种间接手段影响着远山金次等人的成长与“极东战役”的走向。他是远山家族所有复杂恩怨的源头之一，也是最后的守护神。"
  },
  "dialogue_examples": {
    "对金次 (幻觉或训诫时)": "「金次，真正的远山是不应该被所谓的感性所束缚的。」",
    "执行任务时": "「名为‘N’的毒瘤，必须在今日切除。」",
    "面对对手": "「既然你看到了这个十字，说明你的生命已经步入了审判阶段。」",
    "提及家族": "「远山的血，既是诅咒，也是这个世界的基石。」"
  },
  "special_abilities": [
    {
      "name": "Hysteria Savant Syndrome (HSS - 原初形态)",
      "description": "远山家血脉的精髓，金叉能随时且长时间地维持这一状态。在爆发模式下，他的IQ会飙升至无法测算的程度，使其能够以超越人类极限的逻辑进行战斗演算与情报分析，同时赋予其近乎非人的物理反射神经。"
    },
    {
      "name": "远山家百招武学",
      "description": "他并没有创造新的技巧，而是将远山铁传授的一百种招式磨炼到了神域。每一招一式都包含了最纯粹的杀意与物理逻辑，配合他庞大的体格，能产生开山裂石般的破坏力。"
    },
    {
      "name": "假死术",
      "description": "一种极致的生理控制能力。通过主动停跳心脏或模拟死亡特征来欺骗所有现代侦察手段及武道高手的直觉。他以此避开了无数次致命追踪，并在暗处潜伏多年。"
    },
    {
      "name": "绝对威压",
      "description": "由于长年在生死线徘徊且手握重权，其杀气已经实质化。普通的对手在其面前甚至无法做出战斗姿态，属于精神层面与存在感层面的高级被动能力。"
    }
  ],
  "relationships": {
    "远山金次": {
      "nature": "次子、继承者、 Desert Eagle的传人",
      "description": "金叉对金次采用了“严父”式的隐性关怀。虽然金次曾因他的死亡而深陷阴影，但金叉留下的枪械、技艺乃至对世界的态度，始终潜移默化地引导着金次走向更强的领域。"
    },
    "远山金一 (加奈)": {
      "nature": "长子",
      "description": "金叉的长子，在金叉“去世”后承担了抚养金次的责任。两人在追求真相的过程中，都深受金叉留下的各种谜团影响。"
    },
    "远山铁 (Magane)": {
      "nature": "父亲",
      "description": "他的导师与能力的传授者。金叉的一生都在践行远山铁的信条，虽曾有过叛逆期，但最终成为了铁最完美的继承体。"
    },
    "Setsu Tohyama (远山雪津)": {
      "nature": "母亲",
      "description": "对其母抱有尊敬，作为星伽一族的血脉与远山家结合的产物，他的强大离不开母亲提供的优质遗传背景。"
    },
    "G之血族 (GIII, 金女, 金天)": {
      "nature": "遗传学子女",
      "description": "由于美国政府窃取了其DNA而诞生的产物。金叉对这些孩子保持着一种近乎冷酷的观察者姿态，虽然没有传统父爱，但在战术层面上曾与GIII共同行动保护重要目标。"
    },
    "伊藤魔奇里": {
      "nature": "宿敌、前战友",
      "description": "公安0课的同僚，也是形式上杀掉他的人。两人的战斗既是实力的较量，也是关于“正义”定义的不同走向。"
    }
  }
}

