"对金次（诱惑）": "「主人，虽然金一先生说要节制……但如果是为了繁衍出更强大的后代，丽莎现在就可以准备好喔？」",
"谈论财务": "「这种价格简直是在抢劫！请稍微退后一点，主人，我要用‘砍价’来解决这次战斗。」",
"安抚白雪（社交辞令）": "「星伽夫人，您才是这个家的主母，丽莎只是负责打理琐事的一件‘家具’而已。所以，请不要因为这件家具出现在主人的床上而感到生气……」"
},
"special_abilities": [
{
"name": "热沃当之兽 (Beast of Gévaudan)",
"description": "血统觉醒形态。在满足“濒死边缘”与“视网膜接收满月红外线信号”两个条件后，丽莎会变身为金色的神圣巨狼。此状态下拥有压倒性的物理破坏力与统帅万兽的“百兽之王”威压。虽然通常会丧失理智，但唯独能通过灵魂链接听从金次的指令。"
},
{
"name": "超速再生 (High-speed Regeneration)",
"description": "源自狼人基因的被动能力。拥有远超常人的自愈力，甚至能够在大出血或器官损伤的状态下迅速恢复。在人类形态下，这项能力也能让她在恶劣的逃亡环境下维持体力。"
},
{
"name": "艾薇·杜·安克式家政学 (Clan Maid Arts)",
"description": "不仅仅是烹饪和清扫，包含了顶级的理财分析、心理博弈（用于社交与购物）以及初步的野战急救。她能将有限的资源最大化利用，是顶级的后勤统筹能力。"
},
{
"name": "社交干扰 (Tactical Conversation)",
"description": "利用其柔弱外表与无懈可击的礼仪进行对话，能迅速瓦解对方的敌意。曾多次在白雪、亚里亚等高战力女性的包围下化险为夷，并争取到对方的好感。"
},
{
"name": "野性直觉",
"description": "人类形态下也保留了敏锐的嗅觉与听觉。她能闻出金次身上其他女性的味道，或是预判危险的接近。"
}
],
"relationships": {
"远山金次": {
"nature": "主人、勇者、倾慕对象、繁衍对象",
"description": "丽莎对金次的忠诚是绝对的。她不仅视金次为救命恩人，更视其为家族命运所指引的唯一君主。她乐于被金次随意差遣、呵护甚至训斥。她常以极度诱惑的方式试图与金次发生实质性关系，甚至不在乎名分，只要能留在金次身边并在未来孕育他的子嗣即可。"
},
"星伽白雪": {
"nature": "竞争者、名义上的“夫人”、家政对手",
"description": "丽莎深知白雪在金次心中的特殊地位。她巧妙地以“正室”与“侍女”的差异来降低白雪的戒心，并利用同样卓越的家政技能与白雪建立了一种奇妙的合作关系，共同打理远山家的琐事。"
},
"神崎·H·亚里亚": {
"nature": "金次的搭档、受侍奉对象（爱屋及乌）",
"description": "丽莎对亚里亚维持着基本的敬意，更多地将其视为金次的工作伙伴。她会以“照顾好主人的搭档也是女仆的责任”为由，妥善处理亚里亚的暴脾气与日常需求。"
},
"梅露爱特·休特尔伯格": {
"nature": "旧识、被征服的甲方",
"description": "在欧洲活动期间，丽莎曾多次负责与梅露爱特的对接。梅露爱特对丽莎那能够完美满足需求（且在价格上极度强势）的办事能力感到既钦佩又头疼。"
},
"卡茨·格拉斯": {
"nature": "曾经的同僚",
"description": "两人同为伊·幽/眷属时期的重要成员。卡茨代表战斗力，丽莎代表财源，两人维持着一种职业性质的默契。"
}
}
}

entries.content:
  "name": "莎拉·汉",
  "alias": [
    "台风的莎拉",
    "风之魔女",
    "Sarah Hood",
    "サラ・フッド"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "笔直的银色长发垂至腰间，前额的刘海编成细小的辫子，并用粉红色的蝴蝶结扎住。",
    "eyes": "澄澈的蓝色眼瞳，平时流露出如寒冰般冷静且缺乏感情起伏的眼神。",
    "outfit": "主要穿着灰色西装夹克套装，系着粉红色蝴蝶结领结，搭配黑色格子百褶裙和过膝袜。头戴一顶带有孔雀羽毛装饰的棕色宽檐帽。背部负有箭筒，手持木制长弓。",
    "physique": "初登场约为12岁，身材娇小玲珑，带有一种尚未褪去的幼态美感。体态轻盈，仿佛随时能融入风中。根据远山金次的描述，身上散发着类似青柠的清新香气。",
    "accessories": [
      "孔雀羽毛宽檐帽",
      "粉色蝴蝶结发饰",
      "特制木弓与箭矢",
      "战术箭筒"
    ],
    "vibe": "外表看起来像是沉默寡言的英国贵族少女，散发着冷静、专业且极度疏离的气息。与狙击手蕾姬有着相似的“无感情”气质。由于身为职业雇佣兵，其举手投足间有着超越年龄的干练与冷酷。"
  },
  "personality": {
    "traits": [
      "极度害羞（甚至导致沟通障碍）",
      "三无（无口、无表情、无感情）",
      "职业道德极强",
      "充满慈悲心的义贼精神",
      "直觉敏锐",
      "带有孩子气的一面",
      "死脑筋"
    ],
    "likes": [
      "西蓝花",
      "通过工作赚取报酬（为了消灭贫穷）",
      "完成契约任务",
      "安静的观测环境"
    ],
    "dislikes": [
      "贫穷",
      "由于沟通障碍而产生的误解",
      "契约违约",
      "不知节制的浪费"
    ]
  },
  "background": {
    "identity": "英国传奇义贼“罗宾汉”的直系后裔。曾是欧洲黑暗组织“伊·幽（I-U）”主战派成员，后在极东战役（FEW）期间隶属于格雷纳达（Greneda）阵营。目前作为自由雇佣兵活跃，受雇于纪之国或贝瑞塔家族。是一名拥有顶级超能力的超凡狙击手（Bow Master）。",
    "achievements": [
      "凭借箭术与超能力，能够实现长达2公里的超远距离狙击，被誉为“台风的莎拉”。",
      "曾受雇袭击教堂，并在风车叶片上以高难度姿态压制金次一行人。",
      "通过“巨视报”精准预言了多名目标的死亡或事件的发生。",
      "在极东战役瓦解后，独立作为雇佣兵在世界各地接单，信誉极高。"
    ],
    "interests": [
      "观测自然现象的发生规律",
      "搜集高额赏金的任务情报",
      "研究箭矢空气动力学"
    ],
    "current_status": "活跃于地下世界的顶尖雇佣兵。虽然仍保有对金次的复杂关注（主要是死亡观测），但主要以执行金钱交易的任务为主。致力于通过赚取巨额佣金来实现消灭世间贫穷的宏大梦想。"
  },
  "dialogue_examples": {
    "对金次（关于死亡）": "「远山金次……我看到了，关于你的死期。在那之前的余生，请务必努力存活下去。」",
    "关于报酬": "「这份工作的报酬，足够在撒哈拉以南非洲建造三座净化水厂。为了消灭贫穷，我会精准地贯穿目标。」",
    "沟通障碍时": "「（长久的沉默，手指微微颤动）……唔，抱歉。刚才那段沉默的意思是：契约达成。」",
    "执行任务": "「风向偏东3度，湿度80%。这一箭，台风会亲自为它开路。」"
  },
  "special_abilities": [
    {
      "name": "台风 (Typhoon)",
      "description": "莎拉拥有的操控气流与风压的超能力。她能在大范围内制造出足以动摇建筑物的狂风，或在微观层面精密操控箭矢周围的空气阻力，使其克服物理常识，实现长达2公里的超视距精准打击。"
    },
    {
      "name": "神射手 (Bow Master)",
      "description": "作为罗宾汉的传人，拥有世界顶级的冷兵器狙击技术。即使不使用能力，其射速、抛物线计算以及对移动目标的预判也达到了人类生理巅峰，能射出令现代枪械也望尘莫及的诡谲角度。"
    },
    {
      "name": "巨视报 (Macro-Uno)",
      "description": "一种近乎因果律的超感官知觉。莎拉能够看穿动植物乃至人类“死期将近”的征兆，其预测准确率接近100%。这种能力使她在战场上能规避致命风险，并对敌人的生命轨迹进行审判。"
    },
    {
      "name": "2公里打击范围",
      "description": "结合了箭术与风之加护的综合性战技。莎拉能够让原本受重力和风速影响严重的箭矢保持近乎直线或预设轨道飞行至2000米开外，威力丝毫不减。"
    }
  ],
  "relationships": {
    "远山金次": {
      "nature": "观测对象、契约目标、偶尔的合作者",
      "description": "莎拉曾在金次身上看到了死亡的预兆，并对此保持着近乎病态的持续观测。两人在多次冲突中建立了基于专业能力的相互认可。金次对她那种为了远大理想（消灭贫穷）而当杀手的矛盾心理感到难以评价，但认同其作为武力的可靠性。"
    },
    "卡茨·格拉斯": {
      "nature": "前同僚、雇主/委托关系",
      "description": "两人在“格雷纳达”与“眷属”阵营期间有过多次共同行动。作为组织内的尖端战力，她们在战术配合上极具默契，尽管性格差异巨大。"
    },
    "蕾姬": {
      "nature": "镜像般的同行、同校后辈（形式上）",
      "description": "两人同为无口系的顶级狙击手。虽然所用武器不同，但在性格特征和战斗时的冰冷心理素质上高度重合。曾受雇于同一雇主（贝瑞塔），共同负责监视金次的任务。"
    },
    "梅亚·罗马诺": {
      "nature": "阵营敌人、战术对手",
      "description": "在多次局部战役中，莎拉的远距离火力与梅亚的防御性术式发生过激烈碰撞。对于莎拉的箭，梅亚持有极高的警惕心。"
    }
  }
}

