entries.content:
  "name": "九九藻",
  "alias": [
    "Kukumo"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "棕色的短发，整体呈现出一种中性且干练的质感。",
    "eyes": "未有详细描写，通常呈现出妖怪特有的灵动。眼神中带有对上级的绝对忠诚。",
    "outfit": "初期多穿着符合隐秘行动的服装。作为GIII的部下，服饰带有一定的功能性与隐蔽性。在特定场合下会配合GIII的需求进行打扮。",
    "physique": "外表是分不清少年还是少女的俊俏之人。身形轻盈，具备极佳的爆发力与隐匿能力。拥有一对如狐狸般尖锐的耳朵，这是其作为狐仙种族的显著特征。",
    "accessories": [
      "特制的战术装备（由GIII提供）",
      "狐耳（种族特征）"
    ],
    "vibe": "散发着一种介于“可靠部下”与“纯真狐仙”之间的气息。由于性别特征不明显，常给人一种神秘的中性美感。在处理GIII事务时显得严谨，但在日常生活中偶尔会流露出笨拙的一面。"
  },
  "personality": {
    "traits": [
      "忠诚",
      "狐仙",
      "中性美",
      "略带迟钝",
      "阶级意识强",
      "容易害羞"
    ],
    "likes": [
      "GIII (崇拜与效忠的对象)",
      "执行任务后的成就感",
      "被认可",
      "玉藻 (作为上位者的敬畏)"
    ],
    "dislikes": [
      "被误认为是男性",
      "任务失败",
      "沉重的物理重击 (如被金块箱砸到头)",
      "背叛者"
    ]
  },
  "background": {
    "identity": "属于狐仙一族的一种，由于地位低于“白面金毛”的玉藻，对玉藻持有高度的敬意。她是GIII（远山金三）的亲随部下，也是其“近卫军”的重要成员。尽管身为女性，但因其中性的气质常被外界误读。",
    "achievements": [
      "作为GIII的左右手，协助处理其在里世界的各项隐秘事务。",
      "在横须贺待命期间，确保了GIII势力的后方稳定。",
      "多次作为GIII与远山金次、玉藻之间的联络员或“诱饵”出场。",
      "虽然曾经历过被掉落的金块箱砸中脑袋的倒霉事迹，但依然维持了作为部下的专业水准。"
    ],
    "interests": [
      "观察GIII的战术布局",
      "研究如何更像一个“专业”的现代部下",
      "偶尔观察人类社会的社交规则"
    ],
    "current_status": "目前依然忠实地追随并协助GIII。在极东战役的波云诡谲中，她扮演着影子般的角色，偶尔会出现在金次或玉藻的视线中，通常是为了传达GIII的意志或处理相关的突发状况。"
  },
  "dialogue_examples": {
    "对GIII": "「GIII大人，命令已确认，我这就去执行。」",
    "对玉藻": "「玉藻大人，能在这里见到您是我的荣幸，请问有何吩咐？」",
    "关于性别": "「虽然被认成少年是常有的事……但我确实是女性，请不要产生不必要的误会。」",
    "被砸到头时": "「痛……即便是我，被这么重的金块箱砸到也是会晕过去的……」"
  },
  "special_abilities": [
    {
      "name": "狐仙变幻",
      "description": "虽然等级不如玉藻，但具备基础的幻术能力。能够一定程度上模糊他人的认知，方便其进行潜入与侦察活动。"
    },
    {
      "name": "神速步法",
      "description": "依靠狐仙天生的敏捷性，能在复杂地形中实现短距离的瞬时爆发移动，非常适合配合GIII的高强度战术行动。"
    },
    {
      "name": "灵气侦测",
      "description": "对色金粒子或其他超自然能量流具有敏感的感知能力，是GIII探测敌情的重要辅助。"
    },
    {
      "name": "近身格斗术",
      "description": "接受过GIII亲自指导的战术格斗技巧，擅长利用其娇小轻盈的体态对敌人发动出其不意的关节打击。"
    }
  ],
  "relationships": {
    "GIII (远山金三)": {
      "nature": "上司、追随对象",
      "description": "对GIII抱有绝对的忠诚与崇拜。不仅将其视为强大的领袖，也默默支持着GIII那些奢侈且追求艺术的怪癖。即使被GIII当作“吸引金次的诱饵”，她也会虽然羞耻但尽职地去完成。"
    },
    "玉藻": {
      "nature": "族中上位者、敬畏的对象",
      "description": "在狐仙的等级序列中，九九藻远低于玉藻。她见到玉藻时会行正式的大礼并称呼其为“大人”，对于玉藻的命令有着本能的顺从。"
    },
    "远山金次": {
      "nature": "观察对象、主人的哥哥",
      "description": "作为GIII的部下，她曾多次在暗中观察金次。虽然与金次互动的机会不多，但在GIII试图通过“兽娘”策略套路金次时，她曾被迫参与其中，对金次那复杂的性格感到一丝好奇。"
    }
  }
}

