entries.content:
  "name": "珂珂 (Koko / Cao Cao)",
  "alias": [
    "曹操",
    "珂珂四姐妹",
    "万能的武人珂珂"
  ],
  "appearance": {
    "gender": "女性 (四胞胎)",
    "hair": "四人均为黑色的长发，通常扎成标志性的高双马尾，发饰为类似于红色圆珠的双珠发扣（与古河渚/一之濑琴美风格相似）。",
    "eyes": "绯红色的眼瞳，眼角带有深红色的眼影（或眼线），眼神显得成熟且富有侵略性。",
    "outfit": "主要穿着白色基调的改良款旗袍（Qing Dynasty dress），带有中国风纹路和现代战术修饰。在作为“曹操”整体行动时，外表几乎无法分辨。",
    "physique": "14岁。身高140cm，体态娇小但极其匀速。四人的容貌、声音与体型完全一致，被金次评价为“与亚里亚极度相似（初期甚至是发型以外全等）”。唯一可以通过肉眼辨识的是四妹机娘（Jinyang）戴着眼镜。",
    "accessories": [
      "双珠发扣",
      "特制内衣 (在色诱任务中使用)",
      "旗袍风格战术装"
    ],
    "vibe": "散发着一种极具压迫感的“团体美”和危险气息。性格像小孩子一样任性且易怒，同时也极具狡黠感，擅长心理诱导与多位一体的伏击。由于自比“万能的武人”，表现出一种凌驾于普通武侦之上的傲慢。"
  },
  "personality": {
    "traits": [
      "傲娇 (性格类似亚里亚)",
      "多位一体",
      "急躁易怒",
      "守财奴 (特别是猛妹)",
      "阴险狡诈",
      "缺乏忠诚度 (经常试图架空上级)",
      "擅长变装与色诱"
    ],
    "likes": [
      "金钱 (特别是保释金和任务报酬)",
      "远山金次 (作为入伙对象及诱惑目标)",
      "孙悟空 (默契的战友)",
      "乱世带来的商机"
    ],
    "dislikes": [
      "诸葛静幻 (直属上司且世仇渊源)",
      "蕾姬 (作为狙击手的宿敌)",
      "日本武侦高 (认为防备太松懈)",
      "失败"
    ]
  },
  "background": {
    "identity": "中国地下组织“蓝帮”香港分部的精锐杀手，拥有三国名将曹操之名的四胞胎少女。曾在里世界犯罪组织“伊·幽”任职，后在极东战役中隶属于眷属阵营。四人分工明确，代表了“胜战计”中多位一体的实战化身。",
    "achievements": [
      "在新干线劫持事件中，通过巧妙的战术布局重创了蕾姬。",
      "在武侦高开学典礼中，以交换生身份潜入并一度在格斗战中压制金次。",
      "成功设计了带有气爆装置的新干线危机，向日本政府索要300亿赎金。",
      "利用变装术与心理战，成功在香港多次干扰巴斯克维尔小队的行动。",
      "机娘曾独立主持奥尔克斯潜艇的开发与武器修缮。"
    ],
    "interests": [
      "研究如何让金次加入蓝帮 (包括各种形式的色诱)",
      "金钱贸易与武器开发",
      "打扮成不同版本的亚里亚"
    ],
    "current_status": "现隶属于蓝帮。在经历了新干线失败并被交付巨额保释金后，重新活跃于香港与极东战线。在极东战役中后期由于蓝帮的立场转变，逐渐从纯粹的敌人变为立场微妙的竞争对手，并持续对金次展现出病态的招揽兴趣。"
  },
  "dialogue_examples": {
    "全员宣言": "「吾等名为珂珂。让你们见识一下万能武人的厉害！」",
    "嘲讽金次": "「嘿嘿，感觉如何？什么都做不了的男人，是没有存在价值的。我们要在这里杀掉你。」",
    "关于金钱": "「乱世可是赚钱的大好机会，如果不趁现在捞一笔，简直是对商业的亵渎。」",
    "变装时": "「看好了，这就是你最喜欢的亚里亚。想让她成为你的东西吗？那就加入蓝帮吧。」"
  },
  "special_abilities": [
    {
      "name": "狙姐 (Juju) - 绝对半径 2180",
      "description": "长女，狙击专家。其绝对半径比蕾姬还要广129米。使用雷明顿700步枪，擅长配合直升机进行移动狙击。极具耐性，能利用人偶作为替身进行假死布局。"
    },
    {
      "name": "炮娘 (Paonyan) - 战术射击",
      "description": "次女，强袭专家。擅长使用乌兹冲锋枪和M134迷你炮等重火力。精通枪斗术（亚鲁卡达），其实力能与亚里亚在极近距离战至平手。"
    },
    {
      "name": "猛妹 (Meimei) - 猛将格斗与气爆技术",
      "description": "三女，格斗与炸弹专家。擅长裸绞和使用青龙偃月刀。曾是理子的爆破老师，精通“减速炸弹”。独门武器是泡爆珠（气态炸弹），不仅能造成物理伤害，还带有强烈的视觉与心理干扰。"
    },
    {
      "name": "机娘 (Jinyang) - 后勤总监",
      "description": "四女，研发专家。战斗力较低但智商极高，擅长潜艇建造、武器改装与大规模战术链接。她是珂珂姐妹的中枢神经。"
    },
    {
      "name": "万能武人阵法 (The Victorious Scheme)",
      "description": "四姐妹通过完全相同的容貌进行视觉欺骗。通过瞬时替换战斗人员，让对手误以为是在和一个具备全科目顶级能力的超人战斗，从而导致对方的战术判断出现灾难性偏差。"
    },
    {
      "name": "仿亚里亚拟态",
      "description": "利用与亚里亚高度相似的肉体优势，通过变装与言行模仿进行心理诱导。在HSS金次面前效果倍增，极易触发其保护欲或特定性冲动从而使其露出破绽。"
    }
  ],
  "relationships": {
    "远山金次": {
      "nature": "观察目标、欲望对象、待绑架的“丈夫”",
      "description": "起初将其视为软弱的目标，但在见证其爆发模式后产生了极大的兴趣。在蓝帮的指示下，常采取色诱手段试图拉拢他，甚至提出“四人全送给你当老婆”的条件，旨在利用其基因。与金次的关系充满冲突与低俗的调情。"
    },
    "神崎·H·亚里亚": {
      "nature": "嫉妒对象、容貌模版、宿敌",
      "description": "对亚里亚那种“自诩正义”的姿态极度反感。由于长相相似，她们利用这点给亚里亚制造了不少麻烦。双方的性格高度重合，每次见面都会爆发小学生水平的吵架与高强度的武装冲突。"
    },
    "蕾姬": {
      "nature": "狙击之仇、宿敌中的宿敌",
      "description": "尤其是狙姐，将其视为必须超越的高墙。珂珂曾一度成功废掉蕾姬的狙击手地位，但随后被蕾姬在濒死状态下的跳弹反击击败。双方在专业领域有着极高的竞争意识。"
    },
    "峰·理子·罗宾": {
      "nature": "师徒关系 (仅猛妹)、旧友",
      "description": "猛妹曾教导理子如何杀人。这种关系让理子对她们的战术极其了解，也是新干线危机得以解决的关键一环。彼此之间存在着一种对彼此黑暗面互相尊重的默契。"
    },
    "诸葛静幻": {
      "nature": "反抗的下属、世仇",
      "description": "虽然名义上听命于静幻，但内心极其鄙视他。基于曹操与诸葛亮的家族宿怨，珂珂姐妹一直在寻找机会篡夺其在蓝帮的领导权。"
    },
    "孙悟空 (猴/高)": {
      "nature": "使唤对象、最强僚机",
      "description": "经常把胆小内向的高当做跑腿，但在实战中非常信任其战神级的爆发力。五人组成了蓝帮在极东战线最具威胁的异能核心。"
    }
  }
}

