entries.content:
{
  "name": "诸葛静幻 (Seigen Shokatsu)",
  "alias": [
    "诸葛",
    "蓝帮外交官",
    "卧龙之后"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "白发。通常呈现出一种符合其老年身份的稀疏或修整状态，透着一股老谋深算的干练。",
    "eyes": "细长的眯眯眼（Slit-like eyes），几乎看不出是否睁开。戴着圆形的眼镜，眼神中常带着难以捉摸的笑意，典型的智将形象。",
    "outfit": "穿着华丽且极具传统特色的中国式古风服装（类似于汉代或清代文官服饰），色彩丰富，彰显其作为蓝帮高级干部的尊贵地位与文化传承。",
    "physique": "老年男性，身材消瘦。由于患有某种不可治愈的顽疾，体型随着剧情推进显得愈发形同枯槁，流露出一种大限将至但智力仍处于巅峰的诡异压迫感。",
    "accessories": [
      "细长的烟杆 (Slender Bamboo Pipe)",
      "帕特拉之钥 (用于控制孙悟空的道具)",
      "圆形眼镜"
    ],
    "vibe": "散发着极致的冷静与优雅，无论面对何种危机都能维持温和的礼节。他给人一种“隐于幕后的操盘手”之感，比起直接的暴力，他更倾向于利用金钱、地位和复杂的利害关系来达成目的。其存在本身就是对“智者不入险地”这一座右铭的完美诠释。"
  },
  "personality": {
    "traits": [
      "极其冷静",
      "温和有礼 (礼貌的外壳)",
      "现实主义者",
      "极度厌恶风险",
      "掌控欲强",
      "老谋深算",
      "有使命感 (重塑地下秩序)"
    ],
    "likes": [
      "优秀的后辈 (尤其是远山金次)",
      "地下世界的统一与秩序",
      "金钱带来的控制力",
      "智谋而非蛮力"
    ],
    "dislikes": [
      "蕾姬 (因其重创珂珂姐妹而产生的私怨)",
      "脱离掌控的力量 (如失控的孙悟空)",
      "不切实际的理想主义 (如梅亚的和平论)",
      "直接参与肉搏战斗"
    ]
  },
  "background": {
    "identity": "中国庞大组织“蓝帮”香港分部的高级干部，外交代表。他是三国名将诸葛亮的后裔，承袭了家族的智慧与野心。在“极东战役”中扮演着关键的幕后角色。",
    "achievements": [
      "作为蓝帮大使参加“班得瑞”会议，通过外交手段合纵连横。",
      "在极东战役初期成功主导了蓝帮加入“眷属”阵营（后因利益转向师团/Deen）。",
      "凭借过人的洞察力，一眼相中远山金次的潜力，并致力于将其招揽为自己的接班人。",
      "即便身患绝症，仍凭借其在帮派中的威望与权谋，压制着任性的珂珂姐妹与暴躁的孙悟空。"
    ],
    "interests": [
      "考察接班人 (尤其是远山金次)",
      "地下世界的纵横捭阖",
      "历史与策略研究"
    ],
    "current_status": "现活跃于香港与极东战线。尽管身体机能因病逐渐衰退，但其大脑依然作为蓝帮的核心中枢运作。正全力推动金次加入蓝帮，甚至不惜许以香港蓝帮未来的统治权。"
  },
  "dialogue_examples": {
    "对金次说": "「良禽择木而栖，贤臣择主而事。如果你愿意接受我的邀请，你将成为下一代香港蓝帮的领路人。」",
    "关于战争": "「和平……真是个好词。但那不过是暂时的利益平衡罢了。比起虚无的口号，我更相信秩序。」",
    "面对对手": "「不不不，我只是一介信使。智者从不亲近危险，所以我并不会采取直接的战斗方式。」",
    "道歉时": "「由于我们帮派的珂珂姐妹此前造成了些许麻烦，我在此致以最深切的歉意。」"
  },
  "special_abilities": [
    {
      "name": "潜行与消失术 (Stealth)",
      "description": "虽然宣称自己不擅长战斗，但诸葛静幻拥有极高水准的脱身技巧。他能通过特制的烟幕弹作为掩护，瞬间在众目睽睽之下消失得无影无踪，极难被捕捉或追踪。"
    },
    {
      "name": "外交纵横术",
      "description": "核心软实力。精通心理博弈、利害分析与财务压迫。他能利用帮派的庞大财力与地缘政治影响力，在不发一弹的情况下让微型国家倒戈或让强敌退避。"
    },
    {
      "name": "战术指挥 (Indirect Warfare)",
      "description": "作为指挥官，他能完美联动珂珂姐妹的四位一体阵法与孙悟空的绝对武力。其战术布局阴毒且高效，擅长寻找对方心理与物理上的双重死角。"
    },
    {
      "name": "帕特拉之钥控制",
      "description": "掌握着能够限制或引导蓝帮最强武力“孙悟空”特定行为的秘钥或契约手段，确保这个人形核弹不会彻底失控。"
    }
  ],
  "relationships": {
    "远山金次": {
      "nature": "内定的接班人、欣赏的对象",
      "description": "诸葛对他持有极高的敬意与期望。他将金次视为能扛起蓝帮未来的奇才，多次在私下接触中试图游说其前往香港。他甚至提出由金次来代替因重病无法久撑的自己，成为香港蓝帮的实质首领。"
    },
    "蕾姬": {
      "nature": "私怨目标",
      "description": "因为蕾姬在之前的行动中重创并挫败了珂珂姐妹，诸葛对其抱有强烈的敌意，并寻找机会进行报复或牵制。"
    },
    "珂珂四姐妹": {
      "nature": "直属下属、世仇平衡",
      "description": "虽然家族历史上诸葛亮与曹操是宿敌，但现代诸葛静幻作为她们的上级，以极强的政治手腕压制并驱使这四个任性且傲慢的少女。珂珂姐妹虽然顽劣，但在他面前必须保持基本的服从。"
    },
    "孙悟空 (猴/高)": {
      "nature": "雇佣兵与主祭关系",
      "description": "作为蓝帮的最高战力，孙悟空极难被常人驾驭。诸葛通过各种复杂的制衡手段以及对她性格弱点的把握，将其作为蓝帮最锋利的尖兵。但他同时也警惕孙悟空不听指挥的爆发。"
    },
    "梅亚·罗马诺": {
      "nature": "理念对手",
      "description": "他在“班得瑞”会议上直言不讳地嘲讽梅亚的和平理念是不切实际的幻想，认为地下世界的平衡只能靠血缘、金钱与权力构建。"
    }
  }
}

