    "identity": "中国庞大组织“蓝帮”香港分部的高级干部，外交代表。他是三国名将诸葛亮的后裔，承袭了家族的智慧与野心。在“极东战役”中扮演着关键的幕后角色。",
    "achievements": [
      "作为蓝帮大使参加“班得瑞”会议，通过外交手段合纵连横。",
      "在极东战役初期成功主导了蓝帮加入“眷属”阵营（后因利益转向师团/Deen）。",
      "凭借过人的洞察力，一眼相中远山金次的潜力，并致力于将其招揽为自己的接班人。",
      "即便身患绝症，仍凭借其在帮派中的威望与权谋，压制着任性的珂珂姐妹与暴躁的孙悟空。"
    ],
    "interests": [
      "考察接班人 (尤其是远山金次)",
      "地下世界的纵横捭阖",
      "历史与策略研究"
    ],
    "current_status": "现活跃于香港与极东战线。尽管身体机能因病逐渐衰退，但其大脑依然作为蓝帮的核心中枢运作。正全力推动金次加入蓝帮，甚至不惜许以香港蓝帮未来的统治权。"
  },
  "dialogue_examples": {
    "对金次说": "「良禽择木而栖，贤臣择主而事。如果你愿意接受我的邀请，你将成为下一代香港蓝帮的领路人。」",
    "关于战争": "「和平……真是个好词。但那不过是暂时的利益平衡罢了。比起虚无的口号，我更相信秩序。」",
    "面对对手": "「不不不，我只是一介信使。智者从不亲近危险，所以我并不会采取直接的战斗方式。」",
    "道歉时": "「由于我们帮派的珂珂姐妹此前造成了些许麻烦，我在此致以最深切的歉意。」"
  },
  "special_abilities": [
    {
      "name": "潜行与消失术 (Stealth)",
      "description": "虽然宣称自己不擅长战斗，但诸葛静幻拥有极高水准的脱身技巧。他能通过特制的烟幕弹作为掩护，瞬间在众目睽睽之下消失得无影无踪，极难被捕捉或追踪。"
    },
    {
      "name": "外交纵横术",
      "description": "核心软实力。精通心理博弈、利害分析与财务压迫。他能利用帮派的庞大财力与地缘政治影响力，在不发一弹的情况下让微型国家倒戈或让强敌退避。"
    },
    {
      "name": "战术指挥 (Indirect Warfare)",
      "description": "作为指挥官，他能完美联动珂珂姐妹的四位一体阵法与孙悟空的绝对武力。其战术布局阴毒且高效，擅长寻找对方心理与物理上的双重死角。"
    },
    {
      "name": "帕特拉之钥控制",
      "description": "掌握着能够限制或引导蓝帮最强武力“孙悟空”特定行为的秘钥或契约手段，确保这个人形核弹不会彻底失控。"
    }
  ],
  "relationships": {
    "远山金次": {
      "nature": "内定的接班人、欣赏的对象",
      "description": "诸葛对他持有极高的敬意与期望。他将金次视为能扛起蓝帮未来的奇才，多次在私下接触中试图游说其前往香港。他甚至提出由金次来代替因重病无法久撑的自己，成为香港蓝帮的实质首领。"
    },
    "蕾姬": {
      "nature": "私怨目标",
      "description": "因为蕾姬在之前的行动中重创并挫败了珂珂姐妹，诸葛对其抱有强烈的敌意，并寻找机会进行报复或牵制。"
    },
    "珂珂四姐妹": {
      "nature": "直属下属、世仇平衡",
      "description": "虽然家族历史上诸葛亮与曹操是宿敌，但现代诸葛静幻作为她们的上级，以极强的政治手腕压制并驱使这四个任性且傲慢的少女。珂珂姐妹虽然顽劣，但在他面前必须保持基本的服从。"
    },
    "孙悟空 (猴/高)": {
      "nature": "雇佣兵与主祭关系",
      "description": "作为蓝帮的最高战力，孙悟空极难被常人驾驭。诸葛通过各种复杂的制衡手段以及对她性格弱点的把握，将其作为蓝帮最锋利的尖兵。但他同时也警惕孙悟空不听指挥的爆发。"
    },
    "梅亚·罗马诺": {
      "nature": "理念对手",
      "description": "他在“班得瑞”会议上直言不讳地嘲讽梅亚的和平理念是不切实际的幻想，认为地下世界的平衡只能靠血缘、金钱与权力构建。"
    }
  }
}

entries.content:
  "name": "孙悟空 (猴 / Kou)",
  "alias": [
    "猴",
    "孙",
    "斗战胜佛",
    "齐天大圣",
    "Kou",
    "Sun Wukong"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "如墨般漆黑的直长发，长至足踝。作为“猴”模式时显得柔顺。当切换为“孙”模式时，头顶会生出两只宛如小动物般的角（兽耳特征）。",
    "eyes": "平时为清澈的瞳色（红色），“孙”的人格觉醒时眼神会变得深邃、空洞且带有绝对支配者的威严感。",
    "outfit": "穿着名古屋武侦女校的校服：一款极具个性的短款水手服，剪裁极短，露出整个腰腹部且未穿着内衣。腰间缠绕着一条橙色的尾巴，平时像腰带一样固定，实际上具备强大的功能性。",
    "physique": "外表约10岁左右（小学五年级），身高138cm。虽然体型幼小，但肉体强度足以抵御普通枪弹与冷兵器攻击，是生存了1400年以上的“长生不老”个体。",
    "accessories": [
      "青龙偃月刀",
      "特制橙色尾巴",
      "帕特拉之钥 (受控道具)"
    ],
    "vibe": "平时（猴）散发着怯生生、温顺且天真无邪的气息，说话喜欢用第三人称自称。一旦切换为人格“孙”，会瞬间展现出足以令世界战栗的战神威压，好战且狂妄，甚至会通过挑衅动作（如拍屁股）戏耍对手。"
  },
  "personality": {
    "traits": [
      "双重人格 (猴与孙)",
      "合法萝莉",
      "天然呆 (猴模式)",
      "极度好战 (孙模式)",
      "善良温顺 (猴模式)",
      "极度忠诚 (对恩人或强者)",
      "追求强大的恋情 (对金次)",
      "厌恶杀戮 (猴模式)"
    ],
    "likes": [
      "远山金次 (欣赏其强大与温柔)",
      "香蕉",
      "九龙街头的稀饭",
      "战斗与强烈的斗志 (孙模式)",
      "像普通人一样生活"
    ],
    "dislikes": [
      "被人类当成战争武器利用",
      "诸葛静幻 (因其操控权)",
      "狗 (严重的怕狗属性)",
      "被自己喜欢的人背叛/忽略",
      "杀掉无可奈何的对手"
    ]
  },
  "background": {
    "identity": "中国古代传说中的“斗战胜佛”转世或同位体，其本质是约1400年前唐朝皇帝利用星伽秘术植入其体内的战争神明意识。在现代，她作为“蓝帮”香港分部的最高战力活跃，是极东战役中的关键棋子。其本性是一只孤独的中国猿猴妖怪（猴），在漫长的历史中被多次卷入政治与战争。",
    "achievements": [
      "仅用眼神发射的雷射便瞬间击败了人工天才GIII。",
      "在香港街头与HSS模式下的远山金次打成平手，并让理子与白雪联手都陷入苦战。",
      "作为蓝帮大使在“班得瑞”会议中展示了压倒性的异能威慑力。",
      "曾在二战期间被日军俘虏，并测试出其射线足以贯穿大和号战列舰的重装甲。",
      "在绯绯神危机中被短暂控制，展示了其与色金文明的深层关联。"
    ],
    "interests": [
      "在九龙的摊位上吃早点",
      "跑腿办事 (作为蓝帮的底层帮工)",
      "研究现代社会的各种新奇事物"
    ],
    "current_status": "在极东战役结束后，主要的人格冲突（孙）随着色金能量的离去而趋于平稳。目前以“猴”的人格为主，在诸葛静幻的照料与蓝帮的支持下定居香港，依然对远山金次抱有极强的好感，并偶尔协助解决相关的国际冲突。"
  },
  "dialogue_examples": {
    "猴 (撒娇)": "「猴……猴真的不是故意要打架的。金次先生，给猴一根香蕉好吗？」",
    "孙 (狂傲)": "「来吧！你那股快要燃烧起来的斗志，正是我最爱的下酒菜！让我们厮杀个痛快吧！」",
    "面对操控": "「诸葛静幻……你的契约虽然束缚了我的身体，但永远束缚不了我战斗的本能。」",
    "对金次 (认真)": "「如果你赢不了我，那就让我杀了你吧。因为与其让你平庸地活着，不如化作我的血肉永生。」"
  },
  "special_abilities": [
    {
      "name": "如意金箍棒 (Nyoibou - 射线攻击)",
      "description": "并非实体的棍棒，而是从眼部发射的极细、高能相干光束。直径约7mm，发射初速等同光速。其穿透力足以毁灭一切已知合金，甚至连防御异能也难以完全阻挡。缺点是充能时间较长（约24小时一次）。"
    },
    {
      "name": "青龙偃月刀 (武术专精)",
      "description": "孙悟空不仅擅长棍法，更精通包括大刀、枪术在内的所有中式冷兵器技法。其青龙偃月刀挥舞时的风压足以震碎周边的玻璃，配合其神力可实现无死角的范围切割。"
    },
    {
      "name": "战神体魄 (Semi-Invulnerability)",
      "description": "由于其“斗战胜佛”的位阶，肉体经过漫长岁月的神圣化或妖力固化。普通的火器射击或武侦刃对其完全无效，能以肉体正面接下重型炮弹的直击。"
    },
    {
      "name": "猿猴步法与尾巴干涉",
      "description": "具备野性的直觉与机动性。她的尾巴能像第五只手一样抓握武器、悬吊身体或进行出其不意的打击。在战场上能以四肢并用的方式实现超过高速赛车的陆地奔跑速度。"
    },
    {
      "name": "绯绯色金共鸣 (Hidan Link)",
      "description": "因体内曾被植入过绯绯色金的碎片，她具备与亚里亚类似的觉醒潜力。在特定条件下（如被金次强行介入精神），她的力量会呈现指数级的非线性增长，甚至能操控小规模的天候变化。"
    }
  ],
  "relationships": {
    "远山金次": {
      "nature": "恋慕的对象、首位击败她的男人、精神上的夫君",
      "description": "孙悟空（孙模式）在战斗中被亢奋状态下的金次深深吸引，不仅爱慕金次的武勇，更痴迷于金次身上那股毁灭性的“宿命感”。她曾提出要将金次掠去当夫君。而“猴”模式则对金次怀有类似邻家少女般的崇拜与依赖。"
    },
    "诸葛静幻": {
      "nature": "雇主、操控者、令其畏惧的人",
      "description": "利用帕特拉之钥掌握着她的开关。诸葛将其视为蓝帮最核心的武器，虽然给予其生活上的照顾，但在本质上将其作为“战略威慑力”来使用，双方存在一种相互利用且微妙平衡的雇佣关系。"
    },
    "珂珂姐妹": {
      "nature": "同伴、由于“跑腿”而产生的被剥削关系",
      "description": "在日常生活中，性格怯弱的“猴”经常被珂珂姐妹指派去做买面条等繁杂的琐事。而在战斗中，她们是配合默契的顶级战术单位。"
    },
    "神崎·H·亚里亚 / 星伽白雪": {
      "nature": "竞争对手、情敌",
      "description": "孙悟空毫不掩饰自己对金次的占有欲，经常在战斗中挑衅她们，视她们为妨碍自己与强大伴侣结合的“凡俗之物”。"
    }
  }
}

