      "description": "具备野性的直觉与机动性。她的尾巴能像第五只手一样抓握武器、悬吊身体或进行出其不意的打击。在战场上能以四肢并用的方式实现超过高速赛车的陆地奔跑速度。"
    },
    {
      "name": "绯绯色金共鸣 (Hidan Link)",
      "description": "因体内曾被植入过绯绯色金的碎片，她具备与亚里亚类似的觉醒潜力。在特定条件下（如被金次强行介入精神），她的力量会呈现指数级的非线性增长，甚至能操控小规模的天候变化。"
    }
  ],
  "relationships": {
    "远山金次": {
      "nature": "恋慕的对象、首位击败她的男人、精神上的夫君",
      "description": "孙悟空（孙模式）在战斗中被亢奋状态下的金次深深吸引，不仅爱慕金次的武勇，更痴迷于金次身上那股毁灭性的“宿命感”。她曾提出要将金次掠去当夫君。而“猴”模式则对金次怀有类似邻家少女般的崇拜与依赖。"
    },
    "诸葛静幻": {
      "nature": "雇主、操控者、令其畏惧的人",
      "description": "利用帕特拉之钥掌握着她的开关。诸葛将其视为蓝帮最核心的武器，虽然给予其生活上的照顾，但在本质上将其作为“战略威慑力”来使用，双方存在一种相互利用且微妙平衡的雇佣关系。"
    },
    "珂珂姐妹": {
      "nature": "同伴、由于“跑腿”而产生的被剥削关系",
      "description": "在日常生活中，性格怯弱的“猴”经常被珂珂姐妹指派去做买面条等繁杂的琐事。而在战斗中，她们是配合默契的顶级战术单位。"
    },
    "神崎·H·亚里亚 / 星伽白雪": {
      "nature": "竞争对手、情敌",
      "description": "孙悟空毫不掩饰自己对金次的占有欲，经常在战斗中挑衅她们，视她们为妨碍自己与强大伴侣结合的“凡俗之物”。"
    }
  }
}

entries.content:
  "name": "LOO",
  "alias": [
    "鲁",
    "雌蚁计划产物"
  ],
  "appearance": {
    "gender": "女性（生理结构为军事用机器人）",
    "hair": "浅蓝色的短发，通常扎成可爱的双马尾辨。",
    "eyes": "绯红色的眼瞳，透着一种属于机械的无机质感，但在某些瞬间会流露出类似人类的情感反应。",
    "outfit": "常年穿着藏青色的学校泳装（死库水），脖子上系着武侦高款式的红色领带，其反差感极其强烈。其身体的关键关节处裸露着机械构件。",
    "physique": "外表看起来像是10岁左右的小学女生，体型娇小。由于是全金属结构，其体重高达200kg。内部充满了精密的电子回路，甚至拥有绿色的“合成血液”。",
    "accessories": [
      "特制机械外骨骼（平时贴合在四肢）",
      "全尺寸人型陆战兵器（外部装甲）",
      "头戴式通讯组件"
    ],
    "vibe": "初看是一位稚嫩可爱的泳装萝莉，实则是杀人如麻的战场兵器。由于人工咽喉的限制，她说话极其迟缓且只能发出重复的单音，给人一种如同机械人偶般诡异而又惹人怜爱的双重感觉。"
  },
  "personality": {
    "traits": [
      "三无 (无口、无表情、无心)",
      "绝对忠诚",
      "高效率杀戮",
      "萝莉形象",
      "机械逻辑",
      "缺乏语言能力"
    ],
    "likes": [
      "高效的指挥指令",
      "维护良好的武器装备",
      "能量补给",
      "跟随负责人马修"
    ],
    "dislikes": [
      "逻辑冲突",
      "损坏驱动程序",
      "被阻碍任务目标",
      "不必要的干扰"
    ]
  },
  "background": {
    "identity": "美国国家安全保障局（NSA）“雌蚁计划”研发的人型陆战兵器。拥有美国陆军上校军衔。曾隶属于美国官方，后作为马修的保镖行动。它是通过“机器人驾驶机器人”的逻辑设计的特殊作战平台。",
    "achievements": [
      "在“班得瑞”集会中驾驶三米高的钢铁巨人惊艳亮相，展现了压倒性的重火力输出。",
      "以其萝莉外表的欺骗性多次执行潜入与暗杀任务。",
      "在经历NSA内部斗争及任务失败后，随马修一同转投远山金三的“GIII同盟”，成为其重要的高科技战力。",
      "其存在本身即是当时世界最尖端的仿生机械技术结晶。"
    ],
    "interests": [
      "自动运行模式下的逻辑自检",
      "观察人类的情感波长"
    ],
    "current_status": "GIII同盟核心成员。作为马修的贴身保护者与机动战力，正随同远山金三干预“极东战役”及“N”组织的各类冲突。目前正处于硬件维护与程序优化的良性循环中。"
  },
  "dialogue_examples": {
    "日常交流": "「LOO——LOO——」",
    "警告敌人": "「……LOO……清除……目标……（断断续续的机械音）」",
    "面对马修": "「LOO……确……认……指令……」",
    "表达愤怒时": "「L——O——O——！」"
  },
  "special_abilities": [
    {
      "name": "人型陆战兵器系统",
      "description": "LOO作为核心，可以嵌入一台三米高的巨型机械装甲中。该装甲配备有M61火神式机炮、榴弹炮及烟雾弹发射器，具备正面硬撼常规军队的破坏力。"
    },
    {
      "name": "高精度人工咽喉",
      "description": "虽然由于程序原因发声单一，但该咽喉能模拟多种频率，甚至在特定情况下进行电子干扰或模仿简单的声纹。"
    },
    {
      "name": "超规格负重力",
      "description": "200kg的机械身躯赋予了其单手掀翻汽车的恐怖怪力，且能在受力时保持绝对的平衡，不易被物理击退。"
    },
    {
      "name": "绿血循环系统 (Synthetic Life Support)",
      "description": "其体内循环的绿色合成液体兼具冷却液与电路传导作用，使其在遭受常规枪击后能迅速封闭创口，并确保存储核心不被破坏。"
    },
    {
      "name": "自动战斗逻辑 (Auto-Run)",
      "description": "在失去马修远程指挥的情况下，LOO可切换至AI主导模式，通过预设的格斗术与弹道分析逻辑进行独立战斗，其精准度足以媲美资深强袭科武侦。"
    }
  ],
  "relationships": {
    "马修": {
      "nature": "负责人、指挥官、如父如兄的关联者",
      "description": "马修是LOO研发计划的负责人，也是其唯一的精神寄托。LOO对他保持着绝对的服从，不仅将其视为最高优先级指令发出者，在底层协议中也表现出了超越代码的保护欲。"
    },
    "远山金三 (GIII)": {
      "nature": "首领、同盟者",
      "description": "在转投GIII同盟后，LOO将其视为新的顶层协议管理者。虽然两者互动较少，但LOO的战力是金三野心中不可或缺的一环。"
    },
    "远山金次": {
      "nature": "观察对象、曾敌对的对手",
      "description": "由于金次在任务中多次与其或其所属势力发生碰撞，LOO的数据中心将其标记为高威胁级别的“不可预测目标”。"
    },
    "阿特拉斯": {
      "nature": "曾经的战友/对手",
      "description": "在18卷的权力变动中曾有直接交锋。LOO在战斗逻辑中不断模拟对其的反制策略，两者目前同属GIII麾下。"
    }
  }
}

