    "eyes": "深邃的褐色眼瞳，眼神冷冽、坚定，透着一种超越年龄的沧桑感与杀气。",
    "outfit": "标志性的黑色防弹风衣，内部穿着战术服，脚蹬一双耐磨的黑色长靴。其整体装束干练且极具压迫感。在特定桥段中曾被迫穿着远山金次提供的学校女式水手服。",
    "physique": "约25岁。身材高挑且结实，拥有长期特工生涯打磨出的精悍体魄。容貌被金次形容为“美丽到教人毛骨悚然”，散发着一种冷峻的、带有攻击性的美感。",
    "accessories": [
      "灰色戒指 (曾代表在N组织中的高层地位，后被降级为黑色)",
      "防弹风衣 (不仅是服装，也是防御性的战术装备)"
    ],
    "vibe": "给人一种冷酷、孤僻且极度危险的感觉。她像是一把随时可能出鞘的利刃，不仅由于其卓越的战力，更因为她那近乎病态的情感逻辑——将“杀戮”视为“爱”的终极表达方式。当她全神贯注于目标时，周围的空气仿佛都会凝固。"
  },
  "personality": {
    "traits": [
      "极度冷静",
      "孤独的狼",
      "情感逻辑扭曲 (爱=杀)",
      "社交障碍",
      "重情重义 (以自己的方式)",
      "执着",
      "不善言辞 (随能力提升更甚)",
      "家族荣誉感"
    ],
    "likes": [
      "远山金叉 (唯一爱慕的对象，尽管表达方式是杀掉他)",
      "弟弟伊藤可鹉韦 (作为家族血脉的羁绊)",
      "追求强者的决斗",
      "由于从未穿过而产生微妙兴趣的学校制服"
    ],
    "dislikes": [
      "弱者的纠缠",
      "家族中产生的污点",
      "谎言",
      "现代社交中的虚伪辞令"
    ]
  },
  "background": {
    "identity": "前日本公安0课“4式”成员，由于极端的战力与任务完成率而闻名。后脱离组织加入国际顶级恐怖组织“Nautilus (N)”，成为其核心执行力。她是伊藤家族的长女，也是远山金次名义上的杀父仇人。",
    "achievements": [
      "在公安0课时期便展现出顶级特工素质，熟练掌握多种暗杀与战术技巧。",
      "曾在过去的决斗中“击败”了远山金叉（实际上是对方单方面承受攻击后的假死）。",
      "劫持护卫舰“春雾”，企图利用核武威胁来清洗公安0课的高层。",
      "在“春雾”舰上以一敌三（金次、可鹉韦、静刃），展现出统治级的压制力。",
      "凭借对金叉行踪的独家情报，成功与宿敌远山金次达成跨阵营的临时同盟。"
    ],
    "interests": [
      "追踪远山金叉的每一丝踪迹",
      "磨练能在瞬间致命的指技",
      "收集并观察那些足以挑战自己的强者"
    ],
    "current_status": "在与远山金次分头前往美国寻找金叉后，最终与其所爱（金叉）展开了赌上性命的最终决斗。在战斗中遭受多方狙击身负重伤，随后坠入深谷。目前处于生死不明状态，但在武力与情感的双重博弈中，她似乎找到了某种自我解脱。"
  },
  "dialogue_examples": {
    "对远山金叉 (战时)": "「只有死亡能让两颗心彻底融合。金叉，请接受我这份……最后的爱意吧。」",
    "对远山金次 (冷淡)": "「你是他的血脉，但这并不代表我会对你手软。想知道你父亲的下落？那就用实力来换。」",
    "能力发动时": "「接入……深度……加速。我的手指……会停下……所有的子弹。」",
    "关于制服": "「这就是……所谓的学校吗？真是……多余的束缚。」"
  },
  "special_abilities": [
    {
      "name": "逐级提升能力 (Access)",
      "description": "茉斩独有的神经干涉异能。通过分级解锁大脑的限制器，实现神经信号传导的几何倍率加速。进入此状态后，她的身体机能、反应速度与动态视觉会提升至非人境界。然而，作为代价，大脑中负责语言表达的部分会受阻，使其说话变得破碎、断续。"
    },
    {
      "name": "箭指 (Arrow Finger)",
      "description": "窃取自远山金叉并在其基础上异化发展的杀人技。将全身的力量瞬间汇聚于食指尖端，通过极高速的弹击产生的动能冲击，甚至能够正面弹开飞行中的子弹，或在瞬间贯穿钢板。"
    },
    {
      "name": "特工战术全精通",
      "description": "作为前公安0课精英，具备顶级的潜入、格斗、狙击以及重型装备操控能力。她能将周围的一切环境化为致命的陷阱。"
    },
    {
      "name": "病态直觉",
      "description": "基于其扭曲的情感逻辑，茉斩对杀气与恶意有着如同野兽般的敏锐感应。这使她能够在复杂的混战中先发制人，避开致命的背刺。"
    }
  ],
  "relationships": {
    "远山金叉": {
      "nature": "爱慕对象、宿命之敌、渴望杀死的爱人",
      "description": "茉斩一生都笼罩在金叉的阴影与光芒下。她对金叉的爱已经由于极端的环境而转化为毁灭欲，认为唯有两人中一人死在另一人手上，才是感情的最完美结局。她是极少数知晓金叉并未真正死亡且身处美国的人之一。"
    },
    "远山金次": {
      "nature": "宿敌、临时盟友、作为观察对象的“其子”",
      "description": "金次长期视其为杀父仇人。两人在“春雾”舰上爆发过死斗，但随后基于寻找金叉的共同目的，建立了一段充满猜疑与博弈的临时合作关系。茉斩对金次表现出的某些与金叉相似的特质感到好奇。"
    },
    "伊藤可鹉韦": {
      "nature": "亲弟弟、家族的讨伐者",
      "description": "两姐弟同为特工天才，但茉斩选择了堕入黑暗（N），而可鹉韦则坚守正义。这种血亲间的敌对构成了她内心最后的一丝柔弱与挣扎。她理解可鹉韦想要亲手终结她罪孽的想法，并对此表示默认。"
    },
    "尼莫·林卡尔": {
      "nature": "组织同僚 (N)",
      "description": "同为N的高层。两人虽然在同一个组织，但由于茉斩孤僻且以个人情感驱动的行为模式，关系仅限于任务层面的最低限度接触。尼莫对茉斩这种因爱而疯狂的行为表现出知性上的不屑，却又认可其惊人的战力。"
    }
  }
}

entries.content:
  "name": "神崎香苗",
  "alias": [
    "香苗",
    "神崎太太"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "如深夜般深邃的长发，色泽在不同光线下呈现出黑紫色或深紫色。发丝如瀑布般垂至腰际，刘海自然地向右侧斜分，展现出温婉而成熟的气质。",
    "eyes": "深邃的棕色眼瞳，偶尔在特定光线下显现出淡淡的紫色，目光温柔而坚定，充满了包容力与母性的光辉。",
    "outfit": "初期长期穿着淡紫色的囚服（工作服款式），即使在狱中也保持着整洁与尊严。重获自由后，偏向于穿着典雅端庄的长裙或极具主妇气质的休闲服饰，散发着成熟女性的独特魅力。",
    "physique": "身高与成年女性相当，体态优美丰盈，拥有令亚里亚羡慕的成熟曲线。长年的铁窗生涯虽然让她的皮肤显得有些苍白，但并未磨灭她如大和抚子般的优雅感。",
    "accessories": [
      "特制项链（后期常戴）"
    ],
    "vibe": "外在表现为极度冷静、慈祥且带有一丝调皮性格的人妻形象。与女儿亚里亚那种烈火般的火暴性格截然不同，她像是静谧的深潭，温柔地包裹着女儿的脆弱与倔强。即使身陷冤狱，也从未失去对生活的希望与对家人的爱。"
  },
  "personality": {
    "traits": [
      "人妻",
      "温柔体贴",
      "冷静睿智",
      "顽皮的小恶魔性格（爱调侃亚里亚）",
      "坚毅不屈",
      "极度重视家族羁绊"
    ],
    "likes": [
      "女儿神崎·H·亚里亚",
      "调侃亚里亚与金次的关系",
      "红茶与精美的小点心",
      "家庭的宁静时光",
      "观察亚里亚的成长"
    ],
    "dislikes": [
      "亚里亚孤独一人战斗",
      "不公的命运（但并不怨天尤人）",
      "对自己家族血脉的恶意利用",
      "不解风情的迟钝男人"
    ]
  },
  "background": {
    "identity": "神崎·H·亚里亚的生母，英国著名侦探夏洛克·福尔摩斯的后裔家属。曾是备受尊敬的淑女，后被诬陷入狱。虽然在法律层面上是“重刑犯”，但在里世界中，她是掌握着色金核心机密的守护者。",
    "achievements": [
      "在被诬陷为“武侦杀手”并被判刑864年的绝境下，依然维持着清醒的理智与高尚的自尊。",
      "在长达数年的狱中生活中，通过精神交流引导亚里亚前往日本寻找属于自己的伙伴（华生）。",
      "面对日本政府与多方势力的审讯，守口如瓶地保守了有关“绯绯色金”的终极真相。",
      "在极东战役的关键节点，因绯绯色金引发的变故被判定为不再具备威胁，成功获释并与女儿重聚。",
      "在生活中成功撮合（助攻）亚里亚与远山金次的关系。"
    ],
    "interests": [
      "插花与茶道",
      "研习福尔摩斯家族的往事",
      "为未来的女婿（候选人）把关"
    ],
    "current_status": "目前已被释放，居住在亚里亚的宿舍房间内，扮演着亚里亚背后的情感支撑与恋爱军师角色。她依然受到政府的低度监视，但生活已步入正轨，享受着迟来的亲情时光。"
  },
  "dialogue_examples": {
    "对亚里亚（调侃）": "「哎呀，亚里亚~ 既然这位金次君是你带回来的，那我是不是可以开始考虑未来的婚礼邀请名单了呢？」",
    "对亚里亚（期许）": "「亚里亚，不要一个人战斗。你需要一位华生，一个能够理解你、支持你，并在你迷失时拉住你的人。」",
    "谈论冤狱": "「虽然在这里待了很久，但如果这些代价能换来真相被守护、你能平安长大，那么八百年的刑期也不过是弹指一挥间。」",
    "对远山金次": "「金次君，以后我们家那个不成器的孩子，就拜托你多多关照了哦（微笑）。」"
  },
  "special_abilities": [
    {
      "name": "超凡的心理博弈 (Psychological Game)",
      "description": "虽未表现出直接的战斗异能，但其洞察力极其敏锐。在长年的囚禁与审讯中，她能通过微妙的表情与语言反向操控审讯者的节奏，是顶级的心理战大师。"
    },
    {
      "name": "色金密语 (Irokane Secrecy)",
      "description": "作为神崎家的核心成员，她掌握着古老的传承知识。这种能力让她在面对色金粒子引发的精神干扰时，比普通人拥有更强的抵抗力与感知力。"
    },
    {
      "name": "淑女的武技传承",
      "description": "曾受过福尔摩斯家族的基础自卫术训练，虽然体力不如武侦，但在礼仪与战术素养上有着极高的理论功底。"
    }
  ],
  "relationships": {
    "神崎·H·亚里亚": {
      "nature": "母女、精神支柱、守护的对象",
      "description": "她视亚里亚为生命的延续，比亚里亚自己更了解其内心的脆弱。她一直推动亚里亚去寻找伙伴，以此来抵御福尔摩斯血脉中那股孤独且疯狂的宿命。她乐于看到亚里亚害羞吃醋的样子，这是她作为母亲的一种恶作剧式的关怀。"
    },
    "远山金次": {
      "nature": "女婿候选人、信赖的搭档、后辈",
      "description": "初次见面就察觉到了金次不同寻常的潜质（包括HSS带来的那种迷人气息）。她非常认可金次作为亚里亚“另一半”的地位，经常有意无意地制造两人独处的机会，对金次抱有一种慈祥且深具审视意味的关怀。"
    },
    "夏洛克·福尔摩斯三世": {
      "nature": "前夫（已离婚）",
      "description": "曾经的配偶，由于对方投身于伊·幽以及追寻色金的极端计划，导致了婚姻的破裂。尽管如此，她对这段过往仍持有一种理性的淡然。"
    },
    "峰·理子·罗宾": {
      "nature": "导致自己被陷害的真凶（之一）、需要原谅的后辈",
      "description": "虽然理子的行为导致她蒙受不白之冤，但在理子出庭作证后，香苗展现出了宽广的胸襟，将其视为一个被命运戏弄的孩子，并未抱有极度的怨恨。"
    }
  }
}

