    "eyes": "深邃而明亮的黑色瞳孔，透着一种星伽巫女特有的灵气。在害羞或愤怒时会显得非常有神。",
    "outfit": "初登场时穿着传统的白衣绯袴巫女服，背后背着印有星伽家五芒星家纹的包裹，手持红色油纸伞。在现代装扮时，则展现出对外界流行时尚的向往：层叠裙子、带有U型领的略显成熟的短袖夹克、短款背心，搭配大带扣的网状腰带与胸花凉鞋，展现出极大的反差感。",
    "physique": "14至15岁左右的初中生体型，身材纤细娇小，容貌与姐姐白雪十分相似，是一位充满古典气息的美少女。",
    "accessories": [
      "红色油纸伞",
      "带有星伽家纹的行李包",
      "短刀（用于护身或仪式）"
    ],
    "vibe": "外表看起来像是深闺中的大小姐或神圣不可侵犯的巫女，实则对现代社会充满了好奇。她拥有一种带着些许高傲的“傲娇”气质，对待男性极度排斥且保守，但面对美食和流行事物时会露出天真无邪的一面。因为从未接触过外界，表现出一种纯真的笨拙感。"
  },
  "personality": {
    "traits": [
      "傲娇",
      "厌男症 (对远山家除外)",
      "姐控",
      "保守（排斥不洁事物）",
      "对流行敏感",
      "纯真且好骗",
      "自尊心强"
    ],
    "likes": [
      "姐姐星伽白雪（极度依赖）",
      "各种圣代（尤其是像城堡一样的巨型圣代）",
      "购物与时尚装扮",
      "星伽神社的传统与荣耀",
      "被远山金次救援后的感激感"
    ],
    "dislikes": [
      "男性（特别是轻浮的男人）",
      "电视上的亲密场景（视为“不纯洁”、“污秽”）",
      "被人当成小孩子",
      "独自在不熟悉的地方迷路"
    ]
  },
  "background": {
    "identity": "星伽神社六姊妹中的次女，是白雪唯一同父异母的妹妹。星伽神社是极度禁绝男性的封闭领域，由于远山家与星伽家有着某种契约或因缘，远山家男性是唯一被允许进入神社的外人。",
    "achievements": [
      "作为星伽巫女，掌握了家传的“神道占卜”技术。",
      "在深夜独自溜出金次公寓体验东京生活，成功购买了大量心仪物品并品尝了高级圣代。",
      "在遭遇流氓围困时展现了宁死不屈的气节（虽然最后被金次解围）。",
      "在卷五末尾与武侦高众人共同参与了名为“武侦足球队”的非正规对抗，利用巫女的身法展现了独特的竞技能力。"
    ],
    "interests": [
      "现代流行时尚研究",
      "品尝各种甜点",
      "观察并学习“外面的世界”"
    ],
    "current_status": "目前居住在星伽神社，偶尔会因为姐姐白雪的缘故来到东京。在经历金次的营救事件后，虽然嘴上依然强硬，但内心已对金次及武侦这份职业产生了微妙的改观与敬意。她希望能像姐姐一样，未来也能有机会在武侦高生活。"
  },
  "dialogue_examples": {
    "对金次 (初见)": "「你是男人吗？既然是男人，就不准靠近我两步以内！退下，不洁之物！」",
    "看到电视亲吻镜头时": "「呀啊啊！不纯洁！这绝对是不纯洁的行为！这种电视节目应该立刻被禁播！」",
    "偷溜出门被金次发现后": "「我……我只是出来散步的！这、这些购物袋只是刚好顺路买的，才不是因为喜欢这里的东西呢！」",
    "表达对白雪的爱": "「只要能待在姐姐大人身边，无论在哪里，粉雪都是最幸福的。」"
  },
  "special_abilities": [
    {
      "name": "星伽巫女占卜 (Hotogi Miko Divination)",
      "description": "星伽一族秘传的占卜术，能够通过特定的仪式感应吉凶或预测事物的走向。粉雪在家族中属于该领域的佼佼者。"
    },
    {
      "name": "超常体能 (巫女步法)",
      "description": "虽非武侦，但从小在神社接受严酷修行，拥有远超常人的爆发力与灵活性。在足球赛中能轻易使出违反物理常识的移动和踢球技巧。"
    },
    {
      "name": "家传短刀术",
      "description": "熟练掌握用于神事与防身用的短刀技巧，能在近身作战中迅速反击。"
    }
  ],
  "relationships": {
    "星伽白雪": {
      "nature": "亲姐姐、憧憬的对象",
      "description": "粉雪是彻头彻尾的姐控。她将白雪视为完美的榜样，不仅在性格和打扮上模仿姐姐，更在姐姐决定离开神社时感到寂寞与不解。她是白雪在家族内最坚定的支持者。"
    },
    "远山金次": {
      "nature": "观察对象、潜在的好感对象（傲娇期）",
      "description": "最初因为金次的男性身份而极其嫌恶，甚至称其为“野蛮人”。但在金次暗中保护并从流氓手中救下她后，感受到了远山家男人独有的那种可靠与绅士风度，开始对其产生朦胧的好感，并在离去前向其展现了初次的笑容。"
    },
    "神崎·H·亚里亚": {
      "nature": "竞争对手（某种意义上的嫉妒）",
      "description": "对于一直待在金次身边的亚里亚抱有一种竞争心态，尤其不悦于亚里亚对“不纯洁关系”的迟钝，虽然两人性格相似，但初期相处并不融洽。"
    },
    "星伽四姊妹 (风雪、花雪、云雪、雾雪)": {
      "nature": "妹妹们",
      "description": "作为二姐，在白雪不在家时承担起照顾年幼妹妹们的责任。"
    }
  }
}

entries.content:
  "name": "间宫美铃",
  "alias": [
    "间宫宗家 (Mamiya Clan Matriarch)",
    "慈爱的鬼母",
    "Misuzu Mamiya"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "剪裁整齐、带着健康光泽的蜜金色短发，带有温婉的微卷，衬托出成熟女性的干练与柔美。",
    "eyes": "深邃而明亮的紫色瞳孔，透着间宫家特有的洞察力。在平日里充满了母性的光辉，但在进入战斗姿态时，眼神会变得如同冰冷的利刃。",
    "outfit": "在回忆与后期现身中，常穿着绣有间宫家纹的传统和服或便于行动的暗色作业服。其身材极大程度地撑开了衣物，显现出惊人的成熟美感。",
    "physique": "25-30岁左右（目测外表）。皮肤如雪般白皙细腻。拥有极其丰满且匀称的丰腴身材，尤其是那对硕大且极具存在感的乳房，被女儿们（以及读者）视为母性与家族生命力的象征。尽管身为人母，其腰肢依然纤细，肉体中蕴含着由于长期修炼暗杀术而磨炼出的恐怖爆发力。",
    "accessories": [],
    "vibe": "散发着一种极端矛盾的气场：既有大和抚子式的极致温柔与包容，又带有一种由于背负着黑暗暗杀术家族宿命而产生的森冷压迫感。她就像是一朵在深渊中绽放的紫色百合，美丽而致命。"
  },
  "personality": {
    "traits": [
      "绝对母性",
      "坚毅不拔",
      "严苛的导师",
      "隐忍",
      "巨乳",
      "传统的继承者",
      "潜伏者"
    ],
    "likes": [
      "女儿们（明里与乃乃香）的成长",
      "家族技艺的传承",
      "间宫家的宁静（昔日的时光）",
      "看着家人满足的吃相"
    ],
    "dislikes": [
      "伊·幽（IU）等破坏家族和平的势力",
      "杀人技被用于毫无正义的虐杀",
      "女儿们受到伤害",
      "弱小的意志"
    ]
  },
  "background": {
    "identity": "间宫一族嫡系的支柱，间宫明里与间宫乃乃香的生母。她曾是间宫家最顶尖的格斗家，负责将禁忌的暗杀术传授给后代。在“伊·幽”对间宫村发起的那场惨绝人寰的屠杀中，她为了掩护女儿们撤退而失踪，曾一度被认为已经死亡。",
    "achievements": [
      "在灭族危机中，凭借一人之力阻挡了多名具备异能的暗杀者，确保了明里与乃乃香的幸存。",
      "将原本作为屠杀工具的间宫流暗杀术，通过某种特殊的言传身教，将“守护”的种子植入明里的心中。",
      "在被认为死亡的岁月中，于阴影中默默观察并保护着女儿们的成长，其隐匿技术甚至瞒过了各国的谍报网。",
      "在AA故事的终章回归，重整残破的间宫村，重新确立了宗家的威严。"
    ],
    "interests": [
      "钻研武术中的“气”与“劲”",
      "烹饪传统家常菜",
      "收集并修复女儿们幼年时的遗物"
    ],
    "current_status": "确认幸存并活跃于间宫村。她不再是单纯的悲剧受害者，而是成为了引导明里从“武侦”进阶到“宗主”层面的终极导师。她与远山金叉一样，是那个支撑着下一代变强的、存在于地平线尽头的强大父母象征。"
  },
  "dialogue_examples": {
    "对明里（传授技艺时）": "「明里，看着我的手。所谓的鸢穿，不只是力量，而是感知空间在指尖崩裂的瞬间。」",
    "守护女儿时": "「只要我还在这里，谁也别想动这两个孩子一根汗毛……哪怕是地狱的使者也不行。」",
    "重逢时": "「长大了呢，明里。你已经找到了，属于你自己的‘不杀之刺’了吗？」",
    "面对敌人": "「间宫的血，并不代表邪恶。它代表的是……审判。」"
  },
  "special_abilities": [
    {
      "name": "极意·鸢穿 (True Tobi-Ugachi)",
      "description": "间宫流暗杀术的根基。美铃能将全身的动能集中在指尖的一点，通过特殊的物理振动瞬间贯穿目标的护甲。由于其自身惊人的体能加持，她施展的鸢穿具备一击摘取内脏或击碎重装甲的威力，其熟练度远非明里初登场时可比。"
    },
    {
      "name": "间宫流·全百招传承",
      "description": "作为宗家，她掌握了间宫流所有的禁术。不仅包括明里掌握的打击系，还涵盖了点穴、绞杀以及利用地形进行心理暗示的综合杀人术。"
    },
    {
      "name": "空间认知亢进",
      "description": "一种近乎超能力的知觉水平。她能同时处理视野内数十个目标的运动轨迹，预读所有弹道与敌人的肢体动向。这是她能在混战中保护女儿的关键。"
    },
    {
      "name": "母性的坚毅防御",
      "description": "即便在身体遭到重创的情况下，其精神力也能强制分泌内啡肽并封锁痛觉，使其能像机械般持续战斗，其耐打能力是明里那份天生体质的真正源头。"
    }
  ],
  "relationships": {
    "间宫明里": {
      "nature": "长女、理想的继承者",
      "description": "美铃对明里抱有极高的期望，同时也心存怜悯。她既希望明里继承家族的力量以自保，又不忍看她完全坠入杀手的黑暗。明里那柔中带刚的性格正是美铃遗传与教育的结晶。"
    },
    "间宫乃乃香": {
      "nature": "次子、受保护的对象",
      "description": "对于相对娇弱的乃乃香，美铃展现出了更多的柔情与呵护，是她心目中最需要宁静港湾的孩子。"
    },
    "间宫日里三姐妹 (日里, 希海, 儿玉)": {
      "nature": "侄女、分家的血脉",
      "description": "作为宗主，她统御着这些充满野心与个性的分家后代，引导她们回归间宫流的正确道路，并以宽广的胸怀容纳她们的无礼。"
    },
    "远山金叉": {
      "nature": "命运相似的同行者（假想性关联）",
      "description": "在宏观世界观中，两人皆是“死而复生”的父母辈代表，象征着两个战斗家族深不可测的底蕴。如果说金叉代表的是冷酷的法则，美铃则代表了那份为了血脉而不惜染满鲜血的慈悲。"
    }
  }
}

