entries.content:
 {
  "name": "间宫日里",
  "alias": [
    "日里",
    "间宫分家长女",
    "宵座的鹰",
    "Hikari Mamiya"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "剪裁凌乱、带有野性美感的黑色短发，头顶有一根极具辨识度的呆毛。",
    "eyes": "锐利的紫色瞳孔，透着间宫一族特有的洞察力，战斗时眼神如鹰隼般锐利。",
    "outfit": "穿着名古屋爱知女子武侦高中的标准水手服，但经过极端改造：上衣被剪短至胸部下方，露出了紧致的腹部。袖子也缩短了。这种极简的着装风格旨在减少由于流弹或勾扯带来的干扰，并以此彰显其极强的攻击性。在某些场合会身着极小面积的校园泳装。",
    "physique": "拥有经过严格锻炼的健美身材。皮肤呈现出健康的褐色（特意晒黑，为了在黄昏中获得‘暗度适应’伪装）。由于长期进行高强度的格斗训练，身体极具爆发力与柔韧性。身高略高于明里，显得更为成熟而危险。",
    "accessories": [
      "半笼手 (Han Kote)：右臂佩戴的武士金属护臂，用于防御刃物或增加打击力度。"
    ],
    "vibe": "散发着一种极端的侵略感与自信，如同在荒野中游走的幼狼。她兼具武家的威严与某种由于身处暗杀者边缘而产生的阴郁气质。与明里的治愈感相反，她是一种破坏性的美。"
  },
  "personality": {
    "traits": [
      "霸道强势",
      "极度渴望振兴家族",
      "好战",
      "护妹狂魔",
      "自尊心极强",
      "潜在的受虐属性（人格退化后）",
      "传统的叛逆者"
    ],
    "likes": [
      "妹妹希海和儿玉",
      "变得更强",
      "重建间宫家的辉煌",
      "看着明里（竞争对手）露出困扰的表情"
    ],
    "dislikes": [
      "间宫一族的衰落",
      "伊·幽（IU）等毁掉家园的人",
      "妥协与弱小",
      "失败带来的屈辱"
    ]
  },
  "background": {
    "identity": "间宫家分家（宵座）的长女，名古屋爱知女子武侦高中强袭科的学生。在间宫村惨案后与亲人失散并长期潜伏，因家族被灭而产生强烈的执念，试图通过夺取宗家的技艺或强行收纳明里来重组家族。",
    "achievements": [
      "在名古屋武侦高中凭借绝对武力成为顶尖的强袭生。",
      "自行领悟并强化了间宫流奥义，将其改良为杀伤力更强的个人战技。",
      "策划并执行了潜入东京武侦高中的‘猎狐行动’，一度压制了明里的伙伴。",
      "在与明里的最终决斗中虽败犹荣，成功达成了心境的转变。"
    ],
    "interests": [
      "修炼八极拳与间宫流暗杀术的融合",
      "观察并监视明里的动向",
      "通过日晒维持褐色皮肤"
    ],
    "current_status": "活跃于名古屋武侦界，虽然放弃了敌对姿态，但仍将明里视为一生的竞争对手，致力于建立属于自己的‘间宫帝国’。在性格退化事件后，与明里建立了一种微妙且带有‘撒娇’性质的深层纽带。"
  },
  "dialogue_examples": {
    "对明里": "「宗家的那些家伙就是太温柔了。真正的间宫流，应该是用来碾碎敌人的獠牙才对。」",
    "战斗宣言": "「间宫分家‘宵座’，间宫日里……要把你的一身傲骨给彻底震碎！」",
    "人格退化后": "「呜啊——明里姐姐，奶奶，要吸奶奶……呜……」",
    "失败时": "「胜者即是正义。既然我输了，我这幅残破的身躯就任你处置了……」"
  },
  "special_abilities": [
    {
      "name": "极意·强鹰卷 (Hyper Tobi-Ugachi)",
      "description": "间宫流奥义的改良版。通过自身极强的肉体素质和陀螺效应，爆发出的脉冲频率比标准版高出150%。中招者的防弹服和内脏会在瞬间被震散，威力足以击穿装甲车的厚度。"
    },
    {
      "name": "鹫抂 (Washi-Kyō)",
      "description": "间宫宵座秘传。通过指尖极速敲击，调整目标的颅内液体震动频率，强制使其中枢神经紊乱，退化为婴儿人格。这是一招旨在粉碎武士尊严的恶毒技术，但使用不当也会反噬自身。"
    },
    {
      "name": "铁山靠·改",
      "description": "结合了中国八极拳与间宫家发力方式的冲撞。利用背部肌肉瞬间爆发的压力，足以将持盾的重装警察撞飞，并附带持续性的内出血损伤。"
    },
    {
      "name": "黄昏伪装 (Tasogare Camouflage)",
      "description": "利用褐色皮肤与特定的黄昏光线达成近乎完美的隐形。她能在复杂的后巷中消失在阴影里，甚至干扰对手的空间感知系统。"
    }
  ],
  "relationships": {
    "间宫明里": {
      "nature": "竞争对手、堂姐、执念的对象、临时的‘代理母亲’",
      "description": "日里最初敌视明里，认为其‘软弱的武侦路’是在羞辱间宫家。然而在被明里的‘枭挫’击败并发生人格退化后，她对明里产生了极强的依赖感和占有欲。两人的关系在相杀与亲密间摇摆，明里是她唯一的心理救赎。"
    },
    "间宫希海 / 间宫儿玉": {
      "nature": "亲妹妹、最坚定的追随者",
      "description": "作为长姐，她对两个妹妹有着绝对的统御权与深厚的爱。她们三人是流浪岁月中互相依偎的唯一血缘，日里做出的所有极端决定很大程度上是为了给妹妹们一个‘家’。"
    },
    "武极昴": {
      "nature": "校友、合作者",
      "description": "同样来自于名古屋女高，虽然立场未必完全一致，但在某些颠覆性的行动中曾作为同一阵营的强力盟友。"
    },
    "神崎·H·亚里亚": {
      "nature": "敌对目标、值得尊敬的强者",
      "description": "由于明里追随亚里亚，日里起初试图斩断这份契约。在亲眼见证亚里亚的实力后，她将其视为武道的高峰之一，并渴望有一天能正面击溃亚里亚以证明分家的强大。"
    }
  }
}

