    "Nozomi Mamiya"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "留着一头极具蓬松感的蜜棕色长卷发，发丝柔顺地垂落在肩头，给人一种温婉却不失灵动的印象。",
    "eyes": "深邃的紫色瞳孔，鼻梁上架着一副极具知性美的圆形黑框眼镜，眼神中常带着一丝睿智与观察者的冷静。",
    "outfit": "主要穿着名古屋爱知女子武侦高中的标准水手服。与日里的激进改造不同，她的穿着相对规范，但在细节处透着由于身为间宫家成员而特有的干练。在执行特定任务时，会根据日里的指示换上各种极具诱惑性的伪装服饰（如极小面积的内衣或职业制服）。",
    "physique": "拥有非常标准且比例协调的武侦少女身材。虽然不像日里那样强调肌肉线条，但动作间流露出的敏捷性证明其受过严苛的间宫流暗杀术训练。胸部发育良好，甚至超过了身为长姐的日里，是小队中的“隐秘战力”。",
    "accessories": [
      "圆形黑框眼镜：她的标志性饰品，既是矫正视力的工具，也是其‘理性分析者’人格的视觉延伸。"
    ],
    "vibe": "给人一种知性、可靠的“智囊”感觉。在三姐妹中，她通常扮演协调者与策划者的角色。外表看似柔弱温和，实际上内心极度坚韧，对家族的忠诚度丝毫不亚于日里。拥有一种能让人放下戒心的‘亲和力毒药’气质。"
  },
  "personality": {
    "traits": [
      "重度妹控",
      "极度忠诚",
      "知性腹黑",
      "策划者",
      "执行力极强",
      "自我牺牲精神",
      "变装达人"
    ],
    "likes": [
      "姐姐日里和妹妹儿玉",
      "成功执行日里的计划",
      "收集情报",
      "看着志乃被自己玩弄于鼓掌之间",
      "甜食（尤其是作为奖励时）"
    ],
    "dislikes": [
      "间宫一族的屈辱史",
      "计划之外的突发变数",
      "伤害她姐妹的人",
      "背叛者"
    ]
  },
  "background": {
    "identity": "间宫分家（宵座）的次女，名古屋爱知女子武侦高中强袭科学生。与日里、儿玉一同经历了家族被灭的惨剧。作为‘宵座’三姐妹的枢纽，她负责将日里的野心转化为具体的可执行方案。",
    "achievements": [
      "策划了多次针对东京武侦高的潜入调查行动。",
      "在‘猎狐行动’中，通过惊人的变装演技和心理操控，在内衣店成功困住了极度警觉的佐佐木志乃。",
      "协助日里完善了‘宵座’特有的战斗协同战术，使三姐妹在合击时具备挑战S级武侦的实力。",
      "在名古屋危机后，成功协调了分家与宗家的初步停火协议。"
    ],
