    "间宫明里": {
      "nature": "堂姐、宗家继承人、嫉妒的对象",
      "description": "最初儿玉极度轻视明里，认为其“不杀之刺”是间宫家的耻辱。但在见识到明里的韧性后，产生了一种复杂的情感：既想通过武力粉碎这份温柔，又在内心深处渴望那份明里所拥有的、正常的家庭温暖。"
    },
    "佐佐木志乃": {
      "nature": "玩弄的目标、希海的玩具",
      "description": "儿玉经常协助希海戏弄志乃，嘲笑其对明里的过度占有欲。由于志乃是典型的名门大小姐，儿玉享受从精神上将其“蹂躏”至崩溃边缘的过程。"
    }
  }
