entries.content:
  "name": "霸美 (Habi)",
  "alias": [
    "哈比",
    "鬼",
    "Habi"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "棕色的短发，略显凌乱。发间别着一朵极具岛屿风情的鲜艳花朵（红色彼岸花）。",
    "eyes": "深棕色的眼瞳，在战斗兴奋时会流露出野兽般的本能光芒。",
    "outfit": "穿着传统的日式和服，但下摆剪裁较短，方便活动。腰间系有深色的宽腰带，整体装扮融合了部族色彩与东洋风格。",
    "physique": "外表看起来约10岁左右的小女孩，身高矮小。肤色较深（帕劳土著风格），额头上长有两只对称的小角（类似犀牛或长颈鹿的短角）。其肉体中蕴含着极高的密度与超乎想象的力量。",
    "accessories": [
      "重达300kg的特制金属战斧",
      "头饰鲜花"
    ],
    "vibe": "平时像个天真无邪、对外界充满好奇心的孩子。然而作为“鬼”的血脉，她散发着一种原始的威压感，战斗时会将残酷的破坏视作“幼儿园的游戏”，这种纯粹的危险感令人不寒而栗。"
  },
  "personality": {
    "traits": [
      "超力萝莉",
      "天真残忍",
      "非人生物 (鬼族)",
      "野性直觉",
      "赤子之心 (战斗狂)"
    ],
    "likes": [
      "玩耍 (特别是涉及力量的碰撞)",
      "强大的对手",
      "热带水果",
      "绯绯色金的共鸣感"
    ],
    "dislikes": [
      "无聊的会议",
      "被束缚",
      "弱小的猎物"
    ]
  },
  "background": {
    "identity": "帕劳“记国（Kinokuni）”鬼族一脉的代表。她是参与“极东战役（FEW）”的关键异能个体之一，作为“师团（Greneda）”阵营的一员活跃于国际舞台。由于体内植入了绯绯色金的碎片，她与神崎·H·亚里亚、孙悟空（猴）一样，具备与色金文明深层链接的潜质。",
    "achievements": [
      "作为鬼族代表出席“班得瑞”会议，并在纷争中选择了阵营。",
      "在激战中成功接收了从亚里亚体内提取出的部分“黄金壳（七星）”。",
      "仅凭单手就能挥舞300公斤的巨型战斧，其斩击能引发足以撼动岛屿的微型地震。",
      "在后期的战役中展现了惊人的野性机动性，四肢着地奔跑速度可比拟野兽。"
    ],
    "interests": [
      "测试人类强者的力量",
      "在热带森林中奔跑",
      "收集漂亮的装饰物"
    ],
    "current_status": "作为师团的重要战力，在南太平洋及周边地区活动。尽管外表年幼且心智孩童化，但已被列为世界级的危险异能者，正等待着与宿命中的对手展开最终的“游戏”。"
  },
  "dialogue_examples": {
    "日常": "「嘿嘿，大家坐在一起说话好无聊哦。有没有什么好玩的东西呀？」",
    "战斗开始": "「接下来是霸美的玩耍时间！要把你像坏掉的木头一样敲碎哦！」",
    "对阵强敌": "「哇！你的身体里有很好闻的声音在震动，就像亚里亚和猴一样！快来陪霸美玩吧！」",
    "威胁": "「如果不给霸美吃好吃的，就把这座岛整个翻过来哦。」"
  },
  "special_abilities": [
    {
      "name": "极意·鬼神怪力 (Super Strength)",
      "description": "天生具备的恐怖怪力。能够轻松挥舞重达300kg、体积远超自身的金属战斧。她的肌肉结构不同于常人，瞬间爆发力足以将钢筋混凝土构筑的工事彻底粉碎。"
    },
    {
      "name": "地鸣破 (Tremor Shock)",
      "description": "使用巨型战斧全力劈砍地面时，动能会转化为强烈的地震波。有效范围内不仅会产生地裂效果，其强震还能直接破坏敌方个体的平衡感，甚至震碎内脏。"
    },
    {
      "name": "四足兽步 (Animal Agility)",
      "description": "模仿野兽的运动模式。通过四肢并用的高速移动，实现在复杂丛林或城市废墟间的超常位移，其灵活性与反应力能轻易躲避密集的弹幕扫射。"
    },
    {
      "name": "绯绯色金共振 (Scarlet Resonance)",
      "description": "由于体内持有色金碎片，其感官能捕捉到同类宿主的信号。在情绪高涨时，这种共振会强化她的防御力，使其皮肤硬度足以抵御大口径子弹的直击。"
    }
  ],
  "relationships": {
    "远山金次": {
      "nature": "观察的对象、觉得有趣的人类",
      "description": "金次是首个对她的外貌及力量做出冷静分析的男性。霸美对他身上若隐若现的强者气息和HSS模式下的特异波动感到好奇，将其视为“好玩的玩伴”。"
    },
    "神崎·H·亚里亚": {
      "nature": "同类宿主、竞争对手",
      "description": "因为双方体内都拥有色金及其相关的“黄金壳”力量，存在一种本能的感应。霸美对亚里亚那种不服输的斗志表现出像小孩子对待心爱玩具般的执着。"
    },
    "孙悟空 (Kou)": {
      "nature": "宿命的联系、非人同类",
      "description": "同为身形幼小却拥有毁灭性战力的非人生物（猴与鬼），在某种程度上存在共鸣。双方在战场上的遭遇往往会演变为一场灾难性的力量较量。"
    },
    "希尔达": {
      "nature": "暂时的协助者、敌对势力代表",
      "description": "在班得瑞会议后的乱局中，曾因希尔达展示的力量及获取黄金壳的过程而与其产生交集。霸美对其持戒备态度，但也乐于参与对方制造的混乱。"
    }
  }
}

