entries.content:
{
  "name": "瓦尔基丽雅 (Valkyria)",
  "alias": [
    "瓦尔基里",
    "瓦尔武者",
    "战乙女",
    "Vu~arukyuria"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "银白色的长发，带有神圣而不可侵犯的质感。",
    "eyes": "澄澈的冰蓝色瞳孔，蕴含着看穿本质的威严。",
    "outfit": "穿着带有北欧神话风格的战斗铠甲，主要由银色金属与白色的特殊布料组成。作为其标志，她佩戴着一顶华丽的战盔，头盔上点缀着象征羽翼的装饰。在被金次脱去头盔后，其装束在战斗中常伴随神圣的光辉。",
    "physique": "拥有极其匀称且充满力量感的完美体态，身高约170cm以上，散发出超乎凡人的神性美感。皮肤白皙，由于是纯血的瓦尔基丽雅族，全身散发着冰冷而纯净的以太气息。",
    "accessories": [
      "银枪 - 特制的单手或长柄银色战矛",
      "银色戒指 - 象征“N”组织成员（白金级别）的契约物",
      "瓦尔基里战盔"
    ],
    "vibe": "神圣、高冷且充满武人的威压感。她不像是生活在现代社会的生物，而更像是从古代神话画卷中直接走出来的武神。由于其族群特有的“贞洁”观念，她带有一种拒人于千里之外的孤独感，但在被金次击败并揭开面具后，这种冰冷的气息中混杂了一丝少女特有的动摇与迷茫。"
  },
  "personality": {
    "traits": [
      "自傲而忠诚",
      "恪守诫律",
      "武人风骨",
      "纯情（因族规而起）",
      "对强者持有敬意",
      "神族自尊"
    ],
    "likes": [
      "高尚的战斗",
      "清澈的泉水",
      "履行誓言",
      "驱使幻兽（如哈比与飞龙）"
    ],
    "dislikes": [
      "卑鄙的手段",
      "面具/头盔被摘下",
      "无法控制的混乱",
      "不成熟的男人"
    ]
  },
  "background": {
    "identity": "古老瓦尔基丽雅族的现存后裔，不仅是其个人的名字，也是种族的名字。原为“N”组织的白金级成员，致力于莫里亚蒂教授的“第三次接轨”。在加入“N”之前，曾凭借绝对武力在罗马超自然界维持着“犬猿之仲”般的恐怖平衡。被远山金次击败后，现隶属于公安7课。",
    "achievements": [
      "曾独立调解并平定了梅亚（修女）与卡茨（咒术师）之间的长期武装冲突。",
      "在罗马斗兽场的一战中，展现了能够驾驭空间与召唤幻兽的压倒性力量。",
      "被远山金次利用新必杀技“铁风”击落头盔，触发了种族“杀或爱”的终极诫律。",
