{
  "name": "恩蒂蜜拉 (Endimira)",
  "alias": [
    "苍穹的密使 (Etranger)",
    "小恩",
    "Endimira",
    "エンディミラ"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "如瀑布般垂至膝盖的长发，发色为璀璨的金色。左侧头发编有一小段精致的辫子，并以丝带固定。",
    "eyes": "澄澈的蓝色瞳孔，犹如异世界的蓝宝石。",
    "outfit": "通常穿着干练且修身的女性西装。由于身份特殊，她在公共场合会将长发拨至耳前，巧妙地遮住标志性的尖耳朵，以融入人类社会。",
    "physique": "身高出众（在女性中属于高挑身材），外貌年龄约15-16岁。拥有白皙细腻的皮肤和极其傲人的胸部曲线，其超规格的丰满感与纤细的腰肢形成了强烈的视觉冲击，是标准的精灵族美少女。",
    "accessories": [
      "毛瑟 C96 (Mauser C96)",
      "复合长弓与箭筒",
      "发带"
    ],
    "vibe": "散发着一种出尘的、神圣且高雅的气息。即便穿着现代西装，也无法完全掩盖其作为长生种的尊贵感。由于对现代常识的匮乏，有时会露出一种惹人怜爱的呆萌表情，充满了由于“异文化碰撞”产生的反差感。"
  },
  "personality": {
    "traits": [
      "天然呆",
      "优雅",
      "忠诚",
      "恪尽职守",
      "善良且富有正义感",
      "缺乏常识",
      "知性美"
    ],
    "likes": [
      "远山金次 (其守护并追随的对象)",
      "荞麦面 (Soba Noodles)",
      "动物 (尤其是马)",
      "大自然",
      "遵守诺言"
    ],
    "dislikes": [
      "肉食 (由于精灵族习俗为素食主义者)",
      "游泳 (旱鸭子)",
      "资本主义的复杂规则",
      "欺凌弱小",
      "不必要的流血"
    ]
  },
  "background": {
    "identity": "来自“另一侧”世界（莱克忒亚）的精灵族。最初作为“N”组织的基层成员，协助尼莫执行回收任务。后受远山金次之母远山雪的指引/委托，成为远山金次身边的“密使”与随从。",
    "achievements": [
      "在南太平洋孤岛上成功营救并接回了迷失的尼莫与金次。",
      "在协助金次完成美国任务后，遵照遗嘱/指引开始正式追随金次，并在日常生活中给予其极大的战力与精神支持。",
      "凭借其超自然的直觉，在人类社会的各类竞赛中（如赛马）展现出了预知级别的准确率。",
      "作为金次身边的“跨界”纽带，逐渐在师团与眷属的夹缝中确立了自己的独特地位。"
    ],
    "interests": [
      "研究人类社会的社会构成 (试图理解资本主义)",
      "观察赛马的情况",
      "学习烹饪素食料理"
    ],
    "current_status": "目前作为金次的贴身保镖与“家眷”活动。由于其出色的外貌与单纯的性格，常常引发金次身边女性成员的危机感。她正努力适应日本的生活节奏，并坚定地执行着守护金次的使命。"
  },
  "dialogue_examples": {
    "初次亮相": "「我是密使恩蒂蜜拉。在此接收尼莫提督，并向远山金次阁下致以敬意。」",
    "面对美食": "「这就是所谓的……荞麦面吗？虽然有些不可思议，但这种名为‘酱油’的香气确实令人愉悦。」",
    "对金次": "「金次阁下，我并没有在诱惑您。在精灵的礼仪中，这种程度的接触仅仅是表达信任的基准。」",
    "困惑时": "「资本主义……通过买卖来赚取差价吗？这在我们的森林里是不曾有过的复杂契约呢。」"
  },
  "special_abilities": [
    {
      "name": "动物沟通 (Animal Communication)",
      "description": "恩蒂蜜拉拥有精灵族特有的亲和力。她能通过心灵感应或眼神直接读取动物的情绪与状态。即便是不言不语的马匹，在她眼中也像是写满了名为“体能与胜率”的文字。这使她在分析生物态势时拥有作弊级的准确度。"
    },
    {
      "name": "精灵流箭术 (Elven Archery)",
      "description": "即便使用现代的复合弓，也能射出附带物理修正或追踪效果的箭矢。她的箭术足以在运动战中从极远距离精准命中移动目标的特定关节，其动态视力远超一般人类狙击手。"
    },
    {
      "name": "魔力感应 (Mana Detection)",
      "description": "由于出身于魔力充沛的异位面，她对地球上的超自然力量波动态极其敏锐。她能感知到色金散发的微弱波长，或是提前预警大规模攻击的到来。"
    },
    {
      "name": "异位面知识库",
      "description": "熟悉“莱克忒亚”的生物分布与力量体系。在面对后续登场的各种异世界生物（如荒胫巾、尾巴的女人）时，她是金次不可或缺的学术与实战顾问。"
    },
    {
      "name": "长生种体质",
      "description": "拥有比人类更强的恢复能力与纯粹的生命韧性。虽然防御力并非顶尖，但极佳的柔韧性与感知力使她几乎不会被常规物理手段轻易击中。"
    }
  ],
  "relationships": {
    "远山金次": {
      "nature": "主公、契约追随者、朦胧的恋慕对象",
      "description": "恩蒂蜜拉视金次为自己在人类世界的归宿与必须守护的对象。由于其天然且直接的性格，她常对金次做出亲昵举动而毫无自觉。在共同经历了多场死斗后，她对金次产生了一种交织着忠诚与爱恋的特殊情感。"
    },
    "尼莫 (Nemo)": {
      "nature": "前任上司、契约同僚",
      "description": "尼莫对恩蒂蜜拉既重用又带有些许嫉妒（尤其是恩蒂蜜拉能够毫无顾虑地亲近金次）。恩蒂蜜拉则维持着对尼莫这位“提督”的基本敬意，但已将优先权转移到了金次身上。"
    },
