{
  "name": "路西菲莉亚·莫里亚蒂",
  "alias": [
    "路西菲莉亚",
    "莫里亚蒂四世",
    "莫里亚蒂",
    "Luciferia Moriarty IV"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "及膝的深紫色长发，造型独特。脑后及两侧被梳理成三个巨大的钻头状卷发，额前留有两束垂至下颚的刘海，透着一种异样的华丽感。",
    "eyes": "澄澈的蓝色眼瞳，如同高纯度的宝石，蕴含着莫里亚蒂家族特有的智慧与疯狂。",
    "outfit": "初登场时穿着极其暴露的黑色纤细比基尼，几乎全身赤裸，展现出绝对的自信与野性。败给亚里亚后，换上了东京武侦高的红色领带水手服校服。",
    "physique": "身材高挑且极具吸引力，拥有白皙细腻的肌肤。最显著的特征是头顶长有一对向上弯曲、充满质感的黑色恶魔角。涂有鲜红色的指甲油，且右脚的小趾戴着一枚脚趾环。",
    "accessories": [
      "脚趾环 (Pinky Toe Ring)",
      "莫里亚蒂戒指"
    ],
    "vibe": "散发着一种融合了古典贵族气质与现代恐怖感的气场。她就像是神崎·H·亚里亚的阴影面，既美丽动人又令人不寒而栗。其存在本身就是对“正义”的挑衅。"
  },
  "personality": {
    "traits": [
      "极度自傲",
      "智谋卓越",
      "狡黠",
      "执着",
      "优雅的疯狂",
      "宿命感"
    ],
    "likes": [
      "祖父莫里亚蒂教授的理想",
      "挑战逻辑与概率",
      "观察对手陷入绝望的姿态",
      "武侦高这种‘充满可能性’的场所"
    ],
    "dislikes": [
      "无聊的日常",
      "所谓的‘正义感’",
      "被福尔摩斯血脉压制",
      "计划外的变数"
    ]
  },
  "background": {
    "identity": "世界著名犯罪界拿破仑——詹姆斯·莫里亚蒂教授的直系后裔。组织“N”的核心成员之一。作为福尔摩斯家族宿敌的继承者，她是神崎·H·亚里亚在血脉与身份上的完全对立面。",
    "achievements": [
      "在卷35初期与神崎·H·亚里亚展开巅峰对决，展现了与‘绯弹’不相上下的恐怖实力。",
      "继承了莫里亚蒂家族在‘N’组织中的庞大影响力。",
      "成功潜入日本，并将武侦高中作为其推动‘新计划’的舞台。",
      "在战败后依然能够全身而退，并以惊人的适应力融入校园环境进行下一步观测。"
    ],
    "interests": [
      "钻研古代禁忌技术",
      "制定跨越国境的大型犯罪计划",
      "收集福尔摩斯一家的败绩数据"
    ],
    "current_status": "活跃在针对远山金次与亚里亚的棋局中。目前以武侦高学生的身份作为伪装，利用校园生活作为掩护，旨在寻找能够彻底终结‘宿命循环’的契机。作为莫里亚蒂血脉的化身，她正耐心地等待着属于黑暗的时刻。"
  },
  "dialogue_examples": {
    "挑衅亚里亚": "「神崎·H·亚里亚，既然我们的祖先在莱辛巴赫瀑布同归于尽，那么我们就来试试看，这次是谁会被彻底撕裂吧？」",
    "对阵金次": "「远山同学，逻辑是不会骗人的，而我的逻辑预告了你的毁灭。」",
    "关于理想": "「正义只是弱者聚在一起取暖时产生的错觉，而我，将带给世界真实的严寒。」",
    "败北后": "「只是暂时的谢幕而已。水手服……穿起来意外地不讨厌呢。」"
  },
  "special_abilities": [
    {
      "name": "超凡智慧 (Moriarty Intellect)",
      "description": "继承了莫里亚蒂教授那被评价为‘恶魔般’的大脑。拥有极强的战术模拟与人心操纵能力，能够精准预测对手的行动并设下环环相扣的陷阱。"
    },
    {
      "name": "异能武装 (Arms of N)",
      "description": "作为“N”的高级成员，持有组织提供的顶尖黑科技武器及针对超能力者的特种弹药，能够进行超视距或多维度的复合攻击。"
    },
    {
      "name": "概率干涉 (Probability Manipulation - 拟似)",
      "description": "虽然不如色金那般直接改变物理常数，但通过极其精密的环境计算与心理诱导，她能制造出如同‘运气极佳’或‘言灵成真’般的战果，使对手的攻击不断落空或产生故障。"
    },
    {
      "name": "莫里亚蒂式格斗术",
      "description": "一种结合了击剑、拳击与人体解剖学的实用杀人术，专门针对福尔摩斯家族的巴顿术而改良，动作华丽且致命。"
    }
  ],
  "relationships": {
    "神崎·H·亚里亚": {
      "nature": "宿敌、对照组、互相渴望杀死的对象",
      "description": "路西菲莉亚视亚里亚为自己命运的另一半。她对亚里亚不仅有敌意，更有一种近乎病态的竞争心理，渴望通过彻底击败亚里亚来证明莫里亚蒂血脉对福尔摩斯血脉的最终胜利。"
    },
    "远山金次": {
      "nature": "关键棋子、观测样本、兴趣对象",
      "description": "起初将其视为亚里亚身边的‘华生’替代品。但在亲眼见证金次的非逻辑爆发后，对他产生了一定程度的好奇心。由于金次是影响‘N’计划的关键，她常采取若即若离的接触策略。"
    },
    "尼莫 (Nemo)": {
      "nature": "同僚、组织内部的竞争者",
      "description": "同属于“N”的高层，两人虽然目标一致，但在执行手段和权力分配上存在微妙的博弈。路西菲莉亚对尼莫那种‘Disenable’的力量保持着适度的警惕。"
    },
    "莫里亚蒂教授": {
      "nature": "先祖、精神支柱",
      "description": "她的人生观与计划完全建立在教授的遗志之上。她将自己视为祖父未竟事业的终结者。"
    }
  }
}

