entries.content:
  "name": "山根云雀",
  "alias": [
    "山根记者",
    "山根酱"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "黑色的短发，长度及颈，显得干练且锐利。",
    "eyes": "明亮的黄色瞳孔，透着一种新闻从业者特有的审视感与知性。",
    "outfit": "通常穿着职场感十足的深色女性商务西装，但在这种严肃的装扮下，有时会搭配一件带有连帽衫（Hoodie）性质的内衬，展现出一种混搭的非传统气质。在美滨外语高中潜伏时，会穿着该校的校服。",
    "physique": "身高170cm。对于一名高中生年纪的女性来说相当高挑，身形苗条，肤色白皙，整体给人一种理性且冷淡的都市感。",
    "accessories": [
      "高端数码单反相机/隐蔽摄像机",
      "智能手机",
      "记者证（文秋周刊）"
    ],
    "vibe": "外表看起来像是个严肃、沉稳且具有职业道德的职场女性，但实际上拥有极强的行动力与潜伏能力。她身上散发着一种“为了头条不择手段”的冰冷危险感，对于武侦系统持怀疑乃至敌视的态度，是典型的揭露真相型人物。"
  },
  "personality": {
    "traits": [
      "执着",
      "现实主义",
      "毒舌",
      "观察力敏锐",
      "潜行高手",
      "新闻至上"
    ],
    "likes": [
      "具有冲击力的新闻头条",
      "揭开武侦的社会阴暗面",
      "观察目标的破绽",
      "有深度的独家采访"
    ],
    "dislikes": [
      "武侦制度下的暴力行为",
      "真相被掩盖",
      "无能的采访对象",
      "被威胁"
    ]
  },
  "background": {
    "identity": "日本著名八卦周刊《文秋周刊》的资深记者。尽管外表看起来只有17岁左右，但其职业生涯已有数年。她曾因深度报导远山金一（加奈）的相关丑闻而声名大噪，对远山一族有着深入的调查基础。",
    "achievements": [
      "曾成功挖掘并报导了前S级武侦远山金一的失踪与相关黑历史，对武侦界的声誉造成了重大打击。",
      "成功潜入防卫极其森严的美滨外语高中，并精准锁定了远山金次的动向。",
      "在美滨高的高一人气投票中（尽管她是高二）因其‘阴沉’和‘难以捉摸’的气质获得某种层面的关注。",
