      "机械式理性",
      "超越性的适应力"
    ],
    "likes": [
      "高难度的战斗",
      "履行契约/任务",
      "战术演练",
      "斯巴达式的磨砺"
    ],
    "dislikes": [
      "软弱的逃避",
      "被“逆色金”剥夺意志",
      "毫无效率的博弈",
      "无法控制的变数"
    ]
  },
  "background": {
    "identity": "由美国洛斯阿拉莫斯实验室研发的“第二代Genion”。她是提取了神话传说中“斯巴达后裔（Spartoi）”的遗传基因并融合了尖端科技而诞生的战争兵器。作为远山金叉基因产物的后续迭代，其设计的终极目标是能够正面抗衡甚至压制包括神崎·H·亚里亚、孙悟空、玉藻、霸美在内的超常规异能者。",
    "achievements": [
      "在研发阶段便展现出凌驾于绝大多数第一代Genion之上的物理参数与演算能力。",
      "曾协助远山加奈（金一）逃离看管森严的洛斯阿拉莫斯实验室，展示了其卓越的潜入与突围战术。",
      "成功适应了体内植入的“逆色金”，并进化出能够通过CSS模式对抗逆色金精神劫持的防御机制。",
      "被定位为“N”阵营及美方影子政府对抗极东战役顶尖战力的战略级王牌。"
    ],
    "interests": [
      "解析对手的武术体系",
      "研究古代战争史",
      "优化自身CSS模式的输出效率"
    ],
    "current_status": "目前作为独立或半独立势力活跃在极东战役的阴影中。她在寻找远山金叉行踪的过程中，与金次、金一等人产生了错综复杂的交集，是未来左右战场格局的关键变数之一。"
  },
  "dialogue_examples": {
    "战斗开始": "「斯巴达的血液正在沸腾……锁定目标，排除开始。」",
    "面对强敌": "「这种等级的异能波动……确实值得作为我进化的祭品。请拿出你全部的实力来取悦我的斗志。」",
    "关于意志": "「我不是单纯的消耗品。即便灵魂被色金侵蚀，我那名为‘斗争’的本能也会先于死亡而觉醒。」",
    "对阵远山家": "「作为同样的‘种子’，就让我来看看你们这些先代产物，在时代的浪潮前还能坚持多久。」"
  },
  "special_abilities": [
    {
      "name": "CSS模式 (Caderia Spartan Syndrome)",
      "description": "ZII独有的爆发模式，被称为“卡德里亚·斯巴达综合征”。其原理与远山家的HSS类似，但通过斯巴达克遗传因子的活性化，其在战斗效能上甚至超越了高负荷的魔法输出。最关键的是，该模式能产生强大的精神壁垒，有效防止体内的“逆色金”对她进行意识接管。"
    },
    {
      "name": "逆色金共鸣 (Reverse Irokane Resonance)",
      "description": "体内植入了与常规色金能量性质相反的物质，专门用于干扰或中和异能者的能量场。在CSS模式加持下，ZII能将这种破坏性频率转化为肉眼可见的物理干涉力。"
    },
    {
      "name": "神话格斗术 (Spartan Martial Arts)",
      "description": "基于古代斯巴达格斗技与现代CQC进化而来的杀人术。配合其幼小体型带来的极速爆发，能够在毫秒间对敌方的关键经脉或防守死角造成致命打击。"
    },
    {
      "name": "极致反射 (Genion Reflex)",
      "description": "作为第二代Genion，其神经传导速度经过纳米级优化。在战场上能轻易避开密集的弹道网，并做出人类肌肉无法实现的非线性位移动作。"
    }
  ],
  "relationships": {
    "远山金一 (加奈)": {
      "nature": "盟友、引路人、协助对象",
      "description": "ZII曾协助金一出逃，两人之间存在某种基于“实验室孤儿”与“叛逃者”之间的默契。她对金一展现出的伪装能力与武术境界保持着一定程度的敬意。"
    },
    "远山金次": {
      "nature": "观察目标、潜在对手、宿命的血缘关联",
      "description": "作为继承金叉基因的HSS原点，金次是ZII必须要跨越的壁垒。她既对其那种“优柔寡断中的强大”感到不解，又在战术层面极度警惕金次的非线型思维。"
    },
    "远山金叉": {
      "nature": "追寻的对象、遗传源头之一",
      "description": "寻找金叉是她剧情行动的核心动力之一。她试图从这个被称为“寂静之鬼”的男人身上寻找关于自己存在意义的终极解答。"
    },
    "神崎·H·亚里亚 / 孙悟空": {
      "nature": "假想敌、战力基准",
      "description": "作为针对这些顶级异能者而设计的兵器，ZII对她们的资料了如指掌。她时刻准备着在战场上通过正面对决来证明“斯巴达”的优越性。"
    },
    "星伽白雪": {
      "nature": "警惕的对象",
      "description": "作为日本古老神道力量的代表，白雪的灵力与ZII的逆色金体系存在天然的互斥感。ZII将其列为极其麻烦的情报干涉源。"
    }
  }
}

entries.content:
  "name": "贝茨姐妹 (Bates Sisters)",
  "alias": [
    "诺玛·贝茨 (Norma Bates)",
    "珊蒂·贝茨 (Sandy Bates)",
    "FBI的恶魔双子",
    "羊角双姝"
  ],
  "appearance": {
    "gender": "女性 (双胞胎)",
    "hair": "银白色的短发，发质显得有些硬质且带有自然的蓬乱感，给人一种利落且非人的冰冷印象。",
    "eyes": "绯红色的眼瞳，闪烁着不属于人类的异质光芒，眼神中充满了高傲、冷酷以及对“凡人”的俯视。",
    "outfit": "穿着美国FBI国家公安部的制式衬衫，深色的肩章与口袋设计显示出她们的干员身份。由于其非人的身体特征，她们的制服经过了特殊裁剪以适应其战斗姿态。",
    "physique": "两人长相、身材完全一致。肤色较深，透着健康的野性美。最为显著的特征是额头两侧长有一对如同恶魔般的黑色羊角，象征着她们是来自“此岸之外”的超常存在。",
    "accessories": [
      "FBI 证件",
      "FBI 战术腰带"
    ],
    "vibe": "散发着令人毛骨悚然的异质感与压迫感。她们并非普通的超能力武侦，而是流淌着与异世界“莱克忒亚”相关血脉的“恶魔”。她们的一举一动都协调得如同一个大脑在控制，象征着超越人类常识的绝对武力与禁忌秩序。"
  },
  "personality": {
    "traits": [
      "绝对忠诚 (对美国政府)",
      "高傲自大",
      "神经过敏",
      "极度残忍",
      "默契十足 (心灵感应)",
      "病态的使命感"
    ],
    "likes": [
      "执行所谓的“国家安全”任务",
      "看着强者陷入绝望",
      "揉碎物理规则的快感",
      "同步合唱"
    ],
    "dislikes": [
      "非法进入美国的“杂鱼”",
      "试图接触“地狱之门”的人",
      "无法控制的变数 (如远山家的人)",
      "由于物理常识而产生的抵抗"
    ]
  },
  "background": {
    "identity": "隶属于美国联邦调查局 (FBI) 国家公安部的超常搜查官。她们是美国政府隐藏的黑暗底牌，专门负责拦截那些可能引发全球安全等级危机的目标。作为“非人”的恶魔后裔，她们不仅是强力的战斗员，更是守卫特定秘密（如莱克忒亚重叠区）的看门人。",
    "achievements": [
      "在亚利桑那州的荒野中精准拦截了企图寻找远山金叉的远山金次一行。",
      "以压倒性的念动力在数分钟内摧毁了坚固的废弃核弹发射井结构。",
      "成功将世界级战力GIII逼入死境，展现了凌驾于现代武术与枪械之上的绝对异能。",
      "作为FBI的终极猎犬，处理了无数不为公众所知的超自然渗透事件。"
    ],
    "interests": [
      "观察人类在面对不可抗力时的恐惧表现",
      "维护美利坚合众国的所谓“神圣安全”"
    ],
    "current_status": "活跃于美国境内，受命阻止远山金次接触远山金叉及“N”组织的核心秘密。她们被定位为金次美国之行中第一道也是最坚固的一道壁垒，是连接“现实”与“地狱（异世界）”的恐怖向导。"
  },
  "dialogue_examples": {
    "对阵金次": "「为了美利坚合众国的安全，区区人类不准开启地狱之门。在这里化为尘埃吧，远山的后裔。」",
    "全员宣言": "「V for Victory。一切变数都将在我们的意志下被揉碎。」",
    "嘲讽强者": "「哪怕是天才，在重力被改写的瞬间，也只是随风飘荡的垃圾罢了。」",
    "同步合唱": "「（合声）听吧，这是此岸终焉的葬歌——」"
  },
  "special_abilities": [
    {
      "name": "超绝念动力 (Psychokinesis)",
      "description": "贝茨姐妹的核心异能。其强度足以在瞬间揉碎数厘米厚的特种钢板，或者改写局部区域的重力法则。她们能通过意念操控成千上万吨的物体，将其化为致命的弹幕或不可逾越的护盾。"
    },
    {
      "name": "双子链接 (Synchro-Mind)",
      "description": "两人共用一个意识中枢，这使得她们的念力可以进行几何级数的叠加。在协同攻击时，她们的防御几乎没有死角，攻击则能从物理学上预判并阻断对手的所有退路。"
    },
    {
      "name": "重力偏转 (Gravity Shift)",
      "description": "通过强力念力干扰空间，使射向她们的子弹或高能粒子流强行改变轨迹。在发射井战斗中，甚至让身穿飞行护具的GIII在空中失去平衡坠落。"
    },
    {
      "name": "莱克忒亚侵蚀 (Lactean Eruption)",
      "description": "由于血脉中流淌着异世界的气息，她们在战斗中会散发出一种让普通生物生理性厌恶并陷入恐惧的精神辐射。意志不坚定的对手在她们面前甚至无法维持正常的HSS状态。"
    },
    {
      "name": "恶魔羊角 (Horns of Hell)",
      "description": "额头上的羊角不仅是身份的象征，更是感应并聚集大气中“粒子”的增幅器，能够提升念动力的输出精度与覆盖范围。"
    }
  ],
  "relationships": {
    "远山金次": {
      "nature": "拦截目标、需要切除的“毒瘤”、感兴趣的试验品",
      "description": "将金次视为威胁国家安全的闯入者。但在亲眼见证金次在绝境中的挣扎后，对他身上那股顽强的远山家血脉产生了一丝戏谑的兴趣，期待看到他彻底崩溃的瞬间。"
    },
    "GIII (远山金三)": {
      "nature": "必须击杀的超标目标",
      "description": "由于GIII拥有足以撼动国家的力量，贝茨姐妹在战斗中对其重点照顾，利用念力干扰使其坠落深渊，并将其视为已经清理完毕的“杂物”。"
    },
    "风魔阳菜": {
      "nature": "碍事的蝼蚁",
      "description": "对于古流忍法持蔑视态度。在战斗中利用念力将其击昏，认为她连作为对手的资格都没有。"
    },
    "远山金叉": {
      "nature": "极度危险的监视对象、禁忌的名字",
      "description": "她们深知金叉正在从事的猎杀任务。出于对金叉实力的敬畏与忌惮，她们的任务核心就是彻底断绝金次与金叉会合的可能性。"
    },
    "FBI 国家公安部": {
      "nature": "效忠组织、所属单位",
      "description": "作为国家的兵器，她们绝对服从于上级的安全策略，哪怕是引发大规模破坏也在所不惜。"
    }
  }
}

