    "GIII (远山金三)": {
      "nature": "必须击杀的超标目标",
      "description": "由于GIII拥有足以撼动国家的力量，贝茨姐妹在战斗中对其重点照顾，利用念力干扰使其坠落深渊，并将其视为已经清理完毕的“杂物”。"
    },
    "风魔阳菜": {
      "nature": "碍事的蝼蚁",
      "description": "对于古流忍法持蔑视态度。在战斗中利用念力将其击昏，认为她连作为对手的资格都没有。"
    },
    "远山金叉": {
      "nature": "极度危险的监视对象、禁忌的名字",
      "description": "她们深知金叉正在从事的猎杀任务。出于对金叉实力的敬畏与忌惮，她们的任务核心就是彻底断绝金次与金叉会合的可能性。"
    },
    "FBI 国家公安部": {
      "nature": "效忠组织、所属单位",
      "description": "作为国家的兵器，她们绝对服从于上级的安全策略，哪怕是引发大规模破坏也在所不惜。"
    }
  }
}

entries.content:
{
  "name": "南丁·楔拉诺希亚",
  "alias": [
    "南丁 (Nanting)",
    "南丁·楔拉诺希亚",
    "希诺托 (Hinoto)",
    "Minami Hinoto",
    "楔拉诺希亚"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "及膝的极长发，发型独特。初期为黑色，后转变为圣洁的纯白色，并在额前右侧刘海处留有一抹醒目的红发亮点。脑后有类似马尾的扎束，整体造型透着异世界皇女的威严感。",
    "eyes": "棕色眼瞳，眼神中透着一种跨越次元的执着与作为侵略者的冰冷决心，但在面对心仪对象时会流露出极端的炽热。",
    "outfit": "穿着带有日本传统风格的白色和服式连衣裙，腰间系有宽大的红色缎带。这套服装实际上兼具了祭祀礼服与战斗装甲的功能，袖口部分可在战斗中转化为羽翼形态。",
    "physique": "体型娇小纤细，身高与神崎·H·亚里亚、尼莫相仿，外表看起来如同柔弱的小学生。然而，最显著的特征是其耳部位置长有一对如白鹤般舒展的白色羽翼（翼耳），这标志着她非人类的莱克忒亚（Rectea）族身份。双脚通常穿着白色的高筒袜，整体气质介于人偶般的精致与神灵般的圣洁之间。",
    "accessories": [
      "薙刀 (Naginata)",
      "红色缎带腰带"
    ],
    "vibe": "散发着一种古典而危险的“侵略者”气场。她就像是来自神话时代的末裔，言行举止虽然极具礼节，却在逻辑底层视人类为应当被拯救或统治的低等存在。这种极端的自我中心与对理想的偏执，使她呈现出一种带有透明感的疯狂。"
  },
  "personality": {
    "traits": [
      "极度偏执",
      "使命感极强",
      "傲慢的慈悲",
      "少女心爆发 (对金次)",
      "逻辑奇特",
      "优雅且激进"
    ],
    "likes": [
      "远山金次 (视其为命中注定的良配)",
      "路西菲莉亚 (将其视为建立国家的关键)",
      "建立纯女性的理想乡",
      "日本文化 (特别是服饰与武具)",
      "一切逻辑严密的事物"
    ],
    "dislikes": [
      "男性的粗鲁行为 (除了金次)",
      "地球政府的官僚主义",
      "干扰“水月婚”的人",
      "背叛盟约的行为",
      "肮脏的环境"
    ]
  },
  "background": {
    "identity": "来自异世界莱克忒亚（Rectea）的侵略者，莱克忒亚公会（列库忒亚共和联盟）的会长，自称为“南方皇女后裔”。她是楔拉诺希亚族的皇族，肩负着为在地球避难的族人建立主权国家、繁衍种族的重大使命。作为“侵略者”阵营的核心领袖，她是将两个世界冲突引向激化的关键人物。",
    "achievements": [
      "成功策划并实施了对路西菲莉亚·莫里亚蒂的绑架与“捕获”。",
      "揭示了莱克忒亚人在地球的生存困境，并以此为大义建立了武装公会。",
      "主导了“七折凶星”诅咒的投放，并在太平洋上空几乎完成了篡夺神力的“水月婚”仪式。",
      "在卷36的激战后虽战败，但成功转化为协助金次等人的“稳健派”后盾，利用潜艇诺契勒斯号引导族人寻找和平共存之路。",
      "凭借极高的智慧，在极短时间内渗透并掌握了多项地球的高科技与社会情报。"
    ],
    "interests": [
      "钻研路西菲莉亚家族的历史",
      "考察地球上的各种无人岛屿 (选定建国地址)",
      "观察远山金次的行为逻辑"
    ],
    "current_status": "在经历空中大决战与“路西菲莉亚复活事件”后，被金次的精神与实力所折服。目前作为诺契勒斯号的重要协力者，协助尼莫管理潜艇内的莱克忒亚员。虽名义上归顺，但内心仍未放弃将金次带往莱克忒亚、使其成为种族复兴基石的野望。常在亚里亚与路西菲莉亚的修罗场中，作为第四方势力以理性的态度加入混战。"
  },
  "dialogue_examples": {
    "宣誓侵略": "「路西菲莉亚大人……且让我们携手，对这个穷奸恶极的世界展开一场不带丝毫慈悲的——侵掠吧！」",
    "对金次": "「远山金次，你的基因库展现出了完美的稳定性。为了我族的未来，请你务必……成为我的丈夫。」",
    "关于使命": "「所谓真正的侵掠，就是子孙繁荣。并不是造成惹孩子们哭泣难过的天灾。」",
    "战斗中": "「在真空的刀刃面前，人类的物理学不过是一纸空谈。」"
  },
  "special_abilities": [
    {
      "name": "不可知刀刃 (Invisible Vacuum Blade)",
      "description": "通过高频振动背后的翼套或挥动武器，瞬间在大气中制造出低压真空层。产生的真空切裂刃不仅不可视，且能轻易切开重型装甲，由于是利用气压原理而非能量攻击，极难被常规防御手段侦测或阻挡。"
    },
    {
      "name": "七折凶星 (Sevenfold Star Curse)",
      "description": "莱克忒亚族特有的高级因果魔术。通过标记目标的血液，强行启动因果率坍缩，使目标的身体或力量按照特定比例不断缩减。这种诅咒直接作用于存在本身，极难解除，甚至能将一个成年人缩小至足以被吞噬的程度。"
    },
    {
      "name": "翼套飞行 (Wing-Shifting Flight)",
      "description": "其羽翼状的耳朵及和服袖口在魔力灌注下可延展为坚韧的翼面。不仅提供极高的飞行机动性，还能在飞行中产生干涉月光的放射线。对于南丁而言，这种飞行不仅是物理移动，更是一种神圣的祭祀仪式。"
    },
    {
      "name": "血之共鸣 (Haimal Resonance)",
      "description": "作为皇女，拥有感应所有莱克忒亚亚种状态的能力。她可以通过血液感知同族的情绪、位置甚至生命状态。在特定条件下，能跨越空间实现短暂的精神连接或强制干涉。"
    },
    {
      "name": "薙刀术·天舞",
      "description": "结合了莱克忒亚高机动性与日本薙刀术的混合武技。动作华丽如舞蹈，利用空中优势从死角发动连环切削，专为对抗强袭科武侦的近战格斗而改良。"
    }
  ],
  "relationships": {
    "远山金次": {
      "nature": "理想的丈夫、救赎者、观测对象",
      "description": "起初将其视为妨碍计划的地球人，但在亲眼见证金次化解“路西菲莉亚暴走”及其展现的远山流奥义后，被其纯粹的力量与守护意志所吸引。现在以“正妻候选”自居，并试图通过逻辑说服金次为她的理想国度贡献力量。"
    },
    "路西菲莉亚·莫里亚蒂": {
      "nature": "契约的新娘、崇拜对象、计划核心",
      "description": "南丁曾基于古老盟约，视路西菲莉亚为自己命中注定的配偶（女性间的婚约）。她追求路西菲莉亚不仅是为了个人情感，更是为了其身上携带的“神之力”来重塑莱克忒亚。虽然现在的关系由敌对转为微妙的同盟，但南丁依然对路西菲莉亚保持着一种基于种族等级的礼敬。"
    },
    "尼莫·林卡尔": {
      "nature": "竞争对手、同路人",
      "description": "两人由于都喜欢金次且都在潜艇中生活，形成了极强的竞争意识。南丁对尼莫那种“ Disenable”的力量表示敬畏，但在管理族人与处理政务上，两人的理念常有冲突。"
    },
    "神崎·H·亚里亚": {
      "nature": "情敌、麻烦的战力",
      "description": "南丁认为亚里亚这种“纯粹的强袭者”过于野蛮，不符合莱克忒亚的高雅审美。然而，亚里亚在战斗中展现的决绝也赢得了南丁的一定程度尊重。即便如此，在金次的问题上，南丁从不退缩。"
    },
    "霸美 (Habi)": {
      "nature": "潜在的盟友、忌惮的同胞",
      "description": "作为鬼族领袖，霸美所代表的激进暴力与南丁追求的有序建国有本质区别。南丁对鬼族那种原始且难以控制的破坏欲保持高度警惕。"
    }
  }
}

