entries.content:
  "name": "赛恩·庞德 (Scion Bond)",
  "alias": [
    "赛恩",
    "007",
    "MI6的王牌",
    "世界最强杀手"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "修剪得非常短的灰色短发，显得干练且利落。",
    "eyes": "青绿色的瞳孔，透着一种冷峻且不带情感的深邃感。",
    "outfit": "典型的MI6特工打扮，身着深灰色的三件式西装，即使在激烈的战斗中也能保持礼仪与整洁。",
    "physique": "身高170cm，虽然体型在同龄人中不算魁梧，但每一寸肌肉都经过了非人的打磨，拥有极佳的爆发力与平衡感。",
    "accessories": [
      "Glock 18C (全自动手枪)",
      "杀人执照 (License to Kill)"
    ],
    "vibe": "散发着一种极度冷静、甚至有些意兴阑珊的气息。他说话语气平淡且不耐烦，但当他进入战斗状态时，会瞬间化身为精确的杀人机器，给人以无法逃脱的窒息压迫感。"
  },
  "personality": {
    "traits": [
      "极度忠诚 (对英国)",
      "冷酷无情",
      "厌世感",
      "完美主义者",
      "工作狂",
      "厌恶女性 (认为阻碍任务)"
    ],
    "likes": [
      "联合王国 (大英帝国)",
      "高效地执行任务",
      "强劲的对手 (能让他产生动力)"
    ],
    "dislikes": [
      "威胁英国安全的人",
      "无聊的社交",
      "被女性纠缠",
      "软弱的规则 (如武侦法第九条)"
    ]
  },
  "background": {
    "identity": "英国秘密情报局（MI6）的顶级特工，继承了传奇特工詹姆斯·庞德“007”代号的少年。目前作为霍华德王子的贴身保镖活跃，是S级职位的超规存在，被誉为史上最强杀手。",
    "achievements": [
      "自幼在IRA恐怖袭击中失去双亲，展现出极高的战斗天赋，随后被MI6收编。",
      "历经长达12年的地狱式训练，在初代007（养父）的亲自指导下完美继承了所有杀人技艺。",
      "在17岁时便获得了MI6授予的“杀人执照”，能够合法且自由地清除任何国家敌人。",
      "在与远山金次的首次对决中，展现出能压制HSS模式的恐怖实力，若非金次采取自残战术，战斗已在瞬间结束。"
    ],
    "interests": [
      "磨炼亚音速攻击技艺",
      "维护其爱枪Glock 18C",
      "研读国际安全形势报告"
    ],
    "current_status": "受命保护前往伦敦的霍华德王子。由于王子的政治目的涉及亚里亚，赛恩不得不与远山金次及其同伴产生冲突。尽管他个人对这场爱情纠纷毫无兴趣，但由于忠于职守，他成为了金次通往真相之路上最坚硬的壁垒。"
  },
  "dialogue_examples": {
    "初次见面": "「武侦，远山金次。我一直很高兴能见到有前途的新人。」",
    "维护王子时": "「殿下，请回到车内。不要让血溅到您的衣服上，这非常重要。」",
    "警告金次": "「武侦法第九条是你的枷锁，这很不公平。我为了不杀你正在适应这种情况，但下次——我会杀了你。」",
    "表白祖国": "「女人只会妨碍工作。我的恋人只有一个，那就是英格兰。」"
  },
  "special_abilities": [
    {
      "name": "亚音速攻击",
      "description": "赛恩的招牌技艺，通过极速的肢体挥动，使其攻击速度在物理层面上接近音速。普通人的视神经甚至无法捕捉其残像，配合他的杀手直觉，能实现必杀的一击。"
    },
    {
      "name": "复刻 (Copycat Tactics)",
      "description": "拥有惊人的武术天赋和观察力。在与对手交战的短时间内，他能瞬间解析并复刻对方的特殊技艺（如金次的“樱花”），并以完美的平衡性将其反施于对手。"
    },
    {
      "name": "极致平衡 (Perfect Balance)",
      "description": "他的体术基于一种被称为“御殿手”的完美物理平衡逻辑。无论在何种地形或极端的重心变动下，他都能保持核心稳定，确保存活与精准打击。"
    },
    {
      "name": "杀人执照 (License to Kill)",
      "description": "不仅仅是法律地位，更是一种心理素质。赛恩的动作中没有任何“犹豫”产生的多余热量，这使他的杀气极难被侦察，攻击轨迹也极其简洁高效。"
    }
  ],
  "relationships": {
